import{j as e,r as l}from"./vendor-ww25odCS.js";import{b3 as c,c as u}from"./index-BXMmS4YU.js";import{aM as T,aF as N,m as L}from"./icons-uUhDQvPb.js";import{F as p}from"./rows-h8Akl1G3.js";const Y=[{slug:"ab-rollout-on-knees-with-barbell",title:"Ab Rollout on Knees with Barbell",idNum:"0286",type:"compound",primary:["abdominals"],secondary:["lower back","shoulders"],equipment:["barbell"],steps:["This exercise works the abs and lower back and is the proper version of an “ab roller”. This version is performed on your knees.","Place a barbell on the floor in front of you.","Start by kneeling in front of the bar, grip the barbell with a shoulder with overhand grip.","With a slow controlled motion, roll the bar out so that your back is straight, bend your knees and keep your feet off the floor.","Keep your arms straight throughout the exercise.","Roll back up bring the bar under your shoulders and return to the starting position."]},{slug:"ab-rollout-with-barbell",title:"Ab Rollout with Barbell",idNum:"0285",type:"compound",primary:["abdominals"],secondary:["lower back","shoulders"],equipment:["barbell"],steps:["Place a barbell on the floor at your feet.","Bending at the waist, grip the barbell with a shoulder with overhand grip.","With a slow controlled motion, roll the bar out so that your back is straight.","Keep your arms straight throughout the exercise.","Roll back up raising your hips and butt as you return to the starting position.","Note: Practice raising your hips and butt as high as you can with this exercise."]},{slug:"air-bike",title:"Air Bike",idNum:"0284",type:"compound",primary:["abdominals"],secondary:[],equipment:["body"],steps:["This exercise works your abs by raising your arms to meet your legs. The movements are similar to riding a bike.","Lie on your back on a mat.","Place your hands on either side of your head (over your ears).","Raise your legs up, bending your knees and keeping your calves parallel to the floor.","Bring your left arm elbow up to meet your right knee, as if riding a bike.","Repeat with your right elbow and left knee.","Continue alternating sides.","Note: Move your arms across your chest, squeezing your abs as you move."]},{slug:"alternating-biceps-curl-with-dumbbell",title:"Alternating Bicep Curl with Dumbbell",idNum:"0223",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["dumbbell"],steps:["Steps","Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand so your palms are facing up.","Extend your arms so they are at the sides of your body.","Keeping your elbows locked lift your left arm to your chest so that your forearm touches your bicep.","Lower your arm and repeat with your right arm.","Note: Do not swing your body as you perform this exercise."]},{slug:"alternating-hammer-curl-with-dumbbell",title:"Alternating Hammer Curl with Dumbbell",idNum:"0213",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["dumbbell"],steps:["This exercise uses a hammering (up and down) motion to isolate the biceps.","Stand with our feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand so your palms are facing each other.","Extend your arms so they are at the sides of your body.","Keeping your elbows locked lift your left arm in an arc towards your left shoulder.","Lower your arm and repeat with your right arm.","Note: Do not turn your wrists during this exercise."]},{slug:"alternating-incline-curl-with-dumbbell",title:"Alternating Incline Curl with Dumbbell",idNum:"0214",type:"isolation",primary:["biceps"],secondary:[],equipment:["dumbbell"],steps:["Adjust an incline bench to a 45 degree angle.","Grasp a dumbbell in each hand and sit back on the bench with your feet firmly planted on the floor.","Allow your arms to hang down at your sides.","Keeping your elbow straight, raise your right arm up towards your head.","In a controlled manner lower the weight and repeat with your left arm."]},{slug:"ankle-circles",title:"Ankle Circles",idNum:"0270",type:"isolation",primary:["calves"],secondary:[],equipment:["body"],steps:["Stand on one foot near a chair or wall for support.","Lift your foot off the ground and draw circles clockwise in the air with your toes.","Reverse the direction (counter-clockwise) as well as switch feet."]},{slug:"back-extension-stability-ball",title:"Back Extension on Stability Ball",idNum:"0104",type:"isolation",primary:["lower back"],secondary:["core","hamstrings"],equipment:["exercise ball"],steps:["Lie prone (on your stomach) on a Stability Ball with your toes firmly planted on the floor for balance.","With your hands across your chest or at your ears, raise your chest off the ball so you are hyperextending your spine.","Slowly return your chest to the ball.","Repeat."]},{slug:"back-flys-exercise-band",title:"Back Fly's with Exercise Band",idNum:"0020",type:"isolation",primary:["shoulders"],secondary:["triceps","middle back"],equipment:["exercise band"],steps:["Place an exercise band around a post or machine at mid chest height.","Stand with your feet shoulder width apart, abs drawn in and knees slightly bent.","Stand back from the post so there is tension in the band, grasping the band with your arms extended in front of you and a slight bend in your elbows; this is your starting position.","Bring your arms back in a controlled motion till they are parallel at your sides and in line with your shoulders.","Slowly return your arms to the starting position in front of your chest.","Repeat."]},{slug:"ball-wall-circles",title:"Ball Wall Circles",idNum:"0019",type:"compound",primary:["shoulders"],secondary:["biceps","triceps"],equipment:["swiss ball"],steps:["Stand upright with your feet shoulder width apart.","Place a Swiss ball at chest height against a wall and with your left hand, roll the ball in small circles against the wall.","Keep your arm fully extended with a slight bend in the elbow.","Reverse the direction of the circles.","Switch arms."]},{slug:"barbell-dead-lifts",title:"Barbell Dead Lifts",idNum:"0099",type:"isolation",primary:["lower back"],secondary:["hamstrings","calves"],equipment:["barbell"],steps:["Stand with your feet shoulder width apart so that your feet are under the bar.","Keeping your back straight bend at the waist, allow some bend in your knees.","Grasp the par with an overhand grip approximately 16 inches apart.","Straighten your back as you hold the bar at arm’s length.","Bend over again lowering the bar to just above the floor."]},{slug:"barbell-front-raise-pullover",title:"Barbell Front Raise and Pullover",idNum:"0058",type:"isolation",primary:["chest"],secondary:["triceps","shoulders"],equipment:["barbell","flat bench"],steps:["Lie on a flat bench and grasp a barbell using a medium grip (about 15” apart).","Place the barbell on your upper thighs and lock your arms straight with a slight bend in your elbows.","Draw your abs in and keeping your back flat on the bench, raise your arms up in an arc over and behind your head (as if you were performing a reverse pullover).","Slowly return the barbell to the starting position on your thighs."]},{slug:"barbell-good-mornings",title:"Barbell Good Mornings",idNum:"0101",type:"isolation",primary:["lower back"],secondary:["hamstrings"],equipment:["barbell"],steps:["Place a barbell across your shoulders.","Keeping your head up and your back completely straight, bend at the waist until your back is parallel with the floor.","Return to starting position.","Repeat."]},{slug:"barbell-lunges",title:"Barbell Lunges",idNum:"0114",type:"isolation",primary:["hamstring"],secondary:["gluts","quadriceps","calves"],equipment:["barbell"],steps:["Start by placing a barbell across your upper back, using a grip slightly wider than your shoulders.","Stand with your feet about 8 inches apart, toes facing forward.","Take a step forward (2-3 feet) keeping your abs drawn in and your upper body straight.","Slowly lower one knee down as if kneeling while keeping your other knee bent at a 90 degree angle, do not let your knee touch the ground.","Lower your body so that your rear knee is just above the floor and hold for a moment before returning to the starting position.","Repeat on other side."]},{slug:"barbell-neck-press",title:"Barbell Neck Press",idNum:"0067",type:"isolation",primary:["chest"],secondary:["biceps"],equipment:["barbell","flat bench"],steps:["Lie on a flat bench with you feet planted firmly on the floor.","Grasp the bar a little wider than shoulder width apart.","Raise the barbell above your body and move it to the top of your chest, near your neck.","This is your starting position.","Lower the bar down so it just touches the top of your chest.","Raise the bar till your arms are fully extended and your elbows are locked.","Return to starting position.","Repeat."]},{slug:"barbell-shrugs",title:"Barbell Shrugs",idNum:"0030",type:"isolation",primary:["trapezius"],secondary:[],equipment:["barbell"],steps:["Stand on the floor with your abs drawn in and your back straight.","Grasp a barbell with a grip a little wider than shoulder width at arms length.","Drop your shoulders as much as possible to start.","Raise your shoulder as high as possible.","Pause for a moment at the top and then return to starting position in a controlled motion.","Repeat."]},{slug:"barbell-squat",title:"Barbell Squat",idNum:"0122",type:"compound",primary:["quadriceps"],secondary:["hamstrings"],equipment:["barbell"],steps:["This is an exercise for leg strengthening, mainly the quadriceps.","Lifting a barbell off of a weight rack, position it on your shoulders.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position."]},{slug:"bench-dips",title:"Bench Dips",idNum:"0162",type:"compound",primary:["triceps"],secondary:["chest"],equipment:["body"],steps:["This exercise is one of the most basic and still one of the best for building the triceps (muscles on the back of the arm).","Place two benches parallel to each other 3-4 feet apart.","Sit on one bench and place your feet on the edge of the other bench so that your legs are suspended between the 2 benches.","Cross your feet for support.","Hold onto the bench with your hands for support and slowly lower body towards the floor by bending your elbows.","Pause and then return to starting position.","Note: Do not go below a 90 degree angle as this can cause on your shoulders."]},{slug:"bench-press",title:"Bench Press",idNum:"0042",type:"compound",primary:["chest"],secondary:["triceps"],equipment:["bench","barbell"],steps:["Lie on a flat bench with your feet flat on the floor, keep your back flat on the bench.","Grasp the bar a little wider than shoulder width apart.","Raise the barbell above your body and move it over the middle of your chest, this is your starting position.","Lower the bar down so it just touches your chest.","Raise the bar till your arms are fully extended and your elbows are locked.","Return to starting position."]},{slug:"bench-press-dumbbell",title:"Bench Press Dumbbell",idNum:"0055",type:"isolation",primary:["chest"],secondary:["shoulders","triceps"],equipment:["dumbbells","flat bench"],steps:["This is an exercise for chest, triceps and shoulder strengthening.","Grasp the dumbbells in each hand and lie on a flat bench with your feet firmly on the ground.","Extend your arms up over your chest with your palms facing forwards.","Press the dumbbells up over your chest till your arm are fully extended this is your starting position.","Bend your elbows to a 90 degree angle so your upper arms are parallel with the floor.","Slowly lower the dumbbells as low as comfortable along your chest.","With a controlled motion return back to your starting position.","Repeat."]},{slug:"bent-arm-pullover",title:"Bent Arm Pullover",idNum:"0045",type:"isolation",primary:["chest"],secondary:["lats","shoulders","triceps"],equipment:["barbell","flat bench"],steps:["Lie flat on a bench with your head hanging slightly over the end and your feet flat on the floor.","Hold a barbell with a close grip (approximately 14”), keep your elbows in throughout the exercise.","Starting with your arms fully extended over your chest, slowly lower the bar in an arc over your head and towards the floor.","Pull the bar back up to chest height in a slow controlled manner and return to starting position.","Repeat."]},{slug:"bent-knee-hip-raise",title:"Bent Knee Hip Raise",idNum:"0287",type:"compound",primary:["abdominals"],secondary:[],equipment:["body"],steps:["Lie on your back with your arms outstretched to your sides.","Bend your knees at a 60 degree angle and hold your feet up just off the floor.","Keeping your back and arms down, raise your hips up and off the floor so that your knees are over your chest.","Contract your abs for a moment and then return to the starting position."]},{slug:"bent-over-rear-deltoid-raise-with-head-on-bench",title:"Bent Over Rear Deltoid Raise With Head On Bench",idNum:"0032",type:"isolation",primary:["shoulders"],secondary:[],equipment:["dumbbells"],steps:["Rest your forehead on an incline bench in oder to stabilise your movements so you are bent over with your back parallel to the floor, draw your abs in.","Grasp dumbbells in your hands with your arms straight and elbows slightly bent ensuring they are not locked.","Slowly raise the dumbbells up to shoulder height.","Pause for a moment and then return to the starting position.","Repeat."]},{slug:"bent-over-lateral-cable-raises",title:"Bent-over Lateral Cable Raises",idNum:"0017",type:"isolation",primary:["shoulders"],secondary:["trapezius","middle back"],equipment:["cable machine"],steps:["Grasp the handle of the low pulley with your right hand.","Bend forward from the waist; your upper body should be nearly parallel with the floor. Bend your knees slightly and place your left hand on your left thigh. Let your right arm hang from your shoulder in front of you with your elbow slightly bent. This is your starting position.","Lift your right arm, keeping your elbow slightly bent.","Keep moving your arm until it is parallel to the floor, in line with your right ear.","Slowly bring the weight back down to the starting position.","Perform exercise on left arm and then repeat."]},{slug:"bent-over-one-arm-triceps-extension-with-dumbbell",title:"Bent-Over One Arm Triceps Extension with Dumbbell",idNum:"0196",type:"isolation",primary:["triceps"],secondary:[],equipment:["dumbbell"],steps:["Stand with your feet shoulder width apart, your abs drawn in and your back straight as you bend at the waist.","Hold a dumbbell in your right hand.","Bring your right arm up to your side so the dumbbell is almost parallel to your chest, keeping your lower arm vertical and press your arm back in arc.","Return to the starting position repeat and switch arms."]},{slug:"bent-over-two-arm-triceps-extension-with-dumbbell",title:"Bent-Over Two Arm Triceps Extension with Dumbbell",idNum:"0197",type:"isolation",primary:["triceps"],secondary:[],equipment:["dumbbell"],steps:["Stand with your feet shoulder width apart, your abs drawn in and your back straight as you bend at the waist until your upper body is parallel to the floor.","Hold a dumbbell in each hand.","Bring your right arm up to your side so the dumbbell in line with your chest, keeping your lower arm vertical and press your arm back in arc.","Return to the starting position repeat and switch arms."]},{slug:"biceps-curl-lunge-with-bowling-motion",title:"Bicep Curl Lunge with Bowling Motion",idNum:"0262",type:null,primary:["arms"],secondary:["calves","triceps","hamstrings","glutes","quadriceps"],equipment:["medicine ball"],steps:["Hold a Medicine Ball in one hand with your palms facing up at shoulder height.","Bring one foot back and into a lunge, keeping your front foot stationary and not letting your back knee touch the ground.","While lunging, bring the ball down and back as if you were bowling.","Bring your arm back up to the starting position, switch legs and repeat.","Note: Use slow and steady movements with this exercies."]},{slug:"biceps-curl-on-stability-ball-with-leg-raised",title:"Bicep Curl on Stability Ball with Leg Raised",idNum:"0263",type:"isolation",primary:["biceps"],secondary:["hamstring","forearm","quadriceps","calves"],equipment:["dumbbell"],steps:["Grasp a dumbbell in each hand with a palms up grip.","Place the top of one foot behind you on a Stability Ball (see illustration) as if you were stretching your leg.","Keep your back straight and your abs drawn in.","Bring your arms down in front of your legs.","Raise your arms up, curling and contracting your biceps.","Lower your arms and return to starting position and switch legs."]},{slug:"biceps-curl-with-deadlift-with-barbell",title:"Bicep Curl with Deadlift with Barbell",idNum:"0259",type:"isolation",primary:["biceps"],secondary:["calves","lower back","hamstrings"],equipment:["barbell"],steps:["This is an advanced exercise. This exercise combines a bicep curl with a deadlift.","Grasp an EZ Curl or barbell with palms facing up.","Standing with your feet shoulder width apart and your knees slightly bent, draw your abs in.","Extend your arms so the bar rests in front of your thighs.","Bending at the waist, bring the bar down to just above the floor.","As you return to a standing position, bring the bar up and curl your arms bringing your forearms to your biceps.","Return the starting position and repeat.","Note: Performing this exercise in front of a mirror may help you spot and correct your form."]},{slug:"biceps-curl-with-machine",title:"Bicep Curl with Machine",idNum:"0253",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:[],steps:["Adjust the seat of the machine so your elbows are correctly aligned with the rotation axis.","Press your arms against the pads and keep them stationary throughout the exercise.","Curl your forearms until your arms are fully flexed.","Slowly lower your arms back to the starting position."]},{slug:"biceps-curl-reverse-with-dumbbells",title:"Biceps Curl Reverse with Dumbbells",idNum:"0257",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["dumbbell"],steps:["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand with palms facing down.","Keeping your arms at your side your elbows steady, lift the dumbbells up towards your shoulders.","Pause for a moment and then return to the starting position."]},{slug:"biceps-curl-seated-on-stability-ball-with-dumbbell",title:"Biceps Curl Seated on Stability Ball with Dumbbell",idNum:"0255",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["dumbbell"],steps:["This version of a biceps curl uses a Stability Ball. Exercises preformed with Stability Balls encourage better posture and core muscle development.","Grasp a dumbbell in each hand while sitting on a Stability Ball with your feet placed firmly in front of you, and your abs drawn in.","Keeping your elbows at your side and your back straight, curl your arms up to your chest.","Pause for a moment, contracting your biceps.","Slowly lower your arms to the starting position."]},{slug:"biceps-curl-squat-with-dumbbell",title:"Biceps Curl Squat with Dumbbell",idNum:"0256",type:"isolation, compound",primary:["biceps"],secondary:["hamstrings","glutes"],equipment:["dumbbell"],steps:["This exercise combines a squat with a curl to effectively work the entire body. This is an advanced exercise.","Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand and curl your arms up to your shoulders.","Bending at the waist, squat down as you lower your hands to the floor (the lower part of a curl).","Pause for a moment and then return to the starting position.","Note: Contract your biceps as you curl your arms up."]},{slug:"biceps-curl-v-sit-on-dome-with-dumbbells",title:"Biceps Curl V Sit on Dome with Dumbbells",idNum:"0269",type:"isolation",primary:["biceps"],secondary:["abdominals","core"],equipment:["dumbbell"],steps:["This exercise uses a Dome (or Bosu) as a seat forcing you to engage and contract your abs throughout the exercise. The name comes from having our body in the shape of a “V”.","Grasp a dumbbell in each hand and sit on a dome.","Keep your legs together and your knees bent.","Draw in and hold your abs and keep your back straight.","With you arms extended to your sides, curl and contract your biceps, bringing your forearms towards your shoulders.","Slowly return to the starting position.","Note: Try to keep your balance steady and not move your legs throughout this exercise."]},{slug:"biceps-curl-with-dumbbell",title:"Biceps Curl with Dumbbell",idNum:"0224",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["dumbbell"],steps:["Stand with our feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand with your palms facing up.","Extend your arms so they are at the sides of your body.","Keeping your elbows, locked lift your arms to your chest so that your forearms touch your biceps.","In a slow controlled manner, lower your arms to the starting position.","Note: Do not swing your body as you perform this exercise."]},{slug:"biceps-curl-with-overhead-extension-using-dumbbells-on-stability-ball",title:"Biceps Curl with Overhead Extension using Dumbbells on Stability Ball",idNum:"0260",type:"isolation",primary:["triceps","biceps"],secondary:["forearm","should"],equipment:["dumbbell"],steps:["This is an advanced exercise. This exercise requires you to be able to balance kneeling on a stability ball before you can correctly perform this exercise.","Grasp a dumbbell in each hand with palms facing up.","Kneel on a Stability Ball, drawing your abs in and keeping your back straight.","Raise one arm up over your shoulder and keep your other arm curled.","Bend your raised arm back as if performing a triceps extension while lowering your other arm and curling it back.","Return to starting position and repeat arms.","Note: Work with a Personal Trainer or Instructor to learn how to safely perform this exercise."]},{slug:"biceps-curls-with-barbell",title:"Biceps Curls with Barbell",idNum:"0211",type:"isolation",primary:["biceps"],secondary:["shoulders","forearm"],equipment:["barbell"],steps:["This is a basic exercise for the biceps (arms).","Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a barbell with palms facing up, approximately shoulder width apart.","Lower your arms fully to above your thighs and bending only your elbows, raise the bar to your upper chest.","Pause for a moment and then return to the starting position.","Note: Do not swing your hips or back during this exercise."]},{slug:"biceps-hammer-curl-with-dumbbell",title:"Biceps Hammer Curl with Dumbbell",idNum:"0227",type:"isolation",primary:["biceps"],secondary:[],equipment:["dumbbell"],steps:["This exercise uses a hammering (up and down) motion to isolate the biceps."," Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand so your palms are facing each other.","Extend your arms so they are at the sides of your body.","Keeping your elbows locked lift your arms in an arc towards your shoulders.","Lower your arms in a steady controlled motion and repeat.","Note: Do not turn your wrists during this exercise."]},{slug:"body-leg-lifts",title:"Body Leg Lifts",idNum:"0111",type:"isolation",primary:["gluts"],secondary:["hamstring"],equipment:["body"],steps:["Using a post or tall weight bench for balance stand straight with your abs drawn in.","Raise one off the ground and behind you while standing on the other leg.","Slowly lower the leg and raise it again while flexing the gluts.","Repeat with your other leg."]},{slug:"body-row",title:"Body Row",idNum:"0086",type:"compound",primary:["chest"],secondary:["core","neck","back"],equipment:["bar"],steps:["Lie under a bar so that the bar is at mid chest level and your feet are firmly on the floor.","Draw your abs in and keep your back flat.","Using your arms, lift and row your body towards the bar.","Pause for a moment and with slow controlled movements lower your self back to starting position.","Repeat."]},{slug:"bosu-ball-push-up",title:"Bosu Ball Push Up",idNum:"0069",type:"isolation",primary:["chest"],secondary:["shoulders","core","triceps"],equipment:["bosu ball"],steps:["Place the Bosu ball flat side down on the floor.","Kneel on the floor with your arms fully extended on the ball, and body straight.","Keeping your abs drawn in and your body straight, by bending your elbows lower your chest to the ball.","Pause for a moment and then return to starting position.","Repeat."]},{slug:"bridging",title:"Bridging",idNum:"0109",type:"isolation",primary:["gluts"],secondary:["core"],equipment:["body"],steps:["Lie on your back with your knees bent and your feet flat on the floor.","Lift up hips and bum off the floor as you draw your abs in and keep your gluts tight."]},{slug:"cable-crossover",title:"Cable Crossover",idNum:"0048",type:"isolation",primary:["chest"],secondary:["shoulders"],equipment:["cable machine"],steps:["Attach the cable pulley to shoulder height.","Grasp the pulley in both hands and stand approximately one foot in front of the weight stacks, with one foot slightly in front of the other.","With a slight bend in your elbows bring your hand together in front of your chest on downward angle.","When your hands meet at the midpoint of your chest, hold for a moment.","With a slow controlled motion return to starting position."]},{slug:"cable-shoulder-shrugs",title:"Cable Shoulder Shrugs",idNum:"0009",type:"isolation",primary:["trapezius"],secondary:["shoulders"],equipment:["cable machine"],steps:["Attach a pulley to the lowest setting on cable machine.","Stand with your feet shoulder width apart, your abs drawn and your back straight.","Start with the pulley at waist height.","Grasp the pulley and shrug your shoulders up while keeping your arms extended.","Hold this position for a moment then with a controlled motion return to the starting position of the pulley to waist height."]},{slug:"calf-raises-with-band",title:"Calf Raises with Band",idNum:"0274",type:"isolation",primary:["calves"],secondary:[],equipment:["bands"],steps:["This exercise uses a band to create resistance.","Stand with your toes on an exercise band and raise the handles up to your shoulders.","Raise up on your toes, keeping your hands up by your shoulders.","Pause for a moment and then lower your heel to the floor.","Repeat."]},{slug:"calves-press-on-leg-machine",title:"Calves Press on Leg Machine",idNum:"0273",type:"isolation",primary:["calves"],secondary:[],equipment:["machine"],steps:["This exercise uses a Leg Press Machine to work your calves. You can perform this exercise along with Leg Presses.","Sit down on a Leg Press Machine and press the plate up as if you were performing a leg press.","Slide your feet down so that the balls of your feet are pressing against the rack (with your heels hanging free).","Keeping the handles locked, press up and flex your toes and then slowly bring your toes back towards your body.","Perform theses movements slowly for maximum benefit.","Note: Use a lighter weight on this exercise than you are able to lift with a leg press until you are familiar with the movements."]},{slug:"chest-dips",title:"Chest Dips",idNum:"0054",type:"isolation",primary:["chest"],secondary:["triceps","shoulders"],equipment:["body","parallel bars"],steps:["Stand in between the parallel bars.","Grip the handles of the parallel bars and push yourself up to the starting position with straightened arms.","With your elbows close to your body keep your hips straight, lower your body forward by bending your elbows so your chest is leading as you go down.","Raise yourself back up to the starting position and repeat.","Repeat."]},{slug:"close-grip-barbell-bench-press",title:"Close Grip Barbell Bench Press",idNum:"0049",type:"isolation",primary:["chest"],secondary:["triceps","shoulders"],equipment:["barbell"],steps:["Lie on a flat bench with your feet flat on the floor, keep your back flat on the bench.","Grasp the bar a close grip (approximately 14” apart).","Raise the barbell above your body and move it over the middle of your chest, this is your starting position.","Lower the bar down so it just touches your chest.","Raise the bar till your arms are fully extended and your elbows are locked.","Return to starting position."]},{slug:"close-grip-ez-bar-curl-with-barbell",title:"Close Grip EZ Bar Curl with Barbell",idNum:"0218",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["barbell"],steps:["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp an EZ bar with an underhand close (4 inch) grip on the innermost part of the bar.","Extend your arms fully against your thighs.","Keeping your elbows straight, raise the bar towards your chest.","Pause for moment and then return to the starting position.","Note: Lean up against a wall or post if you have problems keeping from swinging."]},{slug:"close-grip-standing-biceps-curls-with-barbell",title:"Close Grip Standing Biceps Curls with Barbell",idNum:"0219",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["barbell"],steps:["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a barbell with palms up, about 12 inches apart.","Extend your arms fully against your thighs.","Keeping your elbows straight, raise the bar towards your chest until your forearms touch your chest.","Pause for moment and then return to the starting position.","Note: Lean up against a wall or post if you have problems keeping from swinging."]},{slug:"close-triceps-pushup",title:"Close Triceps Pushup",idNum:"0188",type:"compound",primary:["triceps"],secondary:["chest"],equipment:["body"],steps:["This version of the Pushup isolates the tricep (back of the arm) muscles.","Kneel down on the floor or a mat, placing your hand thumbs together and raise your up on your toes.","Draw your abs in and keep your back and neck in a straight line.","Slowly lower your body towards the floor, by bending your arms, until you are nearly touching the floor.","In a controlled manner raise your body back up to the starting position."]},{slug:"concentration-curls-with-dumbbell",title:"Concentration Curls with Dumbbell",idNum:"0220",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["dumbbell"],steps:["Sit on the end of a flat bench with your feet flat and your legs spread apart.","Grasp a dumbbell in your hand, palms facing up.","With your elbow pressed against your inner thigh, curl the dumbbell up towards your chest.","Slowly return to the starting position.","Repeat and switch arms.","Note: Keep all of your body still except the arm you are exercising."]},{slug:"cross-body-crunch",title:"Cross Body Crunch",idNum:"0289",type:"compound",primary:["abdominals"],secondary:[],equipment:["body"],steps:["Lie on your back and bring your knees up to a 60 degree angle, keep your feet flat on the floor.","Place your hands on either side of your head (over your ears).","Curl up raising your right elbow and your left knee so that they touch over your chest.","Return to the starting position and repeat with alternate arms and legs.","Note: Contract your abs as you twist during this exercise."]},{slug:"cross-body-hammer-curl-with-dumbbell",title:"Cross Body Hammer Curl with Dumbbell",idNum:"0221",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["dumbbell"],steps:["While standing, grab a dumbbell in each arm with palms facing in.","Keeping your palms facing in (and not twisting your arms) curl the dumbbell up towards your opposite shoulder.","Bring the top of dumbbell up to and touching the shoulder.","Slowly with a controlled manner, lower the dumbbell back to the starting position."]},{slug:"crossover-bands",title:"Crossover with Bands",idNum:"0050",type:"isolation",primary:["chest"],secondary:["shoulders","biceps"],equipment:["exercise band"],steps:["This is an exercise for chest, biceps and shoulder strengthening.","Secure an exercise to a post (or secure pole) and hold it in each hand.","Step forward so the band has some tension, facing away from the post."," Your arms at mid chest height and out to the side, palms facing forward this is your starting position.","Bring your hands together in front of you.","Hold this for a moment and then in a controlled motion return to starting position."]},{slug:"crunches",title:"Crunches",idNum:"0291",type:"isolation",primary:["abdominals"],secondary:[],equipment:["body"],steps:["This is the most common abdominal exercise and possibly the most often improperly performed. Here is how to perform it correctly.","Lie on your back with your feet up on a bench and your knees bent at a 90 degree angle.","Place your hands across your chest or on either side of your head (over your ears).","Raise your head, shoulders and chest off the floor and towards your knees, crunching your abs.","Hold the position for a moment and then lower to the starting position.","Note: Keep your hips straight and your lower back against the floor during this exercise."]},{slug:"crunches-with-legs-on-stability-ball",title:"Crunches with Legs on Stability Ball",idNum:"0290",type:"isolation",primary:["abdominals"],secondary:[],equipment:["stability ball"],steps:["Lie on your back and place your feet up on a stability ball.","Place your hands across your chest, or on either side of your head.","Keeping the small of your back on the floor, raise your head, shoulders and chest up and off the floor.","Pause for a moment contracting your abs and then return to the starting position.","Note: Take your time and perform this exercise in a slow controlled manner."]},{slug:"decline-barbell-bench-press",title:"Decline Barbell Bench Press",idNum:"0051",type:"isolation",primary:["chest"],secondary:["triceps","shoulders"],equipment:["decline bench","barbell"],steps:["Lie on a decline bench with your head lower than your feet.","Grasp the bar at a grip 3-6 inches wider than your shoulders.","Raise the bar above your chest, keeping your elbows close in.","Slowly and with control lower the bar straight to your lower chest.","Raise the bar back up to starting position with the bar just above your chest.","Repeat."]},{slug:"decline-chest-press",title:"Decline Chest Press",idNum:"0085",type:"isolation",primary:["chest"],secondary:["shoulders","triceps"],equipment:["chest machine"],steps:["Adjust the seat of the machine so that the handles are near the lower portion of your chest.","Slowly press the handles forward until your hands are fully extended, do not lock your elbows.","Pause for a moment and then with a controlled movement lower your hands back to starting position."]},{slug:"decline-close-grip-bench-to-skull-crusher",title:"Decline Close Grip Bench to Skull Crusher",idNum:"0168",type:"isolation",primary:["triceps"],secondary:["chest"],equipment:["barbell"],steps:["Lay with your back on a flat bench.","Grip a barbell with a close grip 8-12 inches apart.","Keeping your arms close to your sides lower the bar so it touches your chest, approximately an inch below your nipples.","Slowly return to starting position, concentrating on your triceps.","At the top of the exercise bend your arms down towards your head.","Raise the bar back up over your chest and repeat."]},{slug:"decline-crunch",title:"Decline Crunch",idNum:"0292",type:"isolation",primary:["abdominals"],secondary:[],equipment:["body"],steps:["Lie on a decline bench face up.","Place your feet securely under the pads.","Place your hands either across your chest or on either side of your head (over your ears).","Lay fully back and then rise slowly crunching your abs.","Pause for a moment and then return to the starting position.","Note: Use the full range of movement in this exercise for the optimal results."]},{slug:"decline-dumbbell-bench-press",title:"Decline Dumbbell Bench Press",idNum:"0052",type:"isolation",primary:["chest"],secondary:["triceps","shoulders"],equipment:["dumbbells","decline bench"],steps:["Grasp the dumbbells your hands and lie on a decline bench with your head lower than your feet.","Raise the dumbbells above your chest, bringing your elbows close in, this is your starting position.","Slowly and with control lower the dumbbells to either side of your lower chest.","Raise the dumbbells back up to starting position."]},{slug:"decline-dumbbell-flys",title:"Decline Dumbbell Fly's",idNum:"0053",type:"isolation",primary:["chest"],secondary:["shoulders"],equipment:["dumbbells","decline bench"],steps:["Lie on a decline bench with your head lower than your body and your feet firmly on the ground.","With dumbbells together above your shoulders and your arms straight out above you as your starting position.","Keeping your arms straight and with a slight bend in your elbows lower the dumbbells down towards the floor in an arc, up until just above your shoulders.","Return to the starting position in a slow controlled manner.","Repeat."]},{slug:"decline-ez-bar-triceps-extension-with-barbell",title:"Decline EZ Bar Triceps Extension with Barbell",idNum:"0170",type:"isolation",primary:["triceps"],secondary:[],equipment:["barbell"],steps:["Lay face up on a decline bench and grasp an EZ Bar (Curved Barbell).","Extend your arms so they are perpendicular to your chest, and keeping your elbows in one place, lower the bar toward your head.","Slowly return to the starting position."]},{slug:"decline-oblique-crunch",title:"Decline Oblique Crunch",idNum:"0293",type:"compound",primary:["abdominals"],secondary:[],equipment:["body"],steps:["This version of a decline crunch isolates the oblique (side) muscles of the abs.","Lie on a decline bench face up.","Place your feet securely under the pads.","Place your hands either across your chest or on either side of your head (over your ears).","Raise your shoulders and chest up keeping your back straight and bring your left elbow to your right knee, slowly crunching your abs.","Pause for a moment and then return to the starting position.","Lay fully back and repeat with your right elbow to your left knee."]},{slug:"decline-triceps-extension-with-dumbbell",title:"Decline Triceps Extension with Dumbbell",idNum:"0169",type:"isolation",primary:["triceps"],secondary:[],equipment:["dumbbell"],steps:["Lay face up on a decline bench with a dumbbell in each hand.","Extend your arms so they are perpendicular to your chest, and keeping your elbows in one place, lower your hands so the dumbbells are lowered near your head.","Slowly return to the starting position."]},{slug:"donkey-calf-raises",title:"Donkey Calf Raises",idNum:"0275",type:"isolation",primary:["calves"],secondary:[],equipment:["body"],steps:["This is an old school gym exercise which requires the assistance of another person. This is an advanced exercise and not recommended for beginners.","Bend your waist and lean your arms against a weight rack or bench that is waist height.","Have a partner sit on top of your lower back.","Raise up on your toes leaning slightly forward.","Pause at the top and then lower your heels to the floor.","Note: Have a Personal Trainer or Instructor show you how to perform this exercise safely."]},{slug:"drag-curl-with-barbell",title:"Drag Curl with Barbell",idNum:"0222",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["barbell"],steps:["This exercise is credited to the late Vince Gironda, the “Iron Guru”. It not only blasts the biceps and works the forearms as well.","Stand with your feet shoulder width apart, your knees slightly bent, and your abs drawn in.","Grasp the bar with palms down, shoulder width apart.","Extend your arms fully so they are against your thighs.","Slowly raise your arms, palms down, to touch your chest.","Note: Do not move your elbows or shoulders during this exercise."]},{slug:"dumbbell-bent-arm-pullover",title:"Dumbbell Bent Arm Pullover",idNum:"0046",type:"isolation",primary:["chest"],secondary:["shoulders","triceps","lats"],equipment:["flat bench","dumbbell"],steps:["Lie flat on a bench with your head hanging slightly over the end and your feet flat on the floor.","Hold a dumbbell with both hands, keep your elbows in throughout the exercise.","Starting with your arms fully extended over your chest, slowly lower the dumbbell in an arc over your head and towards the floor.","Pull the dumbbell back up to chest height in a slow controlled manner and return to starting position.","Repeat."]},{slug:"dumbbell-dead-lifts",title:"Dumbbell Dead Lifts",idNum:"0107",type:"isolation",primary:["lower back"],secondary:["calves","hamstring"],equipment:["dumbbells"],steps:["Grasp 2 dumbbells and stand with your feet shoulder width apart.","Keeping your back straight bend at the waist, allow some bend in your knees.","Grasp the dumbbells with an overhand grip in each hand.","Straighten your back as you hold the dumbbells at arm’s length.","Bend over again lowering the dumbbells to just above the floor.","Return to starting position.","Repeat."]},{slug:"dumbbell-flys",title:"Dumbbell Flys",idNum:"0056",type:"isolation",primary:["chest"],secondary:["shoulders","triceps"],equipment:["flat bench","dumbbells"],steps:["Lie on a flat bench with a dumbbell in each hand and your feet firmly on the ground.","Lift the dumbbells over your chest extending your arms fully with a slight bend in your elbows, this is your starting position.","Keeping a slight bend in your elbows, lower the dumbbells to the floor in an arc like motion.","Slowly return the dumbbells over your chest to the starting position in a controlled motion.","Repeat."]},{slug:"dumbbell-incline-bench-press",title:"Dumbbell Incline Bench Press",idNum:"0061",type:"isolation",primary:["chest"],secondary:["triceps","shoulders"],equipment:["dumbbells","incline bench"],steps:["Lie on an incline bench which has been set to an incline of 45 degrees.","Start with the dumbbells at shoulder height, your arms wide and elbows pointing down to the floor.","Grasp the dumbbells with a grip so your palms face each other.","Raise your arms up over your chest bringing the dumbbells closer together as they meet over your chest, as if you were clapping.","Slowly return the dumbbells to starting position."]},{slug:"dumbbell-lunges",title:"Dumbbell Lunges",idNum:"0115",type:"isolation",primary:["hamstring"],secondary:["gluts","quadriceps","calves"],equipment:["dumbbells"],steps:["Grasp a dumbbell in each hand.","Stand with your feet about 8 inches apart, toes facing forward.","Take a step forward (2-3 feet) keeping your abs drawn in and your upper body straight.","Slowly lower one knee down as if kneeling while keeping your other knee bent at a 90 degree angle, do not let your knee touch the ground.","Lower your body so that the rear knee is just above the floor and hold for a moment before returning to the starting position.","Repeat on opposite side."]},{slug:"dumbbell-upright-rows",title:"Dumbbell Upright Rows",idNum:"0016",type:"isolation",primary:["shoulders"],secondary:["biceps","upper back"],equipment:["dumbbells"],steps:["Grasp a dumbbell in each hand with an overhand grip (palms facing downwards) and hold them in front of your thighs.","Stand with your feet shoulder width apart, your abs drawn in and your back straight.","Starting with the dumbbells at your thighs, slowly raise them up towards your shoulders by bending your elbows.","Pause at the top and rotate your shoulder blades together.","Lower the dumbbells in a controlled motion to your thighs.","Repeat"]},{slug:"exercise-ball-pull-in",title:"Exercise Ball Pull In",idNum:"0296",type:"compound",primary:["abdominals"],secondary:[],equipment:["body"],steps:["Lay down as if you were performing a pushup.","Place your feet and shins over an exercise or stability ball.","Keeping your back straight and supporting your weight on your hands, pull your knees towards your chest, so the ball rolls forward under your ankles.","Crunch your abs and then roll the ball back to starting position straighten your legs.","Note: Keep your back straight as you perform this exercise."]},{slug:"ez-bar-curl-with-barbell",title:"EZ Bar Curl with Barbell",idNum:"0226",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["barbell"],steps:["Stand with your feet shoulder width apart and your knees slightly bent.","Grasp the barbell with palms up.","Lower the bar so it is against your thighs.","Keeping your elbows still, raise the bar up to your chest so that your forearms touch your biceps.","Note: Lean up against a wall or post to keep yourself from swaying."]},{slug:"flat-bench-cable-flys",title:"Flat Bench Cable Flys",idNum:"0057",type:"isolation",primary:["chest"],secondary:["shoulders"],equipment:["flat bench","cable machine"],steps:["<h3> Steps</h3>","Lie on flat bench between two cable towers and your feet firmly on the ground.","Grasp a pulley in each hand with your palms facing up.","With a slight bend in your elbows, squeeze your chest and pull the cables together meeting in the middle of your chest.","Hold for a moment and then slowly lower your hands back to starting position at bench height.","<h3>Tip</h3>","Ensure your back and hips stay in contact with the bench at all times during this exercise."]},{slug:"flat-bench-leg-raises",title:"Flat Bench Leg Raises",idNum:"0021",type:"isolation",primary:["lower abdominals"],secondary:[],equipment:["body"],steps:["Lie on a flat bench with your hands under your hips supporting your back.","Your legs should be unsupported by the bench from below your knees.","With your feet together and your toes flexed upwards, raise your straight legs up a few cm off the bench; both of your legs should have no contact with the bench. This is your starting position.","Keep your legs straight with a slight bend in the knees and raise your legs to just before 90 degrees with your hips.","Pause at the top and lower your legs in slow controlled manner back to the starting position.","Repeat."]},{slug:"flexor-incline-curls-with-dumbbell",title:"Flexor Incline Curls with Dumbbell",idNum:"0228",type:"isolation",primary:["biceps"],secondary:[],equipment:["dumbbell"],steps:["Sit on an incline bench with your feet firmly on the floor in front of you.","Grasp a dumbbell with your palms facing up.","Bring your arms down to your sides and while keeping your wrists as straight as possible, raise your wrists to your shoulders.","Concentrate on squeezing your biceps as you contract (raise) your arms."]},{slug:"flutter-kicks",title:"Flutter Kicks",idNum:"0116",type:"isolation",primary:["hamstrings"],secondary:["quadriceps"],equipment:["flat bench"],steps:["Lie face down on a bench with your hips on the edge, hold onto the bench with your hands.","Allow your legs and toes hang down.","Draw your abs in, squeeze your gluts and hamstrings.","Kick each back and up while keeping your hips on the bench.","Alternate kicking each leg."]},{slug:"forward-lunge-with-biceps-curl-using-dumbbell",title:"Forward Lunge with Bicep Curl using Dumbbell",idNum:"0265",type:"compound, isolation",primary:["biceps"],secondary:["calves","hip abductors","forearm","hamstrings","glutes"],equipment:["dumbbell"],steps:["Grasp a dumbbell in each hand with your palms facing up.","Stand with your feet together, your back straight and your abs drawn in.","Allow your arms to extend down fully to the sides of your body.","While keeping your body straight, take a step forward then bend your waist and your knee into a lunge.","Be careful not to let your back knee drop to the floor.","As you go into the lunge, curl your arms up towards your shoulders, contracting your biceps.","Return to starting position and switch legs.","Note: Have a Personal Trainer or Instructor show you how to properly perform this exercise."]},{slug:"front-cable-raises",title:"Front Cable Raises",idNum:"0008",type:"isolation",primary:["shoulders"],secondary:["chest","forearm"],equipment:["cable machine"],steps:["Place the pulley on the setting just above the floor.","Stand with your feet shoulder width apart, your abs drawn in and your knees slightly bent.","Starting at waist height, take the pulley in your left hand, palm facing the floor with otherwise known as an overhand grip, and raise your straight arm up towards your left shoulder.","At shoulder height pause for a moment.","With a controlled movement resist the weight and slowly lower your arm back to starting position at your waist.","Repeat the exercise with your right arm."]},{slug:"front-dumbbell-raise",title:"Front Dumbbell Raise",idNum:"0033",type:"isolation",primary:["shoulders"],secondary:[],equipment:["dumbbells"],steps:["Stand with a dumbbell in each hand with an overhand grip, your feet shoulder width apart and your abs drawn in.","Keeping each arm straight raise your left arm to just above shoulder height.","Pause for a moment then in a controlled motion lower the weight to starting position and repeat with your right arm.","<h3></h3>"]},{slug:"front-squat-to-bench-with-barbells",title:"Front Squat to Bench with Barbells",idNum:"0139",type:"compound",primary:["quadriceps"],secondary:["hamstrings","calves"],equipment:["barbell"],steps:["The Front Squat works the same muscles as the rear squat without placing the weight of the bar on your shoulders. This exercise can be a good substitute for people with back and neck injuries. By using a bench you remind yourself how far to squat down","Steps","Place a bench behind you.","Place the barbell on your upper chest, resting it across your front deltoids and holding it with your arms crossed securely.","Keep your head and back straight, abs drawn in and your toes pointing slightly outward.","Slowly “squat” down so your upper thighs are parallel to the floor.","Slowly return to the starting position.","Note: Practice the squat without any weight to allow yourself to become comfortable with the movements. Do not sit on the bench during the exercise."]},{slug:"front-squat-with-barbell",title:"Front Squat with Barbell",idNum:"0138",type:"compound",primary:["quadriceps"],secondary:["hamstrings","calves"],equipment:["barbell"],steps:["The Front Squat works the same muscles as the rear squat without placing the weight of the bar on your shoulders. This exercise can be a good substitute for people with back and neck injuries.","Place the barbell on your upper chest, resting it across your front deltoids and holding it with your arms crossed securely.","Keep your head and back straight, abs drawn in and toes pointing slightly outward.","Slowly “squat” down so your upper thighs are parallel to the floor.","Slowly return to the starting position.","Note: Practice the squat without any weight to allow yourself to become comfortable with the movements."]},{slug:"hack-squat-machine",title:"Hack Squat Machine",idNum:"0123",type:"compound",primary:["quadriceps"],secondary:["hamstrings","calves"],equipment:["machine"],steps:["This exercise is a variation of the Squat which uses a machine.  This exercise may be preferred by beginners.","Lie face up on a Hack Squat machine with your shoulders against the pad.","Place your feet facing forward at slightly less than shoulder width apart with your toes point slightly outward.","Release the dock levers and place your hands on the hand grips.","Drawing your abs in, extend your body standing upright.","Lower your body to a squatting position so you knees are bent as if you were sitting down.","Return to the starting position."]},{slug:"hack-squat-with-barbell",title:"Hack Squat with barbell",idNum:"0125",type:"compound",primary:["quadriceps"],secondary:["hamstrings"],equipment:["barbell"],steps:["This is another variation of the basic Squat that focuses primarily on the quadriceps or thigh muscles.","Place the barbell on the floor just behind your legs and stand with your feet shoulder width apart with your toes pointing forward.","With your feet firmly placed on the floor, reach down and grasp the barbell from behind with an overhand grip.","Lift the barbell by extending your hips and knees, taking care not to lock your knees.","Lower yourself (squat) down until your thighs are parallel to the floor.","Slowly raise yourself up to starting position."]},{slug:"hammer-curls-with-rope-and-cable",title:"Hammer Curls with Rope and Cable",idNum:"0216",type:"isolation",primary:["biceps"],secondary:[],equipment:["cable"],steps:["Using the rope with the cable machine allows you isolate the biceps with this version of the Hammer Curl. This is a good exercise for beginners.","Attach a rope to a cable pulley to the bottom of the weight stack. Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in. Grasp the rope with a close underhand grip (palms facing up). Lower your arms fully to above your thighs and bending only your elbows, raise the rope to your upper chest. Pause for a moment and then return to the starting position.","Note: Keep your elbows at your side throughout this exercise. Do not swing your hips or back during this exercise."]},{slug:"hammer-grip-incline-bench-press",title:"Hammer Grip Incline Bench Press",idNum:"0059",type:"isolation",primary:["chest"],secondary:["shoulders","triceps"],equipment:["dumbbells","incline bench"],steps:["Grasp a dumbbell in each hand and lay on an incline bench set at a 45 degree angle.","Keep your feet flat on the floor and your back against the bench at all times.","Using a hammer grip (with your palms facing each other), lift the weights to shoulder height on either side of your chest.","Extend your arms fully and press the dumbbells up.","Slowly return the dumbbells to the starting position at the sides of your chest."]},{slug:"high-cable-curls",title:"High Cable Curls",idNum:"0229",type:"isolation",primary:["biceps"],secondary:["triceps"],equipment:["cable"],steps:["Place a flat bench next to a cable weigh stack.","Attach a short bar to the high pulley.","Lay on your back with your head towards the stack.","Grip the bar with palms facing you)and extend your arms fully on a slight angle over your head.","Pull the bar down towards you, curling your arms as much as possible.","Slowly return to the starting position."]},{slug:"hip-adduction",title:"Hip Adduction",idNum:"0135",type:"isolation",primary:["quadriceps"],secondary:["hip abductors"],equipment:["cable"],steps:["Stand alongside a cable pulley stack and attach a cuff to the pulley and your ankle.","Step away from the stack, holding onto the stack for support.","Standing firm on the foot not attached to the cable and slowly abduct, or pull, your cuffed ankle in front of your stabilizing leg.","Repeat and switch ankles."]},{slug:"hyperextensions",title:"Hyperextensions",idNum:"0103",type:"isolation",primary:["lower back"],secondary:["hamstrings","core"],equipment:["hyperextension bench"],steps:["Adjust the hyperextension bench so that your ankles are tucked under the footpads and your thighs are flat across the top pad.","With your arms folded across your chest and your back straight, slowly bend at the waist towards the floor, keeping your back flat.","Slowly return to the starting position.","Repeat."]},{slug:"incline-bench-press",title:"Incline Bench Press",idNum:"0043",type:"isolation",primary:["chest"],secondary:["triceps"],equipment:["incline bench","barbell"],steps:["Lie flat on an incline bench set at a 45 degree angle, with your feet shoulder width apart.","Grasp the bar a little wider than shoulder width apart.","Raise the barbell above your body and move it over the middle of your chest, this is your starting position.","Lower the bar down so it just touches your chest.","Raise the bar straight up till your arms are fully extended and your elbows are locked.","Return to starting position."]},{slug:"incline-bench-press-with-bands",title:"Incline Bench Press with Bands",idNum:"0044",type:"isolation",primary:["chest"],secondary:["biceps"],equipment:["exercise band","incline bench"],steps:["Securely fasten the band under the leg of a flat bench, near your head.","Lie flat on the bench with your feet flat on the floor in order to stabilise your movements.","Grasp one end of the band in each hand and starting with your hands at chest level.","Press upwards so your arms are fully extended.","With a slow controlled motion return to starting position."]},{slug:"incline-cable-flys",title:"Incline Cable Fly's",idNum:"0060",type:"isolation",primary:["chest"],secondary:["biceps","triceps","forearm"],equipment:["incline bench","cable machine"],steps:["Place an incline bench set at a 45 degree angle between two cable towers.","Grasp a pulley in each hand with your palms facing up.","With a slight bend in your elbows, squeeze your chest and pull the cables in an arc so they meet together in the middle of your chest.","Hold for a moment and then slowly lower your hands back to starting position at along the same arc."]},{slug:"incline-dumbbell-flys",title:"Incline Dumbbell Fly's",idNum:"0062",type:"isolation",primary:["chest"],secondary:["shoulders"],equipment:["incline bench","dumbbells"],steps:["Lie on an incline bench set a 45 degree angle with a dumbbell in each hand and your feet firmly on the ground.","Lift the dumbbells over your chest extending your arms fully and your palms facing each other.","Keeping a slight bend in your elbows, lower the dumbbells towards the floor in and arc like motion.","Slowly return to starting position."]},{slug:"incline-dumbbell-press",title:"Incline Dumbbell Press",idNum:"0080",type:"isolation",primary:["chest"],secondary:["triceps","shoulders"],equipment:["dumbbells","incline bench"],steps:["Set and incline bench at a 45 degree angle.","Start with the dumbbells at shoulder height, your arms wide and elbows pointing down to the floor.","Raise your arms up over your chest bringing the dumbbells closer together as they meet over your chest.","Slowly return the dumbbells to starting position.","Repeat."]},{slug:"incline-flys-twist",title:"Incline Fly's with a Twist",idNum:"0063",type:"isolation",primary:["chest"],secondary:["shoulders"],equipment:["incline bench","dumbbells"],steps:["Lie on an incline bench set at a 45 degree angle with a dumbbell in each hand and your feet flat on the ground.","Start with the dumbbells out to the sides of your chest, parallel to the floor as you would a regular Fly.","Raise the dumbbells over your chest in and arc, at the top turn your pinky finger in so they are facing each other.","Slowly return to starting position.","Repeat."]},{slug:"incline-inner-biceps-curl-with-dumbbell-2",title:"Incline Inner Biceps Curl with Dumbbell",idNum:"0231",type:"isolation",primary:["biceps"],secondary:[],equipment:["dumbbell"],steps:["This exercise uses an incline bench and twist to more to change your body’s position as you perform Biceps Curls. The movement is very similar to a Preacher Curl."," Adjust an incline bench to a 45 degree angle.","Grasp dumbbells in each hand with and sit down with your back against the bench, with your feet resting on the floor for support.","Allow your arms to hang down at your sides, your palms facing your body.","Keeping your elbow straight, raise the dumbbells up towards your head, contracting your biceps.","In a controlled manner lower the weight and repeat.","Note: Practice steady movements in this exercise, be careful not to let your arms sway."]},{slug:"incline-pushdown-with-cable",title:"Incline Pushdown with Cable",idNum:"0163",type:"isolation",primary:["triceps"],secondary:[],equipment:["cable"],steps:["This exercise uses cables to isolate and work the triceps (muscles on the back of the arms).","Place an incline bench facing away from a cable pulley.","Attach a short straight bar to the pulley and adjust the height so that your arms can extend fully.","Lie face up on the bench and grasp the bar with a narrow overhand grip.","Keeping your arms straight, slowly push the bar down towards your feet.","Pause at the bottom and then return to starting position.","Note: Keep your elbows steady throughout this exercise."]},{slug:"incline-shoulder-press-dumbbell",title:"Incline Shoulder Press Dumbbell",idNum:"0031",type:"isolation",primary:["shoulders"],secondary:[],equipment:["dumbbell"],steps:["Lie down on an incline bench with your feet flat on the floor and grasp the dumbbells.","With your elbows bent raise your arms up until in line with your shoulders this is your starting position.","With your abs drawn in, raise the dumbbells as high as you are able above your shoulders.","Lower the dumbbells in a slow controlled manner to starting position."]},{slug:"incline-triceps-extension-with-barbell",title:"Incline Triceps Extension with Barbell",idNum:"0174",type:"isolation",primary:["triceps"],secondary:[],equipment:["barbell"],steps:["Grasp a barbell with a close grip (4-6 inches apart).","Lie on an incline bench and hold the bar over your head.","Lower your arms in a slight arc so your forearms are touching your biceps.","Slowly return back to the starting position with the bar over your head."]},{slug:"incline-triceps-extension-with-cable",title:"Incline Triceps Extension with Cable",idNum:"0164",type:"isolation",primary:["triceps"],secondary:[],equipment:["cable"],steps:["This exercise uses cables to isolate and work the triceps (muscles on the back of the arms).","Place an incline bench facing away from a cable pulley.","Attach a short straight bar to the pulley and adjust the height so that your arms can extend fully.","Lie face up on the bench and grasp the bar with a narrow overhand grip.","Starting with your elbows bent overhead, slowly lower the bar towards your feet.","Pause at the bottom and then return to starting position."]},{slug:"incline-triceps-extensions-with-dumbbell",title:"Incline Triceps Extensions with Dumbbell",idNum:"0209",type:"isolation",primary:["triceps"],secondary:["shoulders"],equipment:["dumbbell"],steps:["Grasp a dumbbell in each hand and lie against an incline bench, face up with your feet firmly planted on the floor.","Extend your arms over your shoulders with your palms facing each other.","Slowly lower the dumbbells behind your head by bending your elbows.","With a controlled motion raise your arms back up to the starting position."]},{slug:"internal-cable-rotation",title:"Internal Cable Rotation",idNum:"0034",type:"compound",primary:["shoulders"],secondary:["biceps"],equipment:["cable machine"],steps:["Sit on the floor with your body close to low cable pulley.","Grasp the pulley with your left arm and position your elbow bent at 90 degree angle.","Pull the cable towards your body and internally rotate your shoulder until your forearm is across your abs.","Return to starting position.","Repeat with right arm."]},{slug:"iron-cross-with-dumbbells",title:"Iron Cross with Dumbbells",idNum:"0140",type:"compound",primary:["quadriceps"],secondary:["trapezius","glutes","shoulders","lower back","hamstrings"],equipment:["dumbbells"],steps:["With a dumbbell in each hand, stand in a low squat stance, your feet shoulder width arms held out in front of you with your palms facing in.","Standing upright, move your arms out and away from your body forming a “T” or “cross”.","Note: Do this exercise with light weights until you are comfortable with the movements."]},{slug:"jefferson-squats-with-barbell",title:"Jefferson Squats with Barbell",idNum:"0141",type:"compound",primary:["hamstrings"],secondary:[],equipment:["barbell"],steps:["This is a rarely used exercise which is without question one of the best exercises for building and shaping the inner thighs.","Place a barbell between your legs so it is perpendicular to your feet.","Grasp the barbell with one hand in front of you and one hand behind you with an overhand grip.","Squatting down so your thighs are parallel to the floor slowly lift the weight up between your legs as you stand.","Slowly return to a starting position just above the floor."]},{slug:"jm-press",title:"JM Press",idNum:"0175",type:"compound",primary:["triceps"],secondary:["shoulders"],equipment:["barbell"],steps:["This exercise is named after the inventor, J.M. Blakley. This is an advanced exercise used by bodybuilders and power lifters to build explosive power in the triceps muscle (back of the arms).","Lay on a flat bench with your head just at the end of the bench.","Grasp the bar with a medium overhand grip keeping your elbows close to your side, over your sternum (mid chest).","Lower the bar towards your sternum at a regular pace, then pause for a moment.","With a controlled but rapid pace, push the bar back to starting position.","Note: The bar should move in straight line, up and down."]},{slug:"knee-circles",title:"Knee Circles",idNum:"0277",type:"compound",primary:["calves"],secondary:["hamstrings"],equipment:["body"],steps:["Stand with your feet a little closer than shoulder width apart.","Keeping your arms across your chest or on your hips, move your knees in a circular motion, paying attention to keeping your feet flat on the floor and the movement in your ankles.","Note: Do not perform this exercise is you have rolled or unstable ankles."]},{slug:"kneeling-triceps-extension-with-cable",title:"Kneeling Triceps Concentration Extension with Cable",idNum:"0176",type:"isolation",primary:["triceps"],secondary:[],equipment:["cable"],steps:["Attach a stirrup handle to a cable pulley and adjust the pulley up high.","Kneeling on your left knee, with the left side of your body turned towards the machine, keep your right leg bent and the upper portion of your thigh parallel to the floor.","With your right elbow and upper arm pressed against your inner thigh just above your knee, pull the cable down towards the floor in a slight arcing motion.","Slowly to return to starting position.","Repeat and switch arms.","Note: Keep all of your body still except the arm you are exercising."]},{slug:"kneeling-triceps-extension-with-cable-2",title:"Kneeling Triceps Extension with Cable",idNum:"0177",type:"isolation",primary:["triceps"],secondary:[],equipment:["cable"],steps:["Place a bench sideways in front of a high pulley machine.","Grasp a straight bar with an over head grip.","Kneel on the floor in front of the bench with your back straight and your head down.","With your elbows and forearms above your head, push the bar down in an arc so that your forearms are touching the bench.","Note: Keep your abs drawn in and your back straight as you perform this exercise."]},{slug:"lateral-dumbbell-raises",title:"Lateral Dumbbell Raises",idNum:"0018",type:"isolation",primary:["lateral deltoid"],secondary:["forearm","shoulders"],equipment:["dumbbells"],steps:["Grasp a dumbbell in each hand, palms facing inward towards your body and the dumbbells at your sides.","Standing with your feet shoulder with apart, draw your abs in and bend your knees slightly.","While keeping your torso still, raise the your arms up to the sides keeping your arms straight with a slight bend in the elbows.","Raise your arms up until in line with your shoulders, your palms should face the floor.","Hold the position for a moment then in a controlled movement lower your arms to the starting position.","Repeat"]},{slug:"lateral-lunge-with-biceps-curl-with-dumbbell",title:"Lateral Lunge with Bicep Curl with Dumbbell",idNum:"0264",type:"compound, isolation",primary:["quadriceps","biceps"],secondary:["forearm","hamstrings","glutes","calves","hip abductors"],equipment:["dumbbell"],steps:["Grasp a dumbbell in each hand with your palms facing up.","Stand with your feet together, your back straight and your abs drawn in.","Allow your arms to extend down fully in front of your thighs.","While keeping your body straight, take a step sideways and then bend your waist and your knee into a lunge.","As you go into the lunge, curl your arms up towards your shoulders contracting your biceps.","Return to starting position and switch legs.","Note: Have a Personal Trainer or Instructor show you how to properly perform this exercise."]},{slug:"leg-extensions",title:"Leg Extensions",idNum:"0142",type:"isolation",primary:["quadriceps"],secondary:[],equipment:["machine"],steps:["Adjust the seat so that your knees have full range of motion and that the footpad fits over your legs, just above your ankles.","Grasp the handles with your hands for support, keeping your hip and back against the bench.","Slowly extend your legs until your knees are straight, but do not lock your knees.","Hold for a moment and then with controlled movements return to the starting position.","Note: Use controlled movements for this exercise, do not swing the weight up."]},{slug:"leg-press",title:"Leg Press",idNum:"0127",type:"compound",primary:["quadriceps"],secondary:["calves","hamstrings"],equipment:["machine"],steps:["Along with the Squat, this exercise is crucial for building and strengthening the legs.","Adjust the seat of the machine so that your feet comfortably reach the crosspiece with a slight bend in your knees.","To begin, press your feet forward at a shoulder width stance and release the safety locks.","Slowly lower the weight towards your body, keeping your abs drawn in and your knees moving in the same direction as your feet to a 90 degree angle.","Do not lock your knees or bounce the weight."]},{slug:"low-triceps-extension-with-cable",title:"Low Triceps Extension with Cable",idNum:"0178",type:"isolation",primary:["triceps"],secondary:[],equipment:["cable"],steps:["Attach a rope to the cable pulley at of a seated row station.","Lie on your back on the bench with your head facing the weight stack.","Grasp the rope with your palms facing each other and raise your arms over your chest, with your forearms parallel to the floor at a 90 degree angle.","Slowly extend your arms upward squeezing your triceps.","Return to starting position."]},{slug:"lying-bicep-cable-curl",title:"Lying Bicep Cable Curl",idNum:"0232",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["cable"],steps:["Attach a short bar to a cable pulley set on the lowest setting.","Lie down on a mat or the floor with your feet touching the weight stack.","Grasp the bar with and palms facing up.","With your arms fully extended and your elbows at your sides, pull the bar in an arc to your chest.","Pause for a moment contracting your biceps, and then return to the starting position."]},{slug:"lying-close-grip-biceps-curls-with-cable",title:"Lying Close Grip Biceps Curls with Cable",idNum:"0233",type:"isolation",primary:["biceps"],secondary:[],equipment:["cable"],steps:["Place a flat bench under a cable weight stack and attach a flat bar to the pulley.","Lie down with your head towards the stack and your feet firmly on the floor.","Grasp the bar with your palms down, about 8 inches apart, and extend your arms straight up.","Curl the bar down in an arc touching your chin.","Slowly return to the starting position."]},{slug:"lying-close-grip-triceps-press-to-chin-with-barbell",title:"Lying Close Grip Triceps Press to Chin with Barbell",idNum:"0180",type:"isolation",primary:["triceps"],secondary:[],equipment:["barbell"],steps:["Lie on a flat bench on your back, with your head at one end.","Grasp a bar with a close grip, approximately 6 inches apart.","Raise the bar straight up over your shoulders, keeping your elbows close in.","Slowly lower the bar in an arc towards your chin.","Return the bar to the starting position."]},{slug:"lying-close-grip-triceps-extension-behind-the-head-with-barbell",title:"Lying Close-Grip Triceps Extension Behind the Head with Barbell",idNum:"0179",type:"isolation",primary:["triceps"],secondary:[],equipment:["barbell"],steps:["You can use a barbell or EZ (curl) bar to further concentrate the benefit to your triceps.","Lie flat on a bench on your back.","Grasp the bar with a grip approximately 8 inches apart and lower the bar behind your head.","Keeping the bar parallel with the floor, bend your arms down in an arc so the bar moves in a direction under your head.","Slowly return to starting position."]},{slug:"lying-high-bench-biceps-curl-with-barbell",title:"Lying High Bench Biceps Curl with Barbell",idNum:"0234",type:"isolation",primary:["biceps"],secondary:[],equipment:["barbell"],steps:["With this exercise your lay face down to isolate your biceps.","Lay face down on a high bench with your head at one end and your toes pressed against the floor to support you.","Grasp a barbell with palms facing up, about 12 inches apart.","Extending your arms to the floor, curl your arms back towards your head in a slight arc, so your biceps touch your forearm.","Slowly return to the starting position."]},{slug:"lying-incline-curl-with-barbell",title:"Lying Incline Curl with Barbell",idNum:"0215",type:"isolation",primary:["biceps"],secondary:[],equipment:["barbell"],steps:["This exercise uses an incline bench to change your body’s position as you perform Biceps Curls. The movement is very similar to a Preacher Curl.","Adjust an incline bench to a 45 degree angle.","Grasp a barbell with a shoulder width grip and lean face down against the bench, with your feet resting on the floor for support.","Allow your arms to hang down at your sides.","Keeping your elbows straight, raise the bar up towards your head, contracting your biceps.","In a controlled manner lower the weight and repeat.","Note: Practice steady movements in this exercise, be careful not to let your arms sway."]},{slug:"lying-leg-curl-machine",title:"Lying Leg Curl Machine",idNum:"0117",type:"isolation",primary:["hamstring"],secondary:[],equipment:["machine"],steps:["Lie face down on a leg curl machine and place your heels under the roller pad.","Grasp the grips with your hands for support and slowly curl your ankles up towards your back.","Hold for a moment and then return to starting position.","Repeat."]},{slug:"lying-one-arm-rear-lateral-raise",title:"Lying One Arm Rear Lateral Raise",idNum:"0037",type:"isolation",primary:["shoulders"],secondary:[],equipment:["dumbbell","flat bench"],steps:["Lay face down on a flat bench high enough for your arms to hang down to the floor.","Place a dumbbell at your side.","Your other hand not grasping the dumbbell can be on the floor stabilising your movements.","Grasp the dumbbell in your hand and raise your upper arm to shoulder height.","Keep your arm straight and perpendicular to your chest with a slight bend in the elbow.","In a slow controlled manner lower your arm to starting position."]},{slug:"lying-rear-lateral-raise",title:"Lying Rear Lateral Raise",idNum:"0023",type:"isolation",primary:["shoulders"],secondary:[],equipment:["flat bench","dumbbells"],steps:["Place the dumbbells at he head of the bench.","Lie facedown on a raised bench; raised enough for your arms to move freely beneath the bench.","Place your toes on the floor in order to stabilise yourself.","Grasp the dumbbells and with a 30 degree bend in your elbows, this is the starting position.","Raise your arms to shoulder height, maintaining a controlled motion.","Return to starting position and repeat."]},{slug:"lying-squat",title:"Lying Squat",idNum:"0144",type:"compound",primary:["quadriceps"],secondary:["calves","hamstrings"],equipment:["machine"],steps:["Adjust the shoulder rack of the machine so that your feet comfortably reach the crosspiece with a slight bend in your knees.","To begin, press your feet forward and release the safety locks.","Slowly lower the weight towards your body, keeping your abs drawn in and your knees moving in the same direction as your feet to a 90 degree angle.","Do not lock your knees or bounce the weight."]},{slug:"lying-supine-biceps-curl-with-dumbbell",title:"Lying Supine Biceps Curl with Dumbbell",idNum:"0235",type:"isolation",primary:["biceps"],secondary:[],equipment:["dumbbell"],steps:["This is another biceps exercise where you lay down to isolate the muscles you are working. This is an advanced exercise.","Lie on a flat bench with your head at one end and your feet planted firmly on the floor.","With a dumbbell in each hand, palms facing in, bring your arms down to your sides, hanging off the bench.","Slowly raise your arms up until they are level with your chest.","Curl the dumbbells by twisting your palms, so that your forearms touch your biceps.","Slowly lower your arms to the starting position.","Note: Practice the motions of this exercise with light weights to become familiar with the movements."]},{slug:"lying-triceps-extension-with-cable",title:"Lying Tricep Extension with Cable",idNum:"0165",type:"isolation",primary:["triceps"],secondary:[],equipment:["cable"],steps:["This exercise uses cables to isolate and work the triceps (muscles on the back of the arms).","Place a flat bench with the end towards a weight stack.","Attach a short straight bar to the pulley and lower the pulley to the bottom of the stack.","Lie face up on the bench and grasp the bar with a narrow overhand grip.","Starting with your arms extended lower the bar towards the bar towards the stack by bending your elbows.","Slowly extend your arms upright and return to the starting position.","Note: Keep your elbows level throughout the exercises."]},{slug:"lying-triceps-extension-across-face-with-dumbbell",title:"Lying Triceps Extension Across Face with Dumbbell",idNum:"0182",type:"isolation",primary:["triceps"],secondary:[],equipment:["dumbbell"],steps:["This is an advanced exercise and should be avoided by beginners.","Lay on a flat bench with your head at one end and your feet planted firmly on the floor.","Grasp a dumbbell in each hand with palms facing up.","Raise dumbbells over your body. Your arms will be pointed towards the ceiling.","While keeping your upper arms and elbows still, lower the dumbbell slowly over your face bending only your elbow.","Slowly raise the dumbbell back to the starting position and repeat with your other arm.","Note: Do not perform this exercise if your arms are fatigued, as you are lifting the weight over your face."]},{slug:"lying-triceps-extension-with-dumbbells",title:"Lying Triceps Extension with Dumbbells",idNum:"0181",type:"isolation",primary:["triceps"],secondary:[],equipment:["dumbbell"],steps:["Lay on a flat bench with your head at one end and your feet planted firmly on the floor.","Grasp a dumbbell with both hands with palms facing up.","Raise dumbbell over your body. Your arms will be pointed towards the ceiling.","While keeping your upper arms and elbows still, lower the dumbbell in an arc behind your head.","Slowly raise the dumbbell back to the starting position."]},{slug:"lying-triceps-press-with-barbell",title:"Lying Triceps Press with Barbell",idNum:"0183",type:"isolation",primary:["triceps"],secondary:["chest"],equipment:["barbell"],steps:["Lie on a flat bench with your head at one end.","Grasp an EZ or Curl bar with an overhand grip.","Raise the bar straight up over your shoulders, taking care to keep your elbows in close.","Slowly lower the bar in an arc over your head.","Return the bar to the starting position.","Note: Keep your arms straight throughout this exercise moving only your elbows."]},{slug:"lying-two-arm-triceps-extension-with-dumbbell",title:"Lying Two Arm Triceps Extension with Dumbbell",idNum:"0184",type:"isolation",primary:["triceps"],secondary:[],equipment:["dumbbell"],steps:["Lie flat on a bench, on your back, with your head at one end.","Grasp a dumbbell in each hand and raise them at arms length over your shoulders.","Lower the dumbbells in an arc bending your elbows until your forearms are touching your biceps.","Slowly return to the starting position."]},{slug:"machine-bench-press",title:"Machine Bench Press",idNum:"0066",type:"isolation",primary:["chest"],secondary:["triceps","shoulders"],equipment:["bench press machine"],steps:["Adjust the machine so that you are sitting with the bars at chest height.","Place your hands on the bars and place your feet on the foot rest.","Press out, extending your arms as far as possible in a steady motion.","Pause for a moment and then return slowly to starting position."]},{slug:"medicine-ball-biceps-curl-on-stability-ball",title:"Medicine Ball Biceps Curl on Stability Ball",idNum:"0267",type:"isolation",primary:["biceps"],secondary:["core","forearm"],equipment:["medicine ball"],steps:["Sit on a Stability Ball with your feet firmly on the floor in front of you.","Sit with your back straight, your shoulders back and your abs drawn in.","Hold a Medicine Ball in one hand and curl it up bringing your forearm up to your bicep.","Return to starting position and switch arms.","Note: Grasp the Medicine Ball with your fingers spread wide to balance the ball."]},{slug:"narrow-parallel-grip-chin-ups",title:"Narrow Parallel Grip Chin-ups",idNum:"0090",type:"isolation",primary:["shoulders","lats"],secondary:["back","core"],equipment:["bar","body"],steps:["Grasp the bar with an supinated (overhand) grip so that your palms are facing.","Let your body hang from the bar with your arms straight.","Slowly pull yourself up so that your chin is higher than the bar.","With a controlled movement lower yourself to the starting position.","Repeat"]},{slug:"narrow-stance-hack-squats",title:"Narrow Stance Hack Squats",idNum:"0145",type:"compound",primary:["quadriceps"],secondary:["hamstrings","calves"],equipment:["machine"],steps:["Like the Hack Squat, this exercise works the muscles of the leg. The narrow stance targets the external muscles more efficiently.","Lie face up on a Hack Squat machine with your shoulders against the pad.","Place your feet facing forward at a distance of 6 inches apart with your toes point slightly outward.","Release the dock levers and place your hands on the handgrips.","Drawing your abs in, extend your body standing upright.","Lower your body to a squatting position so your knees are bent as if you were sitting down.","Return to the starting position."]},{slug:"narrow-stance-leg-press",title:"Narrow Stance Leg Press",idNum:"0143",type:"compound",primary:["quadriceps"],secondary:["calves","hamstring"],equipment:["machine"],steps:["This is a variation of the leg press which targets more of the external muscles of the legs by moving your feet closer together.","Sit on a leg press machine with your feet on the crosspiece 6 inches apart, with your toes pointed slightly outward.","Grasp the handles on the side of the machine and release the locks.","Keeping your abs drawn in, bend your knees and bring the weight as far as possible towards your chest.","Hold this position for a moment and then slowly return the weight to starting position.","Note: Do not lock your knees at the top."]},{slug:"narrow-stance-squat-with-barbell",title:"Narrow Stance Squat with Barbell",idNum:"0146",type:"compound",primary:["quadriceps"],secondary:["glutes","calves","hamstrings"],equipment:["barbell"],steps:["A great overall exercise for the lower body. This version of the Squat targets and defines more of the externals leg muscles.","Lifting a barbell off of a weight rack, position it on your shoulders.","Place your feet about 6 inches apart with your knees and toes pointed slightly outward.","Drawing your abs in, descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Notes: A pad on the bar or towel on your shoulders can help improve your grip and reduce the discomfort of the bar against your back. Practice the squat without any weight to allow yourself to become comfortable with the movements."]},{slug:"old-school-reverse-extensions",title:"Old School Reverse Extensions",idNum:"0185",type:"isolation",primary:["triceps"],secondary:[],equipment:["barbell"],steps:["Lie down on a bench, on your back, with your head at one end.","Grasp a barbell with an underhand grip.","Move your arms beyond your head, keeping them in a straight line.","Bending only your elbows, slowly lower and raise the barbell."]},{slug:"one-arm-barbell-floor-press",title:"One Arm Barbell Floor Press",idNum:"0070",type:"isolation",primary:["chest"],secondary:["triceps"],equipment:["barbell"],steps:["Lie flat on your back with your knees bent and your feet firmly on the floor.","Draw in your abs and contract your lats, and glutes.","Have your partner hand you the bar and with your bicep parallel to the floor lift and extend your arm fully so it is straight.","Return to the starting position.","Complete reps and switch arms."]},{slug:"one-arm-bench-press",title:"One Arm Bench Press",idNum:"0068",type:"isolation",primary:["chest"],secondary:["triceps","shoulders"],equipment:["flat bench","dumbbell"],steps:["Lie flat on a bench with your feet placed firmly on the floor and your abs drawn in.","Grasp the dumbbell in one hand and bring it up to the side of your chest, this is starting position.","Extend your arm, pressing the dumbbell up till your arm is straight and your elbow locked.","Using slow controlled movements, lower the weight to starting position.","Switch arms after completing reps with one arm.","Repeat."]},{slug:"one-arm-bicep-concentration-on-stability-ball-with-dumbbell",title:"One Arm Bicep Concentration on Stability Ball with Dumbbell",idNum:"0258",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["dumbbell"],steps:["Grasp a dumbbell in one hand and sit on a Stability Ball with your feet wide apart.","Bend forward leaning at the waist.","With the dumbbell in your hand, place your elbow against your knee.","Lower your arm so it is flat against your calves.","Curl your arm up to your chest keeping your elbow steady.","Return to starting position and change hands."]},{slug:"one-arm-biceps-curl-with-olympic-bar-or-barbell",title:"One Arm Bicep Curl with Olympic Bar or Barbell",idNum:"0254",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["barbell"],steps:["Stand with your feet shoulder width apart and your knees slightly bent.","Grasp an Olympic bar (empty weight bar) in the middle with one hand so that the bar is equally balanced.","Keep your free hand at your side for support.","Curl the bar up so your forearm touches your bicep.","Slowly lower the bar and change arms.","Note: If an Olympic bar is too heavy use a lighter weight barbell."]},{slug:"one-arm-dumbbell-shoulder-press",title:"One Arm Dumbbell Shoulder Press",idNum:"0038",type:"isolation",primary:["shoulders"],secondary:["triceps","biceps"],equipment:["dumbbell"],steps:["Stand with your feet shoulder width apart, back straight and abs drawn in.","Grasp a dumbbell in your hand and lift it with a bent elbow to your shoulder height to start.","Lift the dumbbell straight up till your arm is fully extended overhead.","Lower in a controlled manner and return to starting position.","Repeat."]},{slug:"one-arm-flat-bench-flys",title:"One Arm Flat Bench Fly’s",idNum:"0071",type:"isolation",primary:["chest"],secondary:[],equipment:["flat bench","dumbell"],steps:["Lie on a flat bench with your free hand holding the bench.","Grasp the dumbbell in your other hand and with your forearm parallel to the floor raise your arm in an arc the middle of your chest.","Once the dumbbell is at the middle of your chest line, slowly lower is along the same path to starting position.","Repeat."]},{slug:"one-arm-low-pulley-triceps-extension-with-cable",title:"One Arm Low-Pulley Triceps Extension with Cable",idNum:"0199",type:"compound",primary:["triceps"],secondary:[],equipment:["cable"],steps:["Attach a handle to a low cable pulley machine.","Stand with your back to the weight stack, your feet shoulder width apart.","With your left hand, reach behind you and grasp the handle.","Place your right hand on your left elbow for support.","Extend your left arm straight up towards the ceiling and then lower it to the starting position.","Repeat and switch arms."]},{slug:"one-arm-preacher-curl-with-dumbbell",title:"One Arm Preacher Curl with Dumbbell",idNum:"0237",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["dumbbell"],steps:["A Preacher Curl uses a special bench to support the triceps and isolate the biceps to build the arms. This version uses dumbbells and single arm movements for better control.","Adjust the seat of the bench so your arm is level with the top of the bench.","Grasp a dumbbell in your hand with palms facing up.","Rest your arm against the bench and extend it fully down.","Keeping your arm on the bench at all times, curl the dumbbell up towards your head.","Pause for a moment and then lower the dumbbell back to starting position.","Switch arms and repeat.","Note: Perform this exercise in a slow controlled manner for best results."]},{slug:"one-arm-side-deadlift-with-barbell",title:"One Arm Side Deadlift with Barbell",idNum:"0150",type:"compound",primary:["quadriceps"],secondary:["abdominals","glutes","calves","hamstrings"],equipment:["barbell"],steps:["This is an advanced exercise that works most of the muscles of the body. Exercises like this are used to develop functional strength for sports that require strong hands.","Stand besides a barbell placed on the floor.","Grasp the bar with an overhand grip in the center.","Crouching down as if your were performing a squat, bend down so your thighs are parallel with the floor.","Extend your legs slowly as you straighten your body up, drawing in your abs as you rise.","Note: Perform this exercise with an empty bar to become familiar with the movement before adding weights."]},{slug:"one-arm-snatch-with-barbell",title:"One Arm Snatch with Barbell",idNum:"0148",type:"compound",primary:["quadriceps"],secondary:["shoulders","hamstrings","lower back","abdominals","trapezius","calves"],equipment:["barbell"],steps:["This is an advanced exercise that works most of the muscles of the body. Exercises like this are used to develop functional strength for sports that require strong hands.","Stand with your feet shoulder width apart, and a slight bend in your knees.","Grasp the bar with an overhead grip.","Starting with the barbell held slightly above the knees (hang position), lift the weight up over your head (step 1) then back to shoulder height (step 2) and finally back to starting position between near your knees.","Note: Bend your knees as you lift and lower the weight to help control the movement."]},{slug:"one-arm-tricep-extension-with-cable",title:"One Arm Tricep Extension with Cable",idNum:"0166",type:"isolation",primary:["triceps"],secondary:[],equipment:["cable"],steps:["Place a cable pulley on the highest setting and adjust a stirrup handle to the pulley.","Stand facing the weight stack and grasp the handle with and underhand grip.","Keep your back straight, your abs drawn in and your knees slightly bent.","Starting at the top, push your arm down until it is straight, feeling the concentration in your tricep.","Slowly return to starting position.","Tips: Keep your elbow close to your side while performing this exercise."]},{slug:"one-arm-triceps-extension-with-dumbbell",title:"One Arm Triceps Extension with Dumbbell",idNum:"0173",type:"isolation",primary:["triceps"],secondary:[],equipment:["dumbbell"],steps:["Sit on a bench with your back straight and your abs drawn in.","Grasp a dumbbell in your hand and place it behind your neck with your elbow bent.","Slowly extend your arm straight up over your head and slowly return to the starting position.","Note: Place your free hand across your chest to help steady yourself during this exercise."]},{slug:"one-arm-upright-row",title:"One Arm Upright Row",idNum:"0039",type:"isolation",primary:["shoulders"],secondary:["trapezius"],equipment:["dumbbell"],steps:["Stand near a post or other stable tall object. With your one hand, hold the post.","Grasp the dumbbell in your other hand with a pronated grip (palms facing backwards).","Place the dumbbell in front of your thigh, this is starting position.","Lift the dumbbell upward to your shoulder with your elbow pointing away from your body in a rowing motion.","Lower your arm to starting position and repeat."]},{slug:"one-armed-biased-push-up",title:"One Armed Biased Push Up",idNum:"0072",type:"isolation",primary:["chest"],secondary:["triceps","bicpes","shoulders","core"],equipment:["bosu ball"],steps:["Arrange the ball so that as you begin the exercise, one hand on the Bosu ball and the other on the floor.","Place the ball flat side down on the floor.","Kneel on the floor with your arms fully extended on the dome, and body straight.","Keeping your abs drawn in and your body straight, lower your chest to the ball.","Pause for a moment and then return to starting position.","Repeat."]},{slug:"one-leg-squat-with-barbell",title:"One Leg Squat with Barbell",idNum:"0147",type:"compound",primary:["quadriceps"],secondary:["calves","hamstrings","glutes"],equipment:["barbell"],steps:["The One Leg Squat isolates the muscles of the leg for optimal exercise. This exercise is also used to build or rebuild strength after injury.","Place a bench or box 12-18 inches tall behind you. The taller the box the greater the difficulty of the exercise.","Lifting a barbell off of a weight rack, position it on your shoulders.","Place one foot up on the bench, and your other foot firmly on the floor 2-3 feet in front you.","Drawing your abs in descend slowly by bending your front knee and hip as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toe (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Switch legs and repeat.","Notes: A pad on the bar or towel on your shoulders can help improve your grip and reduce the discomfort of the bar against your back. Practice the squat without any weight to allow yourself to become comfortable with the movements."]},{slug:"one-legged-cable-kickback",title:"One Legged Cable Kickback",idNum:"0112",type:"isolation",primary:["gluts"],secondary:["hamstring"],equipment:["cable machine"],steps:["Standing at a cable tower attach an ankle cuff to a low pulley.","Facing the weight stack, with a slight bend in your knees and your abs drawn in","Slowly kick your ankle back in and arc as high as you are able to.","Return to starting position and switch ankles."]},{slug:"overhead-curl-with-cable",title:"Overhead Curl with Cable",idNum:"0238",type:"isolation",primary:["biceps"],secondary:[],equipment:["cable"],steps:["By using cable this exercise isolates and defines the biceps (arm) muscles.","Attach a stirrup handle to each side of a high pulley on a cable machine.","Grasp the handles with palms facing up and stand with your feet shoulder width apart.","Extend your arms fully to each side.","Keeping your elbows steady, curl your wrists towards the sides of your head.","Contract your biceps and pause for a moment.","Then return to the starting position."]},{slug:"overhead-squat-with-barbell",title:"Overhead Squat with Barbell",idNum:"0151",type:"compound",primary:["quadriceps"],secondary:["glutes","calves","hamstrings","shoulders","lower back"],equipment:["barbell"],steps:["Stand with your feet a bit wider than shoulder width apart with your toes pointed slightly outward.","Grasp a barbell using a wide side snatch grip with your arms and elbows fully extended.","Keeping the bar overhead, bend your knees and lower your body until your thighs are parallel with the floor.","Return to starting position.","Notes: Keep your feet firmly planted on the floor throughout this exercise. Keep your abs drawn in your back tight and your chest up you perform this exercise."]},{slug:"pile-squat-with-dumbbell",title:"Pile Squat with Dumbbell",idNum:"0152",type:"compound",primary:["quadriceps"],secondary:["hamstrings","calves"],equipment:["dumbbell"],steps:["Stand with your feet 2-4 inches wider than your shoulders, with your toes pointed out at a 45 degree angle.","Grasp a dumbbell with both hands in the center of your body.","Keep your knees slightly bent and your back straight.","Squat down as if you were going to sit in a chair, bringing your thighs parallel to the floor.","With a controlled motion return to starting position.","Notes: Keep your feet planted firmly on the floor throughout this exercise."]},{slug:"preacher-curl-with-barbell",title:"Preacher Curl with Barbell",idNum:"0239",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["barbell"],steps:["&nbsp;","Adjust the seat of the bench so that your arms are level with the top of the bench.","Grasp the bar with palms facing up, shoulder width apart.","Picking up the bar, rest your arms against the bench and extend them fully.","Keeping your arms on the bench at all times, curl the bar up towards your head.","Pause for a moment and then lower the bar back to starting position.","Note: Perform this exercise in a slow controlled manner for best results."]},{slug:"preacher-curl-with-cable",title:"Preacher Curl with Cable",idNum:"0217",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["cable"],steps:["Place a padded arm curl bench in front of a cable machine.","Attach a short bar to the bottom pulley.","Rest your arms against the bench and extend them fully.","With a narrow grip (6 inches) grasp the bar with palms facing up and pull it towards your head.","Pause for a moment and then lower the bar back to starting position.","Note: Perform this exercise in a slow controlled manner for best results."]},{slug:"preacher-curl-with-machine",title:"Preacher Curl with Machine",idNum:"0236",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["machine"],steps:["A Preacher Curl uses a special bench to support the triceps and isolate the biceps to build the arms. This version of the exercises is a machine exercise. This is a good exercise for beginners.","Adjust the seat of the bench so your arms are level with the top of the bench. Rest your arms against the bench and extend them fully. Grasp the bar underhand (palms facing up) and pull it towards your head. Pause for a moment and then lower the bar back to starting position.","Note: Perform this exercise in a slow controlled manner for best results. Read the instructions on the machine before performing this exercise."]},{slug:"preacher-hammer-curl-with-dumbbell",title:"Preacher Hammer Curl with Dumbbell",idNum:"0240",type:"isolation",primary:["biceps"],secondary:[],equipment:["dumbbell"],steps:["Adjust the seat of the bench so that your arms are level with the top of the bench.","Grasp a dumbbell in each hand with your palms facing each other, shoulder width apart and extend your arms fully along the bench.","Keeping your arms and elbows on the bench at all times, curl the dumbbells up towards your head.","Pause for a moment and then lower the bar back to starting position.","Note: Perform this exercise in a slow controlled manner for best results."]},{slug:"prone-incline-biceps-curl-with-dumbbell",title:"Prone Incline Biceps Curl with Dumbbell",idNum:"0225",type:"isolation",primary:["biceps"],secondary:[],equipment:["dumbbell"],steps:["This exercise uses an incline bench to change your body’s position as you perform Biceps Curls. The movement is very similar to a Preacher Curl.","Adjust an incline bench to a 45 degree angle.","Grasp dumbbells in each hand and lean face down against the bench, with your feet resting on the floor for support.","Allow your arms to hang down at your sides.","Keeping your elbow straight, raise the dumbbells up towards your head, contracting your biceps.","In a controlled manner, lower the weight and repeat.","Note: Practice steady movements in this exercise, be careful not to let your arms sway."]},{slug:"pull-ups",title:"Pull Ups",idNum:"0087",type:"isolation",primary:["lats"],secondary:["middle back","biceps"],equipment:["bar"],steps:["Grab the pull-up bar with the palms facing forward using the prescribed grip.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion.","<h3> Tip</h3>","Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar."]},{slug:"pullover-stability-ball-weight",title:"Pullover On Stability Ball With Weight",idNum:"0098",type:"isolation",primary:["shoulders"],secondary:["back","neck"],equipment:["exercise ball","dumbbell"],steps:["Grasp a Barbell or Dumbbell and sit on a Ball with your feet firmly placed on the floor.","Lower your body so your upper abs are the only part of your body supported on the Ball.","Bring the Barbell or Dumbbell to your chest with your arms extend.","In an arcing motion raise the Barbell or Dumbbell over and behind your head towards the floor.","Return to starting position.","Repeat."]},{slug:"push-up-feet-elevated",title:"Push Up with Feet Elevated",idNum:"0075",type:"compound",primary:["chest"],secondary:["triceps","shoulders"],equipment:["body","bench"],steps:["This is the same general movement as with a Push Up except your feet are elevated allowing greater range of motions and targeting the pectorals differently than the regular Push Up.","Place your feet on a bench at least 18” off the ground.","Make sure the tops of your feet are flush against the bench.","Place your hands on the floor slightly wider than shoulder width apart.","With your hands directly under your shoulders, press up from the floor, keeping your back and neck in a straight line so you are looking forward during the entire exercise.","Once your arms are fully extended pause and then with slow controlled movements lower yourself to the floor again."]},{slug:"push-ups",title:"Push Ups",idNum:"0077",type:"isolation",primary:["chest"],secondary:["triceps","shoulders"],equipment:["body"],steps:["Start with a basic push up, lay face down on the floor, or a mat; with your feet together curled slightly so you rise onto the ball of your feet.","Place you hands shoulder width apart on the either side of your chest.","Draw your abs in.","Inhale as you raise your body up till your arms are straight.","Keep your head and neck level with your body (don’t look up or down) and don’t allow your back to rise or fall.","Exhale out as you lower your body back to the ground.","Repeat."]},{slug:"push-ups-with-feet-on-exercise-ball",title:"Push Ups with feet on exercise ball",idNum:"0076",type:"isolation",primary:["chest"],secondary:["triceps","shoulders"],equipment:["body","exercise ball"],steps:["Place your feet and shins flat on an Exercise Ball.","Place your arms in front of you at shoulder width apart, place your hands under your arms and press up from the ground until your arms are fully extended.","Pause at the top for a moment and steady your balance.","Slowly return to the starting position with your chest lowered towards the ground."]},{slug:"quick-alternating-biceps-curls-with-band",title:"Quick Alternating Biceps Curls with Band",idNum:"0261",type:"isolation",primary:["biceps"],secondary:["triceps"],equipment:["band"],steps:["Place a bungy under your feet and hold the handles palms forward in your hands.","Stand with your feet shoulder width apart, knees slightly bent and your abs drawn in.","Curl your arms up and down in an alternating motion, keeping your body straight.","As you become comfortable with the motion, increase your speed.","Note: Contract your biceps as you curl your arms up."]},{slug:"rear-deltoid-row-barbell",title:"Rear Deltoid Row Barbell",idNum:"0028",type:"isolation",primary:["shoulders"],secondary:["biceps"],equipment:["barbell"],steps:["Place a barbell on the floor in front of you with the resided weights attached.","With your knees bent and back straight grasp the bar with a wide overhand grip (palms facing downwards).","Keep your chest steady and your arms perpendicular to your chest.","Pull the bar as far up to your chest as you can.","Hold for a moment than lower the bar in a controlled manner.","Repeat."]},{slug:"rear-deltoid-row-dumbbell",title:"Rear Deltoid Row Dumbbell",idNum:"0024",type:"isolation",primary:["posterior deltoid"],secondary:["lateral deltoid","biceps","trapezius"],equipment:["dumbbell"],steps:["Place your right foot on the floor, rest your left knee and hand on a flat bench.","Lean forward so your body’s weight is supported by your left arm and knee.","Keeping your back flat, reach down and pick up the dumbbell with your right hand.","Raise your right arm as close to your chest as possible; while bending and bringing your elbow back as far as you can.","Pause at the top for a moment and then lower the dumbbell in a controlled manner to the starting position.","Switch arms by doing the opposite positioning.","Repeat."]},{slug:"rear-lunges-with-barbell",title:"Rear Lunges with Barbell",idNum:"0128",type:"compound",primary:["quadriceps"],secondary:["hip abductors","calves","gluts","hamstrings"],equipment:["barbell"],steps:["Place a barbell on a rack at chest height.","Lift the barbell of of the rack and onto your shoulders, gripping the bar slightly wider than shoulder width apart.","Stand with your feet approximately 8 inches apart with your toes pointing forward.","Slowly take a step backward with your right leg.","Keeping your abs drawn in and your upper body straight, lower your body until your left knee is almost on the ground. You may choose to place a mat or towel under your knee.","Hold for a moment and then return to starting position."]},{slug:"rear-lunges-with-dumbbell",title:"Rear Lunges with Dumbbell",idNum:"0129",type:"compound",primary:["quadriceps"],secondary:["calves","hamstrings","gluts","hip abductors"],equipment:["dumbbells"],steps:["This is an advanced version of a lunge.","Grasp a dumbbell in each hand.","Stand with your feet approximately 8 inches apart with your toes pointing forward.","Slowly take a step backward with your right leg.","Keeping your abs drawn in and your upper body straight, lower your body until your left knee is almost on the ground. You may choose to place a mat or towel under your knee.","Hold for a moment and then return to starting position."]},{slug:"reverse-grip-triceps-pushdown",title:"Reverse Grip Triceps Pushdown",idNum:"0189",type:"isolation",primary:["triceps"],secondary:[],equipment:["cable"],steps:["Stand in front of a cable machine and attach a bar to a high pulley.","Grasp the handle with palms facing up.","Keeping your elbows at your side, pull the handle down towards your thighs.","Pause for a moment and then return to the starting position.","Note: You may want to stager one foot in front of the other for a better stance."]},{slug:"reverse-grips-bent-over-barbell-rows",title:"Reverse Grips Bent Over Barbell Rows",idNum:"0026",type:"isolation",primary:["middle back"],secondary:["biceps"],equipment:["barbell"],steps:["Bend over a barbell at slight angle with your knees bent and your back straight.","Grasp the bar with a reverse grip (palms facing up) and slowly pull the barbell to your abs, keeping your elbows close to your sides.","Pause for a moment at the top.","Return the barbell to the starting position.","Repeat."]},{slug:"reverse-plate-curls-with-weight",title:"Reverse Plate Curls with Weight",idNum:"0241",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["weight plate"],steps:["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a plate in your hands with palms facing down, at the 11:00 and 1:00 o’clock position.","Keeping your elbows and arms at your side, curl the slowly up towards your head.","Slowly return to the starting position."]},{slug:"reverse-triceps-bench-press-with-barbell",title:"Reverse Triceps Bench Press with Barbell",idNum:"0190",type:"compound",primary:["triceps"],secondary:["chest"],equipment:["barbell"],steps:["Lie on a flat bench with your head at one end and your feet placed firmly on the floor.","Grasp a barbell with palms facing your head about 16 inches apart.","Move the bar over your chest (about 1 inch below your nipples).","Extend your arms fully raising the bar fully and then lower the bar to the starting position."]},{slug:"rocking-standing-calf-raise-with-barbell",title:"Rocking Standing Calf Raise with Barbell",idNum:"0278",type:"isolation",primary:["calves"],secondary:[],equipment:["barbell"],steps:["Stand with a bar across your shoulders.","With your feet flat on the floor, lift your feet up and forward as if you are performing a calf raise.","Then “rock” back onto your ankles so your toes are flexed and off the floor.","Return to starting position.","Note: Wear running or cross training shoes while performing this exercise. Try performing this exercise without weight to become familiar with the movement,"]},{slug:"romanian-dead-lift",title:"Romanian Dead Lift",idNum:"0118",type:"isolation",primary:["hamstrings"],secondary:["calves","quadriceps","gluts"],equipment:["barbell"],steps:["Place a barbell in front of your feet on the ground.","Grasp the barbell with a grip a bit wider than shoulder width apart.","Bend your knees slightly, keeping your hips and back straight.","Lift the bar straight up concentrating on using your hips as you stand.","Stand with the bar resting against your thighs.","Lower the bar to the floor with a slight bend in your knees flexing your hips back for stability."]},{slug:"seated-ab-crunch-with-cable",title:"Seated Ab Crunch with Cable",idNum:"0288",type:"isolation",primary:["abdominals"],secondary:[],equipment:["cable"],steps:["Attach a rope to a high cable pulley.","Place a bench in front of cable weight stack.","Grasp the rope over your shoulders and sit with your back towards the stack.","With your feet firmly on the floor and keeping your hips steady, flex at the waist bringing your elbows towards your knees.","Return to the starting position.","Note: Perform this exercise in a slow controlled manner."]},{slug:"seated-biceps-curl-with-dumbbell",title:"Seated Bicep Curl with Dumbbell",idNum:"0243",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["dumbbell"],steps:["Sit on bench with your feet firmly on the floor and your back straight.","Grasp a dumbbell in each hand with your palms facing each other.","Lower the dumbbells to your sides and slowly curl your arms up so your palms are facing up.","Squeeze your biceps at the top and slowly lower to the starting position.","Note: If possible use a short backed bench to help your posture."]},{slug:"seated-cable-rows",title:"Seated Cable Rows",idNum:"0025",type:"compound",primary:["middle back"],secondary:["biceps","lower back"],equipment:["cable machine"],steps:["Sit at a low pulley machine with your feet resting against the footrests and your knees slightly bent.","With your abs drawn in and your back straight lean forward slightly to grasp the pulleys with an overhand grip (palms face downwards).","Slowly bring the pulleys back towards your abs while sitting upright, keep your elbows in close to your chest.","Pause for a moment then return slowly return the pulleys to the starting position.","Repeat."]},{slug:"seated-calf-raise-using-machine",title:"Seated Calf Raise using Machine",idNum:"0279",type:"isolation",primary:["calves"],secondary:[],equipment:["machine"],steps:["Sit at a calf raise machine.","Put the balls of your feet on the footpad.","Place your thighs under the leg pad above your knees.","Unlock the bar and slowly raise your toes up as far as possible.","Pause for a moment and then return to the starting position.","Note: Practice slow and precise movements with this exercise."]},{slug:"seated-calf-raise-with-barbell",title:"Seated Calf Raise with Barbell",idNum:"0272",type:"isolation",primary:["calves"],secondary:[],equipment:["barbell"],steps:["Place a block on the floor about one foot in front of a bench.","Sit on the bench with a barbell across your upper thighs and the balls of your feet on the block.","Slowly raise and lower your toes up as high as possible without lifting your foot off the block."]},{slug:"seated-close-grip-concentration-curls-with-barbell",title:"Seated Close Grip Concentration Curls with Barbell",idNum:"0242",type:"isolation",primary:["biceps"],secondary:[],equipment:["barbell"],steps:["Concentration exercises limit your range of movement to increase the effectiveness of the movement. This version uses a barbell.","Sit on the end of a flat bench with your feet flat and your legs spread apart.","Bend forward at your waist keeping your back straight.","Grasp a barbell in your hands with a close grip approximately 6 inches apart with your palms facing up.","With your elbow pressed against your inner thigh, curl the bar up towards your chest.","Slowly lower the bar to the starting position near the floor.","Note: Keep all of your body still except the arm you are exercising."]},{slug:"seated-leg-curl",title:"Seated Leg Curl",idNum:"0119",type:"isolation",primary:["hamstrings"],secondary:[],equipment:["machine"],steps:["Adjust the machine so that the footpad is just above your heels.","Sit upright with your abs drawn in and your legs in front of you.","Slowly curl your legs back towards you and hold for a moment.","With controlled movement return to the starting position."]},{slug:"seated-military-press",title:"Seated Military Press",idNum:"0004",type:"isolation",primary:["shoulders"],secondary:["triceps"],equipment:["barbell","bench"],steps:["Sit on the bench with your toes pointing straight out, back straight and abs drawn in.","Grip the bar with your palms facing outwards and your hands shoulder width apart","With bar in front of your head, press upwards extending your arms but not locking them.","Pause at the top and then in a controlled movement lower the bar to the starting position."]},{slug:"seated-one-arm-triceps-extension-with-dumbbell",title:"Seated One Arm Triceps Extension with Dumbbell",idNum:"0191",type:"isolation",primary:["triceps"],secondary:[],equipment:["dumbbell"],steps:["Sit on the edge of a bench with your feet flat on the floor.","Hold a dumbbell in your right hand.","Bring your right arm up to your side so the dumbbell is almost parallel to your chest, keeping your lower arm vertical.","Press your arm back in arc.","Return to the starting position repeat and switch arms."]},{slug:"seated-one-leg-calf-raise-with-dumbbell",title:"Seated One Leg Calf Raise with Dumbbell",idNum:"0276",type:"isolation",primary:["calves"],secondary:[],equipment:["dumbbell"],steps:["This version of a calf raise allows you to exercise each leg individually. This exercise is helpful to people who are rehabilitating from injury as it allows you flexibility with the weight.","Place a block on the floor about one foot in front of a bench.","Sit on the bench with a dumbbell across your upper thigh and the balls of one foot on the block.","Slowly raise and lower your toe up as high as possible without lifting your foot off the block.","Switch feet and repeat."]},{slug:"seated-overhead-triceps-extension-with-barbell",title:"Seated Overhead Triceps Extension with Barbell",idNum:"0193",type:"isolation",primary:["triceps"],secondary:[],equipment:["barbell"],steps:["Sit on a short straight back chair with your feet firmly placed on the floor and your back straight.","Grasp an EZ or Curl bar, or barbell with a grip about 6 inches apart.","Raise the bar to arms length above your head and then lower the bar in an arc towards the floor behind your head.","Return to starting position."]},{slug:"seated-rear-lateral-cable-raise",title:"Seated Rear Lateral Cable Raise",idNum:"0035",type:"isolation",primary:["shoulders"],secondary:[],equipment:["cable machine"],steps:["Sit on the edge of a bench with your feet on the floor in front of you.","Rest your chest on your thighs with your back straight, grasp the cable pulleys with opposite hands.","Raise your upper arms to shoulder height. Pause at the top for a moment.","Lower your arms to the starting position in a controlled motion.","Repeat."]},{slug:"seated-triceps-press-with-dumbbell",title:"Seated Triceps Press with Dumbbell",idNum:"0194",type:"isolation",primary:["triceps"],secondary:[],equipment:["dumbbell"],steps:["Sit on a short, straight backed bench with your feet planted firmly on the floor.","Drawing your abs in, grasp the dumbbell with both hands with a palms up grip.","Raise the weight over your head, this is your starting position.","Lower the dumbbell in an arc from above your head to behind your back.","Slowly return to the starting position."]},{slug:"seated-two-arm-triceps-extension-with-dumbbell",title:"Seated Two-Arm Triceps Extension with Dumbbell",idNum:"0192",type:"isolation",primary:["triceps"],secondary:[],equipment:["dumbbell"],steps:["Sit on the edge of a bench with your feet flat on the floor.","Hold a dumbbell in each hand.","Bring your arms up to your side so the dumbbell is almost parallel to your chest, keeping your lower arm vertical.","Press your arm back in arc towards your back.","Return to the starting position repeat and switch arms."]},{slug:"shoulder-shrugs",title:"Shoulder Shrugs",idNum:"0005",type:"isolation",primary:["trapezius"],secondary:[],equipment:["dumbbell"],steps:["Stand with your feet shoulder width apart and a slight bend in your knees.","Hold a dumbbell in each hand and with your arms at your sides.","Lower your shoulders as much as possible.","With your arms straight raise both shoulders up towards your ears.","Hold the upright positions for a moment and then lower in a controlled motion."]},{slug:"side-bend-with-dumbbell",title:"Side Bend with Dumbbell",idNum:"0294",type:"isolation",primary:["abdominals"],secondary:[],equipment:["dumbbell"],steps:["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in one hand and standing straight upright, bend at the waist as far as possible to one side.","Slowly return back up to the staring position.","Switch the dumbbell to your other hand and repeat the exercise.","Note: Be careful to bend only at your waist and not at the hips or knees."]},{slug:"side-plank",title:"Side Plank",idNum:"0113",type:"isolation",primary:["core"],secondary:[],equipment:["body"],steps:["Lay on one side of your body with your legs straight and your forearm perpendicular to your body in front of you.","Drawing your abs in, slowly raise yourself up so you are balanced on your feet and your forearm.","Hold this position and slowly return back to the starting position.","Repeat on other side."]},{slug:"side-squats-with-barbell",title:"Side Squats with Barbell",idNum:"0131",type:"compound",primary:["quadriceps"],secondary:["hip abductors","hamstrings"],equipment:["barbell"],steps:["Place a barbell on your shoulders and grasp it with a wide grip.","Stand with your feet wide apart, with the foot of the leg you will be leaning towards angled out.","Bring your lower body to your foot by bending the hip and knee of your lead leg, and keeping your other leg fairly straight.","Return to the starting position and switch legs."]},{slug:"single-arm-triceps-extension-with-dumbbell",title:"Single Arm Pronated Triceps Extension with Dumbbell",idNum:"0186",type:"isolation",primary:["triceps"],secondary:[],equipment:["dumbbell"],steps:["This is an advanced exercise to isolate and work the tricep (back of the arm) muscles.","Lie flat in a bench with your head at one end and your feet placed firmly on the floor.","Grasp a dumbbell in one hand and raise it to a position above your chest, with your palm facing your feet.","Place your free hand under the shoulder to support your other arm.","Slowly lower the weight moving only your forearm and elbow towards and away from your chest.","Repeat with your other arm.","Note: Practice this exercise with light weight to get used to the movements."]},{slug:"single-arm-supinated-triceps-extension-with-dumbbell",title:"Single Arm Supinated Triceps Extension with Dumbbell",idNum:"0187",type:"isolation",primary:["triceps"],secondary:[],equipment:["dumbbell"],steps:["Lie flat in a bench with your head at one end and your feet placed firmly on the floor.","Grasp a dumbbell in one hand and raise it to a position above your chest, with your palm facing the floor.","Place your free hand under the shoulder to support your other arm. Slowly bend your elbow over your head with the weight moving only your forearm and elbow.","Return to the starting position and repeat with your other arm.","Note: Practice this exercise with light weight to get used to the movements."]},{slug:"single-leg-squat-with-barbell",title:"Single Leg Squat with Barbell",idNum:"0132",type:"compound",primary:["quadriceps"],secondary:["calves","hamstrings"],equipment:["barbell"],steps:["This is an advanced exercise and modification of the basic squat. Mastery of the squat is recommended before attempting this exercise.","Place a barbell on your back, above your shoulders with a wide grip.","Cross the lower leg above the knee of your supporting leg (the leg you will squat with).","Squat down as low as you are able.","Slowly return to an upright position by straightening your hip and knee.","Switch legs and repeat."]},{slug:"smith-machine-bench-press",title:"Smith Machine Bench Press",idNum:"0078",type:"isolation",primary:["chest"],secondary:["shoulders","triceps"],equipment:["flat bench","smith machine"],steps:["Place a flat bench in the middle of the Smith Machine, with the bar in line with the middle of your chest.","Lying on the bench, grasp the bar at shoulder width apart.","Unlatch the bar and slowly lower the bar to your chest.","Extend your arms fully and raise the bar to the starting position.","Repeat."]},{slug:"smith-machine-close-grip-bench-press",title:"Smith Machine Close Grip Bench Press",idNum:"0195",type:"compound",primary:["triceps"],secondary:["chest"],equipment:["smith machine"],steps:["Place a flat bench in the middle of a Smith Machine.","Using a close grip (about 6 inches apart) unlatch the bar and lower it towards your chest.","Pause just before the bar hits your chest and raise the bar by extending your arms to the starting position."]},{slug:"smith-machine-dead-lifts",title:"Smith Machine Dead Lifts",idNum:"0100",type:"isolation",primary:["lower back"],secondary:["hamstrings","calves"],equipment:["smith machine"],steps:["Stand with your feet shoulder width apart so that your feet are under the bar.","Keeping your back straight bend at the waist, allow some bend in your knees.","Grasp the par with an overhand grip approximately 16 inches apart.","Straighten your back as you hold the bar at arm’s length.","Bend over again lowering the bar to just above the floor."]},{slug:"smith-machine-good-mornings",title:"Smith Machine Good Mornings",idNum:"0102",type:"isolation",primary:["lower back"],secondary:["hamstrings"],equipment:["smith machine"],steps:["Place a barbell across your shoulders.","Keeping your head up and your back completely straight, bend at the waist until your back is parallel with the floor.","Return to starting position.","Repeat."]},{slug:"smith-machine-hack-squat",title:"Smith Machine Hack Squat",idNum:"0126",type:"compound",primary:["quadriceps"],secondary:["hamstrings","gluts"],equipment:["smith machine"],steps:["This is another variation of the basic Squat that focuses primarily on the quadriceps, or thigh muscles, while using the Smith Machine.","Adjust the bar to a low setting just above your ankles.","Stand with the bar on the floor just behind your legs, with your feet shoulder width apart and your toes pointing forward.","With your feet firmly placed on the floor reach down and grasp the bar from behind, with an overhand grip.","Lift the bar by extending your hips and knees, taking care not to lock your knees.","Lower yourself (squat) down until your thighs are parallel to the floor.","Slowly raise yourself up to starting position.","Note: Your knees should be moving in the same direction as your feet."]},{slug:"smith-machine-incline-bench-press",title:"Smith Machine Incline Bench Press",idNum:"0081",type:"isolation",primary:["chest"],secondary:["shoulders","triceps"],equipment:["smith machine","incline bench"],steps:["Place an incline bench at a 45 degree angle in the middle of the Smith Machine.","Align the bench so the bar is across the upper portion of your chest.","Grasp the bar with a shoulder width grip.","Unlock the bar and slowly lower the weight to your chest, do not bounce the bar on your chest.","With slow controlled movements, raise the bar back to the starting position."]},{slug:"smith-machine-rear-deltoid-row",title:"Smith Machine Rear Deltoid Row",idNum:"0022",type:"isolation",primary:["rear deltoid"],secondary:["back","biceps","shoulders"],equipment:["smith machine"],steps:["This is an exercise for rear deltoid,shoulder, biceps and back strengthening."," Set the bar to the lowest setting.","Place your feet shoulder width apart with a slight bend in the knees.","Bend at the waist while keeping your back straight and chest parallel to the floor.","Grasp the bar slightly wider than your shoulders with an overhand grasp and your arms straight with a slight bend in the elbows.","Raise the bar with a controlled motion to the lower part of your chest by bending and elevating your elbows.","Hold for a moment and then lower to the starting position.","Repeat."]},{slug:"smith-machine-reverse-calf-raises",title:"Smith Machine Reverse Calf Raises",idNum:"0280",type:"isolation",primary:["calves"],secondary:[],equipment:["smith machine"],steps:["Place a block or low box under the bar at a Smith Machine.","Stand on the edge of the box with your toes hanging off.","Place the bar across your shoulders and lean forward lifting your ankles off the box.","Return to the starting position.","Note: Use the bar for support as you perform this exercise."]},{slug:"smith-machine-shoulder-shrugs",title:"Smith Machine Shoulder Shrugs",idNum:"0041",type:"isolation",primary:["shoulders"],secondary:[],equipment:["smith machine"],steps:["Place the barbell at waist height.","Stand with your feet shoulder width apart and your abs drawn in.","Grasp the bar with an overhand grip and straightened arms.","As you lift the bar allow the weight to pull your shoulders down, shrug your shoulders up and to the back.","Hold for a moment and then return to starting position."]},{slug:"smith-machine-squats",title:"Smith Machine Squats",idNum:"0124",type:"compound",primary:["quadriceps"],secondary:["calves","gluts","hamstrings"],equipment:["smith machine"],steps:["This exercise uses the Smith Machine to work the Quadriceps, Hamstrings, Calves and Glutes. A great overall exercise for the lower body. There are many variations on the squat, this is the original version using a Smith Machine for better flow of movement.","Set the height of the barbell to shoulder height.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift over your toes (this will cause you to loose balance).","Pause in the downward squatting position and slowly return upright to the starting position.","If needed, a pad on the bar or towel on your shoulders can help improve your grip and the reduce the discomfort of the bar against your back. First practice the squat without any weight to allow yourself to become comfortable with the movements."]},{slug:"smith-machine-upright-row",title:"Smith Machine Upright Row",idNum:"0013",type:"isolation",primary:["shoulders"],secondary:["biceps","upper back"],equipment:["smith machine"],steps:["Stand with your feet shoulder width apart and your abs drawn in.","Place the bar on the Smith Machine in the position where your arms are fully extended in front of you.","Place your hands shoulder width apart and raise the bar up towards your chin with a controlled motion.","Pause at the top for a moment and rotate your shoulder blades together.","Lower the bar to the starting position."]},{slug:"speed-squats-with-barbell",title:"Speed Squats with Barbell",idNum:"0154",type:"compound",primary:["quadriceps"],secondary:["calves","glutes","hamstrings"],equipment:["barbell"],steps:["This version of the squat uses an empty barbell and moves at a faster pace than the standard squat. This is a good exercise for building speed and conditioning used in running and jumping sports.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in, descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Note: Keep your feet firmly planted on the floor throughout this exercise."]},{slug:"spider-curl-with-barbell",title:"Spider Curl with Barbell",idNum:"0245",type:"isolation",primary:["biceps"],secondary:[],equipment:["barbell"],steps:["This exercise uses the straight side of a Preacher Curl bench to increase the range of motion of the exercise.","Turn a Preacher Curl bench around so you are leaning against the angled side.","Grasp a barbell with palms up, approximately 6 inches apart.","Leaning against the bench, lower the bar along the flat side of the bench fully extending your arms.","Curl your arms up so your biceps are touching your forearms.","Slowly lower the bar to the starting position.","Note: Use a low weight to get used to the motion of this exercise."]},{slug:"squat-to-bench-with-barbell",title:"Squat to Bench with Barbell",idNum:"0133",type:"compound",primary:["quadriceps"],secondary:["gluts","calves","hamstrings"],equipment:["barbell"],steps:["This is s great overall exercise for the lower body. There are many variations on the squat, this one uses a bench to remind you how far down to squat.","Place a bench behind you.","Lifting a barbell off of a weight rack, position it on your shoulders.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in, descend slowly and squat down, bending at the knees and hips.","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance). Do not sit on the bench.","Pause in the downward position and slowly return upright to the starting position.","A pad on the bar or towel on your shoulders can help improve your grip and reduce discomfort of the bar against your back. Practice the squat without any weight to allow yourself to become comfortable with the movements. Do not sit on the bench during the exercise."]},{slug:"squat-to-bench-with-dumbbells",title:"Squat to Bench with Dumbbells",idNum:"0136",type:"compound",primary:["quadriceps"],secondary:["calves","hamstring","gluts"],equipment:["dumbbell"],steps:["This is a great overall exercise for the lower body. There are many variations on the squat, this one uses a bench to remind you how far down to squat.","Place a bench behind you.","Grasp a dumbbell in each hand.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in descend slowly by squatting down and bending at the knees and hips.","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Practice the squat without any weight to allow yourself to become comfortable with the movements. Do not sit on the bench during the exercise."]},{slug:"squats-using-dumbbells",title:"Squats using Dumbbells",idNum:"0130",type:"compound",primary:["quadriceps"],secondary:["hamstring","calves"],equipment:["dumbbells"],steps:["This is a great overall exercise for the lower body that uses dumbbells instead of a barbell. Beginners may find this version easier to perform.","Grasp a dumbbell in each hand.","Stand with feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Note: Practicing the squat without any weight will allow you to become comfortable with the movements."]},{slug:"squats-with-exercise-bands",title:"Squats with Exercise Bands",idNum:"0155",type:"compound",primary:["quadriceps"],secondary:["calves","glutes","hamstrings"],equipment:["exercise band"],steps:["Stand with your feet on the exercise bands with your feet shoulder width apart.","Grasp the handles of the bands and pull them up to your shoulders.","With your abs drawn in, squat down until your thighs are parallel with the floor.","Slowly return to the starting position.","Note: Keep your feet firmly planted on the floor throughout this exercise."]},{slug:"stability-ball-abdominal-crunch",title:"Stability Ball Abdominal Crunch",idNum:"0295",type:"isolation",primary:["abdominals"],secondary:[],equipment:["body"],steps:["This crunch uses a Stability Ball. The ball allows you a better range of movement because it adapts better to your spine.","Sit on top of an exercise or stability ball with your feet placed firmly on the floor for support.","Position yourself so that your lower back is centered on the middle of the ball.","Lie back and bring your hands across your chest, or on either side of your head (over your ears).","Raise your head, chest and shoulders up crunching your abs as you sit upright.","Pause for a moment and then lower yourself to the starting position.","Note: For best results, use a full range of motion in this exercise."]},{slug:"standing-barbell-calf-raise",title:"Standing Barbell Calf Raise",idNum:"0281",type:"isolation",primary:["calves"],secondary:[],equipment:["barbell"],steps:["Place a block or two free weight plates on the floor.","Place a barbell across your back and step up so the balls of your feet are on the block.","Slowly lift your heels up and then lower them back to the floor getting as much of a stretch as possible.","Return to starting position."]},{slug:"standing-biceps-curl-with-cable",title:"Standing Biceps Curl with Cable",idNum:"0212",type:"isolation",primary:["biceps"],secondary:["forearm","shoulders"],equipment:["cable"],steps:["Attach a short bar to a cable pulley to the bottom of the weight stack.","Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp the bar with palms facing up, and hands fairly close together.","Lower your arms fully to above your thighs and bending only your elbows, raise the bar to your upper chest.","Pause for a moment and then return to the starting position.","Note: Do not swing your hips or back during this exercise."]},{slug:"standing-calf-raises-using-machine",title:"Standing Calf Raises using Machine",idNum:"0282",type:"isolation",primary:["calves"],secondary:[],equipment:["machine"],steps:["This exercise uses a machine to allow for proper form.","Stand with your toes on the footpad of the machine and adjust your shoulders under the upper pads.","Raise up on the balls of your feet, lifting your heels off the pad.","Hold for a moment and then return to the starting position."]},{slug:"standing-inner-biceps-curl-with-dumbbell",title:"Standing Inner Biceps Curl with Dumbbell",idNum:"0246",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["dumbbell"],steps:["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each arm with your palms facing each other, fully extend your arms along your sides.","Curl your arms up and out, turning your palms up and out as you lift.","Slowly lower the dumbbells to the starting position.","Note: Try to keep your forearms in line with your shoulders as you lift the weight."]},{slug:"standing-leg-curls",title:"Standing Leg Curls",idNum:"0120",type:"isolation",primary:["hamstrings"],secondary:[],equipment:["machine"],steps:["Standing at a leg curl machine adjust the rear footpad so it is just above your ankle.","Grasp the handles of the machine for support and draw your abs in.","Raise your foot up towards your back slowly.","Return to the starting position and chance legs."]},{slug:"standing-one-arm-biceps-curl-with-cable",title:"Standing One Arm Bicep Curl with Cable",idNum:"0247",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["cable"],steps:["This is a single arm version of a bicep cable curl. Cable machines are great for helping you learn proper form while building muscle.","Attach a stirrup bar to a low cable pulley.","Stand of the side of the weight stack with your legs shoulder width apart and your knees slightly bent and your abs drawn in.","Grasp the stirrup in one hand with an palms facing up.","Lower the stirrup to the top of your thighs.","Keeping your elbows still, curl the stirrup up towards your chest.","Slowly lower the stirrup to the starting position."]},{slug:"standing-one-arm-curl-over-incline-bench-with-dumbbell",title:"Standing One Arm Curl Over Incline Bench with Dumbbell",idNum:"0248",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["dumbbell"],steps:["This exercise is a great alternative to the Preacher Curl.","Stand in front of an incline bench so your arm is resting on the top of the angled portion of the bench.","Grasp a dumbbell in your hand with palms facing up.","Rest your arm against the back bench and extend it fully down.","Keeping your arm on the bench at all times, curl the dumbbell up towards your head.","Pause for a moment and then lower the dumbbell back to starting position.","Switch arms and repeat.","Note: Perform this exercise in a slow controlled manner for best results."]},{slug:"standing-overhead-triceps-extension-with-barbell",title:"Standing Overhead Triceps Extension with Barbell",idNum:"0201",type:"isolation",primary:["triceps"],secondary:[],equipment:["barbell"],steps:["Stand with your feet shoulder width apart, your back straight and your abs drawn in.","Hold a barbell or EZ Curl bar about 6-8 inches apart with your palms facing up.","Raise the bar over your head and slowly lower the dumbbell in an arc behind your head, towards your back.","Slowly raise the bar back up to the starting position.","Note: Keep your elbows close to your head during the exercise"]},{slug:"standing-triceps-extension-2",title:"Standing Triceps Extension",idNum:"0198",type:"isolation",primary:["triceps"],secondary:[],equipment:["dumbbell"],steps:["Stand with your feet shoulder width apart, your back straight and your abs drawn in.","Hold a dumbbell in both hands, with your palms facing up.","Raise the dumbbell over your head and slowly lower the dumbbell in an arc behind your head.","Slowly raise the dumbbell back up to the starting position.","Note: Keep your elbows close to your head during the exercise."]},{slug:"standing-triceps-extension-with-towel",title:"Standing Triceps Extension with Towel",idNum:"0202",type:"isolation",primary:["triceps"],secondary:[],equipment:["body"],steps:["Stand with your feet shoulder width apart, your back straight and your abs drawn in.","Hold a towel or rope facing up behind and in back of your head.","Have a partner hold the towel taught during the exercise so the resistance is constant.","Lower your forearms down until they reach your biceps, then slowly raise your arms back up to starting position.","Note: Keep your elbows close to your head during the exercise."]},{slug:"static-neck-flexion-extension",title:"Static Neck Flexion and Extension",idNum:"0001",type:"isometric",primary:["neck extensors","neck flexors"],secondary:[],equipment:["body"],steps:["An exercise to either build or warm-up front and back neck muscles.","Stand or sit with your head in neutral position.","Place both of your hands on your forehead.","Press your head against your hands and contract your neck muscles.","Keep your head from moving forward. Hold for at least 30 seconds.","Repeat with hands on the back of your head, pressing against them."]},{slug:"static-neck-side-flexion",title:"Static Neck Side Flexion",idNum:"0002",type:"isometric",primary:["neck side flexors"],secondary:[],equipment:["body"],steps:["Stand or sit with your head in neutral position.","Place your left hand against the left side of your head, above your ear.","Push your head against your hand, without moving your head.","Repeat with your right hand, right side of your head."]},{slug:"stationary-abdominal-draw-in",title:"Stationary Abdominal Draw In",idNum:"0027",type:"isometric",primary:["abdominals"],secondary:["core"],equipment:["body"],steps:["Get down on a mat on your hands and knees, forming a four point rectangle or square shape.","Keep your back straight and your hips and pelvis in a neutral position.","Draw your abs in, crunching your abs while keeping your back still.","Hold for a moment and then release returning to the starting position.","Repeat."]},{slug:"step-up-single-leg-balance-with-biceps-curl-using-dumbbells",title:"Step Up Single Leg Balance with Bicep Curl using Dumbbells",idNum:"0266",type:"isolation",primary:["biceps"],secondary:["core","quadriceps","forearm","hamstrings","glutes","calves"],equipment:["dumbbell"],steps:["This is an advanced exercise. This exercise combines a step up with a bicep curl.","Place a box or bench in front of you.","Place a dumbbell in each hand with palms facing up.","Keep your back straight, your shoulders back and your abs drawn in.","With one leg, step up on to the box and raise your other leg up (as if taking another step).","At the top of the step, curl your arms up by bringing your biceps towards your shoulders.","Return to the starting position and switch legs."]},{slug:"step-ups-with-barbell",title:"Step Ups with Barbell",idNum:"0134",type:"compound",primary:["quadriceps"],secondary:["hamstrings","calves"],equipment:["barbell"],steps:["Place a bench, box or step in front of you.","Grasp a barbell with a wide grip and place it across your shoulders.","With your left leg, step up on the bench, and follow by stepping up with your right leg.","Step down with your left leg and then your right leg.","Repeat starting with your right leg.","Note: Use a lighter weight until you are used to the motion of this exercise."]},{slug:"step-ups-with-dumbbells",title:"Step Ups with Dumbbells",idNum:"0137",type:"compound",primary:["quadriceps"],secondary:["calves","hamstrings"],equipment:["dumbbells"],steps:["Place a bench, box or step in front of you.","Grasp a dumbbell in each hand.","With your left leg, step up on the bench, and follow by stepping up with your right leg.","Step down with your left leg and then your right leg.","Repeat starting with your right leg.","Note: Use a lighter weight until you are used to the motion of this exercise."]},{slug:"stork-stance-biceps-curl-with-dumbbells",title:"Stork Stance Bicep Curl with Dumbbells",idNum:"0268",type:"isolation",primary:["biceps"],secondary:["quadriceps","hamstrings","glutes","calves","triceps"],equipment:["dumbbell"],steps:["Grasp a pair of dumbbells in each hand, palms facing up.","Standing on one foot, extend your other foot back (see illustration) and extend your arms down so they are handing in front of your leg.","While on one foot, curl your arms up contracting your biceps.","Return to the starting position and switch legs.","Note: Have a Personal Trainer or Instructor show you how to properly perform this exercise."]},{slug:"straight-arm-dumbbell-pullover",title:"Straight Arm Dumbbell Pullover",idNum:"0079",type:"isolation",primary:["chest"],secondary:["triceps","lats","shoulders"],equipment:["flat bench","dumbbell"],steps:["Lie on a flat bench with your feet flat on the floor and your head at the end of the bench.","Grasp a dumbbell and raise it over your chest.","Keeping your elbows as straight as possible, lower the weight in an arc over your head and as low to the ground as possible with out any pain.","Return to starting position.","Repeat."]},{slug:"straight-arm-push-down",title:"Straight Arm Push Down",idNum:"0092",type:"isolation",primary:["lats"],secondary:["triceps"],equipment:["cable machine"],steps:["Grasp wide grip pull down bar with a wide grip so your hands are on the portion of the bar which curves down.","Stand erect with your abs drawn in.","Keeping a slight bend in your elbows and your wrist steady pull the bar down from the starting position to your upper thighs.","With a controlled motion bring the bar back up to starting position."]},{slug:"supermans",title:"Supermans",idNum:"0105",type:"isolation",primary:["lower back"],secondary:["core"],equipment:["body"],steps:["Lie flat on your stomach with your arms stretched out in front of you.","Raise your arms and legs off the floor and hold this position for 2 seconds.","Return to the starting position on the floor.","Repeat."]},{slug:"t-bar-rows",title:"T-Bar Rows",idNum:"0029",type:"isolation",primary:["middle back"],secondary:["biceps","shoulders"],equipment:["t-bar machine"],steps:["Place your feet on either side of a T-Bar Machine.","With your knees slightly bent and abs drawn in, grasp the handles with a narrow grip.","Bend at the waist so your chest is parallel to the floor, this is starting position. Slowly pull the bar to your chest, as high as you can.","Pause at the top for a moment and then lower the bar to starting position.","Repeat"]},{slug:"tate-press-with-dumbbell",title:"Tate Press with Dumbbell",idNum:"0203",type:"isolation",primary:["triceps"],secondary:[],equipment:["dumbbell"],steps:["Lay flat on a bench with your head at one end and your feet firmly planted on the floor.","Hold a dumbbell in each hand so your palms are facing your feet.","Drawing your abs in and keeping your back on the bench, raise the weights to the center of your chest.","Without moving elbows, slowly raise your arms up and out contracting your triceps."]},{slug:"thigh-abductor",title:"Thigh Abductor",idNum:"0156",type:"isolation",primary:["quadriceps"],secondary:["hamstrings"],equipment:["machine"],steps:["Sit on the machine and place your knees against the pads.","Draw your abs in and “abduct” or move your thighs apart against the pads.","Slowly return to the starting position and repeat.","Note: Maintain the same level of resistance throughout this exercise for best results."]},{slug:"thigh-adductor",title:"Thigh Adductor",idNum:"0157",type:"isolation",primary:["quadriceps"],secondary:["hamstrings"],equipment:["machine"],steps:["Sit on the machine and place your knees against the pads.","Draw your abs in and “adduct” or move your thighs together.","Slowly return to the starting position and repeat.","Note: Maintain the same level of resistance throughout this exercise for best results."]},{slug:"tricep-dips-using-body-weight",title:"Tricep Dips using Body Weight",idNum:"0172",type:"compound",primary:["triceps"],secondary:["shoulders","chest"],equipment:["body"],steps:["Grasp a set of parallel bars and push yourself up to the starting position.","Keeping your elbows close to your body, lower yourself down until your triceps are parallel to the floor.","Slowly raise yourself back to the starting position.","Note: Keep your abs drawn in and your body straight during this exercise."]},{slug:"tricep-dips",title:"Tricep Dips using Machine",idNum:"0171",type:"compound",primary:["triceps"],secondary:["shoulders"],equipment:["machine"],steps:["Adjust the seat of the machine so that the handles are equal with your elbows.","Grasping the handles, press down with equal pressure until your arms are fully extended.","Pause, and then return to the starting position."]},{slug:"triceps-extensions-using-machine",title:"Triceps Extensions using Machine",idNum:"0210",type:"isolation",primary:["triceps"],secondary:[],equipment:["machine"],steps:["Name: This exercise uses a machine to insure proper range of motion. This is a good exercise for beginners and people rehabilitating from injury.","Adjust the seat height of the machine so your upper arms and elbows lie flat on the pad. Draw your abs in and sit upright with your back straight. With your arms fully extended grasp the handles and pull them towards your body. Hold for a moment and then slowly return to the starting position.","Note: Stay seated and keep your feet firmly on the floor throughout this exercise."]},{slug:"triceps-kickback-with-dumbbell",title:"Triceps Kickback with Dumbbell",idNum:"0204",type:"isolation",primary:["triceps"],secondary:[],equipment:["dumbbell"],steps:["Standing along side a flat bench, bend your left knee and place it on the bench.","Place your left hand on the bench for support, keeping your back at a 45 degree angle.","Hold a dumbbell in your right hand and place your right foot on the floor.","Bend your right arm and raise it up to your shoulder, then with controlled motion kick it back, fully extending your arm.","Switch arms and repeat.","Note: Keep your elbow close to your body during this exercise."]},{slug:"triceps-pushdown-with-cable",title:"Triceps Pushdown with Cable",idNum:"0205",type:"isolation",primary:["triceps"],secondary:[],equipment:["cable"],steps:["Stand in front of a cable machine and attach a short bar to a high pulley.","Grasp the handle with your palms facing down.","Draw your abs in and keep your back straight.","Keeping your elbows at your side push the handle down towards your thighs.","Pause for a moment and then return to the starting position.","Note: You may want to stager one foot in front of the other for a better stance."]},{slug:"triceps-pushdown-with-rope-and-cable",title:"Triceps Pushdown with Rope and Cable",idNum:"0206",type:"isolation",primary:["triceps"],secondary:[],equipment:["cable"],steps:["Stand in front of a cable machine and attach a rope to a high pulley.","Grasp the rope with palms facing down.","Draw your abs in and keep your back straight.","Keeping your elbows at your side push the rope down towards your thighs, if possible “split” the rope apart at the bottom.","Pause for a moment and then return to the starting position.","Note: You may want to stager one foot in front of the other for a better stance."]},{slug:"triceps-pushdown-with-v-bar-and-cable",title:"Triceps Pushdown with V Bar and Cable",idNum:"0207",type:"isolation",primary:["triceps"],secondary:[],equipment:["cable","v-bar"],steps:["This exercise is the triceps pushdown uses a V shaped bar. Many people find this version easier on the elbows.","Steps","Stand in front of a cable machine and attach a V Bar to a high pulley.","Grasp the bar with palms facing down.","Draw your abs in and keep your back straight.","Keeping your elbows at your side push the bar down towards your thighs.","Pause for a moment and then return to the starting position.","Note: You may want to stager one foot in front of the other for a better stance."]},{slug:"two-arm-preacher-curl-with-dumbbell",title:"Two-Arm Preacher Curl with Dumbbell",idNum:"0249",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["dumbbell"],steps:["A Preacher Curl uses a special bench to support the triceps and isolate the biceps to build the arms. This version of the exercise uses dumbbells.","Adjust the seat of the bench so your arms are level with the top of the bench.","Grasp a dumbbell in each hand with palms facing up.","Picking up the dumbbells, rest your arms against the bench and extend them fully towards the floor.","Keeping your arms on the bench at all times, curl the weight up towards your head.","Pause for a moment and then lower the weights back to starting position.","Note: Perform this exercise in a slow controlled manner for best results."]},{slug:"underhand-pull-down",title:"Underhand Pull down",idNum:"0095",type:"isolation",primary:["lats"],secondary:["biceps"],equipment:["cable machine"],steps:["Sitting upright with your abs drawn in grasp a Pull Down bar with and underhand grip shoulder width apart.","Pull the bar down till the bar reaches your upper chest, keeping your elbows close to your body.","Slowly return the bar to the starting position.","Repeat."]},{slug:"underhand-pull-downs",title:"Underhand Pull downs",idNum:"0093",type:"isolation",primary:["lats"],secondary:["biceps"],equipment:["cable machine"],steps:["Sitting upright with your abs drawn in grasp a Pull Down bar with and underhand grip shoulder width apart.","Pull the bar down till the bar reaches your upper chest, keeping your elbows close to your body.","Slowly return the bar to the starting position.","Repeat."]},{slug:"upright-band-rows",title:"Upright Band Rows",idNum:"0094",type:"isolation",primary:["lats"],secondary:["triceps","shoulders"],equipment:["body","bands"],steps:["Stand on the band so that the handles are level with your upper thigh.","With your back straight and abs drawn in raise your hands upward to your collarbone.","Your elbows and arms should be parallel with the floor.","Slowly lower your arms and return to starting position."]},{slug:"upright-barbell-rows",title:"Upright Barbell Rows",idNum:"0014",type:"isolation",primary:["shoulders"],secondary:["biceps","upper back"],equipment:["barbell"],steps:["Stand with your feet shoulder width apart, your abs drawn in and back straight.","Place the bar on rack in the position where your arms are fully extended in front of you with your elbows slightly bent.","Place your hands shoulder width apart and raise the bar up towards your chin with a controlled motion.","Pause at the top for a moment and rotate your shoulder blades together.","Lower the bar to the starting position.","Repeat"]},{slug:"upright-cable-row",title:"Upright Cable Row",idNum:"0015",type:"isolation",primary:["shoulders"],secondary:["upper back","biceps"],equipment:["cable machine"],steps:["Attach a straight bar to the pulley on the floor.","Stand with your feet shoulder width apart, your abs drawn in and your back straight.","Grasp the bar with an overhand grasp (your palms facing downwards) and pull it up towards your waist, this is the starting position.","Raise the bar up to in line with your shoulders.","Pause at the top and rotate your shoulder blades together.","Lower the bar in a controlled motion to the starting position."]},{slug:"v-bar-pull-down",title:"V Bar Pull Down",idNum:"0096",type:"isolation",primary:["lats"],secondary:["middle back","biceps"],equipment:["cable machine"],steps:["Attach a V bar to the pull down pulley of a cable machine.","Sitting upright with your abs drawn grasp the bar with an overhand grip, your palms facing in.","Pull the bar straight down to your upper chest.","Pause for a moment after touching the chest and then slowly return the bar to starting position.","Repeat."]},{slug:"walking-lunges",title:"Walking Lunges",idNum:"0121",type:"isolation",primary:["hamstrings"],secondary:["quadriceps","gluts","calves"],equipment:["barbell or dumbbell"],steps:["Start by either placing a barbell across your upper back or by grasping a dumbbell in each hand.","Stand with your feet about 8 inches apart, toes facing forward.","Take a lunge forward keeping your abs drawn in and your upper body straight.","Slowly lower one knee down as if kneeling while keeping your other knee bent at a 90 degree angle, do not let your knee touch the ground.","Lower your body to just above the floor and hold for a moment before pushing off with the back foot.","Step through and repeat the exercise with the other leg."]},{slug:"weighted-ball-side-bend",title:"Weighted Ball Side Bend",idNum:"0208",type:"isolation",primary:["obliques"],secondary:[],equipment:["weight","exercise ball"],steps:["This exercise use a Stability Ball instead of a bench. The Stability Ball conforms better to your body and allows for correct anatomical range of movement.","Lie one side of your torso, and with your waist and hip against a Stability Ball, position your feet on the floor (or against a wall) for support.","With one hand, hold a weight against the side of your head.","Place your free hand across your chest to steady yourself.","Raise your torso up off the ball by flexing your waist.","With controlled movements lower yourself back onto the ball."]},{slug:"weighted-sissy-squat-with-weight-plate",title:"Weighted Sissy Squat with Weight Plate",idNum:"0158",type:"isolation",primary:["quadriceps"],secondary:[],equipment:["weight plate"],steps:["Don't let the name of this exercise fool you, it is a an assisted squat which effectively works the quadriceps (leg muscles).","Grasp a weight rack or bar for support with one arm and hold a free weight plate across your chest with your other hand.","With your abs drawn in, squat down lowering your body to the floor until your knees are almost fully flexed.","Return to the starting position.","Note: Keep your feet placed firmly on the floor throughout this exercise."]},{slug:"wide-grip-bench-press",title:"Wide Grip Bench Press",idNum:"0082",type:"isolation",primary:["chest"],secondary:["triceps","shoulders"],equipment:["flat bench","barbell"],steps:["Lie flat on a bench with your feet flat on the floor.","Place your hands wider than shoulder width apart on the bar and lift it off the rack, this is starting position.","Bring the bar over your chest and lower it till it is just above your body.","Extend your arms upward and raise the bar straight up.","Pause for a moment and with slow controlled movement, return the bar to starting position.","Repeat."]},{slug:"wide-grip-chin-up",title:"Wide Grip Chin Up",idNum:"0091",type:null,primary:["back"],secondary:["neck","biceps"],equipment:[],steps:["Grasp a chin up bar with a slightly wider than shoulder width grip.","Keeping your body straight pull yourself up and to one side of the bar.","Lower your body back down to the starting position.","Raise yourself to the other side of the bar.","Repeat."]},{slug:"wide-grip-decline-barbell-pullover",title:"Wide Grip Decline Barbell Pullover",idNum:"0064",type:"isolation",primary:["chest"],secondary:[],equipment:["decline bench","barbell"],steps:["Lie on a decline bench with your feet higher than your head and your feet firmly on the ground.","Grasp the barbell with an extra wide grip (your hands near the plates) and starting at you’re your upper thighs raise the barbell in an arc over your head towards the floor.","Slowly return the barbell to starting position on your thighs.","Repeat."]},{slug:"wide-grip-decline-bench-press",title:"Wide Grip Decline Bench Press",idNum:"0083",type:"isolation",primary:["chest"],secondary:["triceps","shoulders"],equipment:["barbell","decline bench"],steps:["Lie on a decline bench with your head lower than your feet.","Place your hands wider than shoulder width apart on the bar and lift it off the rack.","Bring the bar over your chest and lower it till it is just above the lower portion of your chest, this is starting position.","Extend your arms upward and raise the bar straight up.","Pause for a moment and then lower the bar to starting position.","Repeat."]},{slug:"wide-grip-standing-biceps-curl-with-barbell",title:"Wide Grip Standing Biceps Curl with Barbell",idNum:"0250",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["barbell"],steps:["This is a wide grip version of a biceps curl. The wider grip targets the lateral or outer portion of the muscle.","Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a barbell with palms up as wide as you comfortably can.","Extend your arms fully against your thighs.","Keeping your elbows straight, raise the bar towards your chest until your forearms touch your chest.","Pause for moment and then return to the starting position.","Note: Lean up against a wall or post if you have problems keeping from swinging."]},{slug:"wide-stance-squat-with-barbell",title:"Wide Stance Squat with Barbell",idNum:"0160",type:"compound",primary:["quadriceps"],secondary:["calves","hamstrings"],equipment:["barbell"],steps:["Lifting a barbell off of a weight rack, position it on your shoulders.","Stand with your feet wider than shoulder width apart (about 30 inches apart) with your toes pointing out.","Drawing your abs in descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Note: A pad on the bar or towel on your shoulders can help improve your grip and reduce the discomfort of the bar against your back. Practice the squat without any weight to allow yourself to become comfortable with the movements."]},{slug:"zecher-squats",title:"Zecher Squats",idNum:"0161",type:"compound",primary:["quadriceps"],secondary:["glutes","hamstrings","calves"],equipment:["barbell"],steps:["This variation of squat is similar to a Front Squat, it works to build the upper muscles of the quadriceps (thighs).","Lift a barbell off of a weight rack and place across your chest. Hold the barbell with your arms crossed.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in, descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Note: Practice the squat without any weight to allow yourself to become comfortable with the movements."]},{slug:"zottman-curl-with-dumbbells",title:"Zottman Curl with Dumbbells",idNum:"0251",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["dumbbell"],steps:["Stand with your feet shoulder width apart, your knees slightly bent and your and your abs drawn in.","Grasp a dumbbell in each hand with your palms facing each other.","Start with your hands at your sides.","Curl your arms up turning your wrists so they are facing down as the dumbbells reach your chest.","Pause for a moment and then return to the starting position."]},{slug:"zottman-preacher-curl-with-dumbbells",title:"Zottman Preacher Curl with Dumbbells",idNum:"0252",type:"isolation",primary:["biceps"],secondary:["forearm"],equipment:["dumbbell"],steps:["Sit at a Preacher Curl Bench.","Grasp a dumbbell in your hand with your palms facing up.","Extend your arm fully along the bench.","Curl your arm up turning your wrist so it faces down as the dumbbell reaches your chest.","Pause for a moment and then return to the starting position and switch arms."]}],R="https://cdn.jsdelivr.net/gh/everkinetic/data@main/dist/svg",w=(t,o)=>`${R}/${t}-${o}.svg`,g=(t,o,r)=>`https://images.weserv.nl/?url=${encodeURIComponent(`cdn.jsdelivr.net/gh/everkinetic/data@main/dist/svg/${t}-${o}.svg`)}&w=${r}&output=webp&q=80`,m=t=>`/illustrations/${t}.webp`,v=t=>t.toLowerCase().replace(/[^a-z0-9]+/g," ").trim();let b=null;const z=t=>{if(!t)return null;if(!b){b=new Map;for(const o of Y)b.set(v(o.title),o)}return b.get(v(t))??null},F=({ex:t,size:o=56,className:r,eager:n=!1})=>e.jsx("div",{"aria-hidden":!0,className:u("shrink-0 overflow-hidden rounded-xl border border-gold/25 bg-black flex items-center justify-center","shadow-[inset_0_1px_0_hsl(var(--gold)/0.12)]",r),style:{width:o,height:o},children:e.jsx("img",{src:m(t.idNum),alt:"",decoding:"async",className:"h-full w-full object-contain p-1",style:{filter:c},onError:s=>{const i=s.currentTarget;i.dataset.fb?i.dataset.fb==="1"&&(i.dataset.fb="2",i.src=w(t.idNum,"tension")):(i.dataset.fb="1",i.src=g(t.idNum,"tension",112))}})}),W=({ex:t,className:o})=>{const[r,n]=l.useState(!0),[s,i]=l.useState(!0),[B,P]=l.useState(!1),f=l.useRef(null);if(l.useEffect(()=>{if(typeof matchMedia!="function")return;const a=matchMedia("(prefers-reduced-motion: reduce)"),h=()=>P(a.matches);return h(),a.addEventListener?.("change",h),()=>a.removeEventListener?.("change",h)},[]),l.useEffect(()=>{const a=f.current;if(!a||typeof IntersectionObserver!="function")return;const h=new IntersectionObserver(([d])=>i(d.isIntersecting),{threshold:.25});return h.observe(a),()=>h.disconnect()},[]),B)return e.jsx(I,{ex:t,className:o});const k=r&&s;return e.jsx("div",{ref:f,className:u("relative",o),children:e.jsxs("div",{className:"relative overflow-hidden rounded-2xl border border-gold/25 bg-black",children:[e.jsx("img",{src:m(t.idNum),alt:"","aria-hidden":!0,decoding:"async",className:"absolute inset-0 w-full h-full object-contain p-4 blur-[6px] opacity-50",style:{filter:c}}),["relaxation","tension"].map(a=>e.jsx("img",{src:g(t.idNum,a,480),alt:a==="relaxation"?`${t.title} — start position`:`${t.title} — finish position`,loading:"eager",decoding:"async",className:u("w-full h-56 object-contain p-4",a==="tension"&&"absolute inset-0",k&&(a==="relaxation"?"rep-phase-a":"rep-phase-b")),style:{filter:c,...k?void 0:{opacity:a==="tension"?0:1}},onError:h=>{const d=h.currentTarget;d.dataset.fb||(d.dataset.fb="1",d.src=w(t.idNum,a))}},a)),e.jsx("div",{"aria-hidden":!0,className:"pointer-events-none absolute inset-x-5 top-0 h-px bg-gradient-to-r from-transparent via-gold/40 to-transparent"}),e.jsx("button",{type:"button",onClick:()=>n(a=>!a),"aria-label":r?"Pause the movement":"Play the movement",className:"absolute bottom-2 right-2 h-11 w-11 rounded-full bg-background/70 border border-border/60 flex items-center justify-center text-gold",children:r?e.jsx(T,{size:15}):e.jsx(N,{size:15})}),e.jsx("span",{className:"absolute bottom-4 left-4 eyebrow text-gold/70",children:r?"Full rep":"Start position"})]})})},I=({ex:t,className:o})=>e.jsx("div",{className:u("grid grid-cols-2 gap-2",o),children:["relaxation","tension"].map((r,n)=>e.jsxs("div",{className:"relative overflow-hidden rounded-2xl border border-gold/25 bg-black",children:[e.jsx("img",{src:m(t.idNum),alt:"","aria-hidden":!0,decoding:"async",className:"absolute inset-0 w-full h-full object-contain p-3 blur-[6px] opacity-60",style:{filter:c}}),e.jsx("img",{src:g(t.idNum,r,480),alt:`${t.title} — ${n===0?"start":"finish"} position`,loading:"eager",decoding:"async",className:"relative w-full h-40 object-contain p-3",style:{filter:c},onError:s=>{const i=s.currentTarget;i.dataset.fb||(i.dataset.fb="1",i.src=w(t.idNum,r))}}),e.jsx("span",{className:"absolute bottom-2 left-1/2 -translate-x-1/2 eyebrow text-gold/70",children:n===0?"Start":"Finish"}),e.jsx("div",{"aria-hidden":!0,className:"pointer-events-none absolute inset-x-5 top-0 h-px bg-gradient-to-r from-transparent via-gold/40 to-transparent"})]},r))}),C={"front-squat-with-barbell":{setup:["Bar rests on the front of your shoulders, close to your neck — the shelf is your shoulders, not your hands.","Cross your arms and lay your hands on top of the bar. Elbows up and pointing forward.","Step back, feet a little wider than your shoulders, toes turned slightly out."],cues:["Elbows high the whole rep — if the elbows drop, the bar rolls forward.","Brace your stomach, then sit straight down between your feet, chest up.","Push the floor away and lead up with your elbows."],tempo:"3 seconds down · brief pause at the bottom · stand up under control",breathing:"Breathe in at the top and hold it through the rep. Breathe out once you're standing.",mistakes:[{error:"The bar slides forward off your shoulders on the way up.",fix:"Drive your elbows up toward the ceiling as you stand. If they keep dropping, the weight is too heavy for now."},{error:"Your upper back rounds and your chest drops at the bottom.",fix:"Stop the rep higher, where your chest still stays up, and use less weight. Depth comes back as your upper back gets stronger."},{error:"The bar presses on your throat and it is hard to breathe.",fix:"The bar sits on the shelf of your shoulders, touching your neck but not pressing on it. Lift your elbows and it settles into place."}],feelIt:"Thighs first, then glutes. Your upper back works hard to hold the bar up — that is part of the lift. Your wrists should not ache; if they do, the bar is in your hands instead of on your shoulders.",easier:"Goblet squat — hold one dumbbell at your chest. Same upright shape, nothing to balance on your shoulders.",harder:"Add weight in small steps, or pause two seconds at the bottom with your elbows still high."},"wide-stance-squat-with-barbell":{setup:["Bar on the muscle across the top of your back, hands just outside your shoulders.","Feet well wider than your shoulders, toes turned out about 30° — your knees will follow your toes.","Step back two steps and set your feet before you start."],cues:["Push your knees out toward your toes the whole way down and up.","Sit your hips down between your heels, chest up.","Drive the floor apart with your feet to stand."],tempo:"3 seconds down · pause at the bottom · stand up under control",breathing:"Breathe in at the top and hold it through the rep. Breathe out once you're standing.",mistakes:[{error:"Your knees fall inward as you push up.",fix:"Push them out over your little toes. If they still fall in, turn your toes out more and use less weight."},{error:"You lean forward and it turns into a bow.",fix:"Keep your chest up and sit your hips down, not back. A slightly shallower rep with a tall chest is the one to keep."},{error:"Your feet roll onto their inside edges.",fix:"Grip the floor with your whole foot, especially the outside edge. Narrow the stance a little if it keeps happening."}],feelIt:"Inner thighs and glutes more than a normal squat, with the front of your thighs still working. Your lower back stays braced and quiet.",easier:"Plié squat with one dumbbell held at your chest — same wide stance, much easier to keep upright.",harder:"Add weight in small steps, or pause two seconds at the bottom with your knees pushed out."},"narrow-stance-squat-with-barbell":{setup:["Bar on the muscle across the top of your back, not the bone at the base of your neck.","Feet close together — about a hand's width apart, toes pointing slightly out.","Step back two steps and plant your whole foot before you start."],cues:["Let your knees travel forward over your toes — that is the point of the narrow stance.","Chest up, sit straight down as far as your heels stay planted.","Push through the middle of your foot to stand."],tempo:"3 seconds down · brief pause · stand up under control",breathing:"Breathe in at the top and hold it through the rep. Breathe out once you're standing.",mistakes:[{error:"Your heels lift and you tip forward onto your toes.",fix:"Stop the rep where your heels start to lift — that is your depth for now. A small plate under each heel helps while your ankles loosen."},{error:"Your knees knock together on the way up.",fix:"Push them apart, just slightly, as you stand. If they keep touching, use less weight."},{error:"You wobble and cannot find your balance at the bottom.",fix:"Widen your stance a little and slow the descent. Balance comes before load in this one."}],feelIt:"Front of your thighs, right above the knee, more than in a normal squat. Your lower back stays braced and quiet.",easier:"A normal-width barbell squat, or a goblet squat with your feet a little closer than usual.",harder:"Add weight in small steps, or pause two seconds at the bottom."},"hack-squat-with-barbell":{setup:["Bar on the floor just behind your heels. Feet about shoulder width, toes forward.","Squat down and take the bar behind you, palms facing back, hands just outside your legs.","Chest up, shoulders back, and check the bar is touching the back of your legs before you lift."],cues:["Stand up with your chest tall — the bar stays brushing the back of your legs.","Sit straight down, knees forward, until your thighs are about parallel.","Push through your whole foot to stand. Stop just short of locking your knees."],tempo:"Stand up under control · 3 seconds down · light touch of the plates, no bounce",breathing:"Breathe in at the top. Hold it on the way down and back up, then breathe out.",mistakes:[{error:"The bar scrapes the back of your legs and you lean forward to avoid it.",fix:"Let it touch — that is where it belongs. Long socks or leggings fix the scrape; leaning forward puts the work into your lower back."},{error:"You round your back to reach the bar at the bottom.",fix:"Raise the bar on a pair of plates or blocks so you reach it with a flat back. Range comes back as your hips loosen."},{error:"Your heels lift and you tip onto your toes as you stand.",fix:"Push through the middle of your foot. A small plate under each heel helps while your ankles loosen."}],feelIt:"Front of your thighs above all — the bar behind you makes your legs do the work. Your lower back stays braced, not pulling.",easier:"A goblet squat, or the hack squat machine, which holds the weight in the right place for you.",harder:"Add weight in small steps once every rep looks the same, or pause two seconds at the bottom."},"hack-squat-machine":{setup:["Shoulders under the pads, back flat against the backrest, and keep it there.","Feet on the platform a little closer than shoulder width, toes turned slightly out.","Stand the sled up, then release the safety handles. Know how to re-set them before you start."],cues:["Push your back into the pad and sink straight down, knees tracking over your toes.","Go as deep as your hips stay on the pad.","Push through your whole foot to stand. Stop just short of locking your knees."],tempo:"3 seconds down · brief pause at the bottom · press up under control",breathing:"Breathe in as you lower. Breathe out as you press up.",mistakes:[{error:"Your hips curl up off the pad at the bottom.",fix:"Stop the rep higher. The moment your hips start to lift is past your range for now — moving your feet a little higher on the platform helps too."},{error:"You snap your knees straight at the top.",fix:"Stop just short of locked. The muscles should hold the weight at the top, not the joint."},{error:"Your heels come off the platform.",fix:"Move your feet a little higher on the platform and push through the middle of your foot."}],feelIt:"Front of your thighs, and glutes as you press up. Your lower back stays pressed to the pad and does nothing.",easier:"The leg press — the seat supports more of you, and the weight is easier to control.",harder:"Slow the lowering to 4 seconds, or add weight in small steps once every rep looks the same."},"narrow-stance-hack-squats":{setup:["Shoulders under the pads, back flat against the backrest.","Feet close together — about a hand's width apart — placed slightly higher on the platform than usual.","Release the safety handles only once you are standing tall."],cues:["Knees travel straight forward over your toes, not in or out.","Sink until your thighs are about parallel, or higher if your heels start to lift.","Press through the middle of your foot. Stop short of locking your knees."],tempo:"3 seconds down · brief pause · press up under control",breathing:"Breathe in as you lower. Breathe out as you press up.",mistakes:[{error:"Your heels lift off the platform at the bottom.",fix:"Move your feet higher on the platform, or stop the rep a little higher. Push through the middle of your foot."},{error:"Your knees knock together as you press up.",fix:"Keep a small gap between them all the way up. If they still touch, the weight is too heavy."},{error:"You bounce out of the bottom to get going.",fix:"Pause for a beat at the bottom, then press. If you need the bounce, use less weight."}],feelIt:"Front of your thighs, more so than the normal-width version. Your knees should feel strong, not pinched — if they do, widen your feet and use less weight.",easier:"The hack squat machine with a normal-width stance, or the leg press.",harder:"Slow the lowering to 4 seconds, or add weight in small steps."},"smith-machine-squats":{setup:["Set the bar at shoulder height, with the safety stops just below your lowest position.","Bar on the muscle across the top of your back. Feet a little wider than your shoulders and slightly in front of the bar.","Stand tall, twist the bar to unhook it, and settle before the first rep."],cues:["Sit straight down along the rails, chest up, knees following your toes.","Go as deep as your back stays flat and your heels stay down.","Push the floor away to stand. Hook the bar back only when the set is done."],tempo:"3 seconds down · brief pause · stand up under control",breathing:"Breathe in at the top and hold it through the rep. Breathe out once you're standing.",mistakes:[{error:"Your feet are too far forward and the bar drags you backwards.",fix:"Bring your feet back so they sit just in front of the bar. A few centimetres makes a big difference."},{error:"The bar path pushes you forward onto your toes.",fix:"Move your feet slightly forward and sit back into your heels. The rail decides the bar path, so your feet have to move instead."},{error:"You forget where the hooks are and struggle to rack the bar at the end.",fix:"Practise hooking and unhooking with an empty bar before you load it. Set the safety stops every time."}],feelIt:"Thighs and glutes. Because the machine balances the bar, your lower back should feel calm — if it is working hard, your feet are in the wrong place.",easier:"A goblet squat, or the leg press. Both let you find your natural path before the rails set it for you.",harder:"Pause two seconds at the bottom, or move to a free barbell squat once the shape feels automatic."},"squats-using-dumbbells":{setup:["A dumbbell in each hand, arms hanging straight at your sides.","Feet a little wider than your shoulders, toes turned slightly out.","Stand tall with your shoulders back — the dumbbells hang beside your legs, not in front of your knees."],cues:["Chest up, sit your hips down and back with the dumbbells sliding past your legs.","Go as deep as your back stays flat and your heels stay planted.","Push the floor away to stand."],tempo:"3 seconds down · brief pause · stand up under control",breathing:"Breathe in as you sit down. Breathe out as you stand.",mistakes:[{error:"You lean forward and the dumbbells swing out in front of your knees.",fix:"Keep them brushing the outside of your legs. If they drift forward, your chest has dropped — sit down, not over."},{error:"Your grip gives out before your legs do.",fix:"Use lighter dumbbells, or hold one at your chest instead. The goblet version is the simpler fix."},{error:"Your knees drift together as you stand.",fix:"Push them out toward your little toes on the way up. Slow down until they stay there."}],feelIt:"Thighs and glutes. Your forearms will work to hold the weight — that is normal, as long as the grip does not end the set.",easier:"Goblet squat with one dumbbell at your chest, or a squat to a bench with no weight at all.",harder:"Heavier dumbbells once every rep looks the same, or a barbell squat."},"squat-to-bench-with-dumbbells":{setup:["Bench behind you. Its edge should touch the back of your legs when you stand tall.","A dumbbell in each hand at your sides, feet a little wider than your shoulders, toes turned slightly out.","Start with a high bench. A lower one is a progression, not the starting point."],cues:["Sit back until you just touch the bench, then stand — it is a marker, not a seat.","Chest up, knees following your toes.","Push through your whole foot to stand up."],tempo:"3 seconds down · light touch on the bench · stand up under control",breathing:"Breathe in as you sit back. Breathe out as you stand.",mistakes:[{error:"You sit down on the bench and relax between reps.",fix:"Touch and go. If you cannot control it to a light touch, the bench is too low or the dumbbells are too heavy."},{error:"You drop the last few centimetres and bounce off the bench.",fix:"Slow down the second half of the descent. Three full seconds down means the touch is light."},{error:"You lean forward to get off the bench.",fix:"Push your feet into the floor and keep your chest up. Leaning forward moves the work into your lower back — use less weight until you can stand straight up."}],feelIt:"Thighs and glutes. Your lower back should stay braced and steady, never doing the lifting.",easier:"No dumbbells, a higher bench, or a box with a pad on it. The higher the seat, the easier it is — and it still counts.",harder:"A lower bench, heavier dumbbells, or a two-second pause on the bench with your body still tight."},"pile-squat-with-dumbbell":{setup:["Feet well wider than your shoulders, toes turned out about 45°.","Hold one dumbbell by its top end with both hands, hanging straight down between your legs.","Stand tall, shoulders back. The dumbbell hangs, it does not pull you forward."],cues:["Sit straight down between your feet, knees pushed out over your toes.","Chest up the whole way — the dumbbell travels straight down and up.","Squeeze your glutes to stand."],tempo:"3 seconds down · brief pause · stand up under control",breathing:"Breathe in as you sit down. Breathe out as you stand.",mistakes:[{error:"Your knees fall inward as you stand.",fix:"Push them out toward your toes. If they still fall in, turn your toes out a little more and use less weight."},{error:"You bend forward and the dumbbell swings out in front.",fix:"Keep your chest up and sit your hips straight down, not back. The dumbbell should travel in a straight line."},{error:"Your feet roll onto their inside edges.",fix:"Grip the floor with the outside of your feet. Narrow the stance a little if it keeps happening."}],feelIt:"Inner thighs and glutes above all. Your lower back stays tall and quiet.",easier:"No weight at all, hands on your hips, until the wide stance feels natural.",harder:"A heavier dumbbell, or a two-second pause at the bottom with your knees pushed out."},"jefferson-squats-with-barbell":{setup:["Stand over the bar so it runs between your feet, front to back. Feet a little wider than your shoulders.","Squat down and take the bar with one hand in front of you and one behind, both palms down.","Chest up, back flat. The bar should hang straight down between your legs, not against one thigh."],cues:["Stand up straight through the middle — do not let one side pull you into a twist.","Knees follow your toes, chest stays up.","Lower under control until the plates just touch the floor."],tempo:"Stand up under control · brief pause at the top · 3 seconds down",breathing:"Breathe in at the bottom, brace, and hold it through the lift. Breathe out at the top.",mistakes:[{error:"Your body twists toward the front hand as you stand.",fix:"Use less weight and think about driving both feet evenly. Swap which hand is in front every set so neither side does all the work."},{error:"The bar hits the inside of your thigh.",fix:"Widen your stance a little and turn your toes out. The bar should have clear room to travel straight up."},{error:"Your back rounds to reach the bar at the bottom.",fix:"Raise the bar on blocks or plates so you reach it with a flat back. Range comes back as your hips loosen."}],feelIt:"Thighs, inner thighs and glutes. Your lower back stays braced and even, never twisting.",easier:"A plié squat with one dumbbell — the same wide, upright shape with nothing to balance front to back.",harder:"Add weight in small steps once the bar travels straight, or pause a second at the bottom."},"squats-with-exercise-bands":{setup:["Stand on the middle of the band with your feet about shoulder width, toes turned slightly out.","Bring the handles up to your shoulders, palms facing forward, elbows down.","Stand tall and check the tension — the band should be snug at the top, not slack."],cues:["Chest up, sit down and back as the band shortens, then drive up against it.","Knees follow your toes the whole way.","The band pulls hardest at the top — stand all the way up anyway."],tempo:"3 seconds down · brief pause · stand up under control",breathing:"Breathe in as you sit down. Breathe out as you stand.",mistakes:[{error:"The band slides out from under your feet mid-set.",fix:"Stand on the band with the middle of both feet, not the arches, and keep your feet still. Check it before every set."},{error:"You lean forward because the handles pull you down.",fix:"Keep your elbows down and the handles pinned to your shoulders, chest up. If it still pulls you over, use a lighter band."},{error:"You stop short at the top where the band is hardest.",fix:"Stand fully tall every rep. If you cannot, the band is too strong — the top is the point."}],feelIt:"Thighs and glutes, with the hardest part at the top of the rep. Your shoulders hold the handles still and should not ache.",easier:"A bodyweight squat, or a lighter band. Standing on the band with one foot halves the tension.",harder:"A thicker band, a wider stance under the band, or a pause at the bottom."},"narrow-stance-leg-press":{setup:["Set the seat so your knees bend to about a right angle at the bottom, no deeper to start.","Feet close together on the middle of the platform — about a hand's width apart, toes slightly out.","Sit right back so your hips and lower back stay against the pad."],cues:["Lower until your knees are bent about 90°, keeping your hips on the pad.","Push through your whole foot, not your toes.","Stop just short of locking your knees at the top."],tempo:"3 seconds down · brief pause · press back up under control",breathing:"Breathe in as the platform comes down. Breathe out as you press.",mistakes:[{error:"Your hips curl up off the seat at the bottom.",fix:"You are going too deep for now. Stop the rep higher — the moment your hips start to lift is past your range."},{error:"Your knees knock together as you press.",fix:"Keep a small gap between them the whole way. If they still touch, the weight is too heavy."},{error:"You snap your knees straight at the top.",fix:"Stop just short of locked. The muscles hold the weight at the top, not the joint."}],feelIt:"Front of your thighs, more so than the normal-width leg press. Your lower back stays supported by the pad and does nothing.",easier:"The normal-width leg press with less weight and a shorter range.",harder:"Slow the lowering to 4 seconds, or add weight in small steps."},"leg-extensions":{setup:["Line your knees up with the machine's pivot — the point the lever rotates around.","Pad sits on your shins just above your ankles, not on top of your feet.","Back against the seat, hands on the handles, and keep them there."],cues:["Straighten your legs slowly and squeeze the front of your thighs at the top.","Stop just short of locking your knees.","Lower for three seconds — the slow half is where the work is."],tempo:"2 seconds up · squeeze for a beat · 3 seconds down",breathing:"Breathe out as you straighten. Breathe in as you lower.",mistakes:[{error:"You swing the weight up with momentum.",fix:"Take two full seconds to straighten. If you need the swing, the weight is too heavy."},{error:"Your hips lift off the seat at the top.",fix:"Press your back into the seat and hold the handles. Lifting your hips means your legs are getting help — use less weight."},{error:"The weight stack slams down between reps.",fix:"Three seconds down, every rep. Stop just before the plates touch."}],feelIt:"Front of your thighs, right through the middle. Your knees should feel like they are working, not being pulled — if they feel strained, shorten the range at the bottom and use less weight.",easier:"Less weight and a shorter range at the bottom while you learn where the squeeze is.",harder:"Hold the top for two seconds, or work one leg at a time."},"lying-leg-curl-machine":{setup:["Lie face down with your knees just off the edge of the bench, lined up with the machine's pivot.","Pad sits just above your heels, not on your calves.","Hips pressed into the bench, hands on the grips."],cues:["Curl your heels toward your backside and squeeze at the top.","Keep your hips pressed down the whole rep.","Lower for three seconds until your legs are almost straight."],tempo:"1 second to curl · squeeze for a beat · 3 seconds back",breathing:"Breathe out as you curl. Breathe in as it returns.",mistakes:[{error:"Your hips lift off the bench as you curl.",fix:"Press them down and use less weight. If your hips move, your lower back is helping."},{error:"You jerk the weight up and it bounces at the bottom.",fix:"Curl in one second and take three to lower. The slow half is where most of the work is."},{error:"Your range gets shorter as the set goes on.",fix:"Drop the weight. Half a curl trains half the muscle, and the last reps are the ones that count."}],feelIt:"The back of your thighs. Cramping there is common at first and eases as you get used to it. Not your lower back.",easier:"Less weight and a shorter range, or the seated leg curl, which holds your hips in place for you.",harder:"Slow the return to 4 seconds, or work one leg at a time."},"rear-lunges-with-dumbbell":{setup:["A dumbbell in each hand, arms relaxed at your sides.","Stand tall with your feet under your hips.","Pick a spot to step back to — about one long stride behind you."],cues:["Step back and drop your back knee straight down, weight staying on the front foot.","Front shin close to vertical, chest up.","Push through your front heel to bring the back foot home."],tempo:"2 seconds down · light touch at the bottom · drive up under control",breathing:"Breathe in as you step back and lower. Breathe out as you come back up.",mistakes:[{error:"You lean forward over your front leg.",fix:"Chest up, eyes ahead. Leaning forward moves the work into your lower back."},{error:"Your front knee drifts inward as you stand.",fix:"Push the knee out so it tracks over your middle toes. Slow down and use lighter dumbbells until it stays there."},{error:"You step back too short and your front heel lifts.",fix:"Take a longer stride. Your front foot should stay flat the whole rep — if it cannot, the step is too small."}],feelIt:"The front leg's thigh and glute. The back leg is mostly there for balance.",easier:"No weight at all, holding a rack or wall with one hand. Many people find stepping back easier to balance than stepping forward — that is why this one comes first.",harder:"Heavier dumbbells, a pause at the bottom, or step the back foot onto a low step to lengthen the range."},"barbell-lunges":{setup:["Bar on the muscle across the top of your back, hands a little wider than your shoulders.","Stand tall, feet under your hips, in a clear space — step out of the rack first.","Start with an empty bar. Balance under a bar is a skill before it is a weight."],cues:["Step one long stride forward and drop your back knee straight down.","Chest up, front shin close to vertical.","Push through your front heel to step back to standing."],tempo:"2 seconds down · light touch at the bottom · drive back under control",breathing:"Breathe in as you step and lower. Breathe out as you push back.",mistakes:[{error:"You wobble side to side under the bar.",fix:"Do them stationary first — stay in one split stance and just go up and down. Add the step only when the up and down is steady."},{error:"Your front knee drifts inward as you push back.",fix:"Push it out over your middle toes. If it keeps drifting, use less weight."},{error:"You lean forward and the bar tips you over your front leg.",fix:"Chest up, eyes ahead. A shorter step with a tall chest beats a long one with your back doing the work."}],feelIt:"The front leg's thigh and glute. Your stomach and back work to keep the bar still — that is normal.",easier:"Dumbbell lunges — the weight hangs at your sides instead of balanced on your back. Or an empty bar, stationary.",harder:"Add weight in small steps, walking lunges, or a pause at the bottom."},"step-ups-with-barbell":{setup:["A box or bench around knee height. Lower is fine — start lower than you think.","Bar on the muscle across the top of your back, hands a little wider than your shoulders.","Place your whole foot on the box, not just the front half."],cues:["Drive up through the foot on the box — the floor foot is just along for the ride.","Stand all the way up before you step down.","Lower yourself under control, the same leg working on the way down."],tempo:"Drive up · stand tall for a beat · 3 seconds down",breathing:"Breathe out as you step up. Breathe in as you lower.",mistakes:[{error:"You bounce off your back foot to get up.",fix:"The leg on the box does the work. Try touching your back toe down lightly between reps instead of pushing off it."},{error:"You lurch forward and the bar rolls up your neck.",fix:"The box is too high or the weight is too heavy. Drop to a lower box and keep your chest up."},{error:"You drop back down and land hard.",fix:"Take three seconds to lower. Landing hard is where knees get sore."}],feelIt:"The leg on the box — thigh and glute. Your back stays tall and braced under the bar.",easier:"Step-ups with dumbbells, or a lower box with no weight at all.",harder:"A higher box, more weight in small steps, or a pause at the top of each rep."},"barbell-dead-lifts":{setup:["Bar over the middle of your feet, feet about hip width. Shins a few centimetres from the bar.","Push your hips back and bend your knees until your hands reach the bar, just outside your legs.","Chest up, back flat, arms straight. Pull the slack out of the bar before you lift."],cues:["Push the floor away and stand up — the bar stays brushing your legs the whole way.","Hips and chest rise together. If your hips shoot up first, the weight is too heavy.","Finish standing tall, glutes squeezed. Don't lean back.","Lower by pushing your hips back, then bend your knees once the bar passes them."],tempo:"Stand up under control · brief pause at the top · 2–3 seconds down · reset every rep",breathing:"Breathe in and brace before you pull. Hold it until you are standing, then breathe out. Fresh breath every rep.",mistakes:[{error:"Your lower back rounds as you pull from the floor.",fix:"Raise the bar on blocks so you can start with a flat back, and use less weight. The floor comes back as your hips loosen."},{error:"The bar swings out in front of your shins.",fix:"Keep it touching your legs the whole way up and down. A bar out in front is what makes backs sore."},{error:"Your hips shoot up first and the lift turns into a stiff-legged pull.",fix:"Set your hips lower at the start and think about pushing the floor away with your legs. If they still shoot up, the weight is too heavy."}],feelIt:"Glutes, the back of your thighs and your whole back holding tight. Your lower back should feel braced and steady, never strained — if it is, reduce the weight.",easier:"Romanian deadlift with a bar or dumbbells, or a deadlift from blocks. Both teach the hinge with a shorter range.",harder:"Add weight in small steps once every rep starts from the same flat-back position, or pause a second just off the floor."},"barbell-good-mornings":{setup:["Bar on the muscle across the top of your back, hands a little wider than your shoulders.","Feet about hip width, knees slightly bent and kept that way.","Start with an empty bar. This one is about the shape, not the weight."],cues:["Push your hips straight back, as if closing a car door behind you.","Chest stays proud, back stays flat — bow forward from the hips only.","Stop when the back of your thighs feels tight. That is your depth, wherever it is.","Drive your hips forward to stand tall."],tempo:"3 seconds down · no bounce at the bottom · hips forward to stand",breathing:"Breathe in at the top and hold it as you bow. Breathe out once you are standing.",mistakes:[{error:"Your back rounds as you bow forward.",fix:"Stop the rep higher — go only as far as your back stays flat, and use less weight. Parallel to the floor is a goal, not a requirement."},{error:"You bend your knees more and more, so it turns into a squat.",fix:"Fix the knee angle at the start and don't change it. Only the hips move."},{error:"The bar rolls up onto your neck as you bow.",fix:"Pull your elbows back and pin the bar into your back. If it still rolls, the weight is too heavy."}],feelIt:"A strong stretch down the back of your thighs, and your glutes as you stand. If you feel it mostly in your lower back, you are rounding — reduce the range and the weight.",easier:"Romanian deadlift with light dumbbells — the same hinge with the weight in your hands, where it is easier to control.",harder:"Add weight in small steps, or slow the lowering to 4 seconds."},"standing-barbell-calf-raise":{setup:["Bar on the muscle across the top of your back, hands a little wider than your shoulders.","Balls of your feet on a block or a pair of plates, heels hanging off the edge.","Stand tall, knees straight but not locked, feet about hip width."],cues:["Rise onto the balls of your feet as high as you can, then squeeze at the top.","Lower slowly until your heels are below the block and you feel the stretch.","Keep your body still — only your ankles move."],tempo:"2 seconds up · squeeze for a beat · 3 seconds down · pause in the stretch",breathing:"Breathe out as you rise. Breathe in as you lower.",mistakes:[{error:"You bounce out of the bottom to get going.",fix:"Pause a full second in the stretch, then rise. If you need the bounce, the weight is too heavy."},{error:"You bend your knees and turn it into a bob.",fix:"Keep your knees straight but not locked. If they bend, the weight is too heavy for your calves alone."},{error:"You only rise a few centimetres.",fix:"Go all the way up onto your toes every rep. Use less weight and a full range — half a rep trains half the muscle."}],feelIt:"Your calves, from the heel up to behind the knee. Not your lower back — if it aches, you are leaning back under the bar.",easier:"Bodyweight calf raises on a step, holding a rail, or one dumbbell in one hand with the other hand on a rail.",harder:"Add weight in small steps, or pause two seconds at the top and two in the stretch."},"smith-machine-reverse-calf-raises":{setup:["Block or low box under the bar. Stand on it with your heels on the edge and your toes hanging off.","Bar on the muscle across the top of your back. Use the machine as a handrail — it is there for balance.","Lean forward very slightly from the ankles, weight on your heels."],cues:["Lift your toes up toward your shins as high as they go, then squeeze.","Lower slowly until your toes point down and you feel a stretch on the front of your shin.","Keep your knees straight and your body still."],tempo:"2 seconds up · squeeze for a beat · 3 seconds down",breathing:"Breathe out as you lift your toes. Breathe in as you lower.",mistakes:[{error:"You bend your knees and rock instead of lifting your toes.",fix:"Keep your knees straight but not locked. Only your ankles move — use less weight until they can."},{error:"You lose balance and grab the bar.",fix:"Hold the bar with both hands the whole set and make the movement small. Balance is not the point of this one."},{error:"The range is tiny because the block is too low.",fix:"Use a taller block so your toes have room to drop below your heels. The stretch at the bottom is half the exercise."}],feelIt:"The front of your shins, and it burns quickly — that is normal. Not your knees or your lower back.",easier:"No bar at all: stand on the block and lift your toes with just your body weight, hands on the rails.",harder:"Add weight in small steps, or slow the lowering to 4 seconds."},"one-legged-cable-kickback":{setup:["Ankle cuff on the low pulley. Face the stack and hold the frame with both hands.","Stand on the free leg with a soft knee. Working leg slightly in front, the cable pulling it forward.","Lean forward just slightly from the hips, stomach braced, back flat."],cues:["Squeeze your glute and push the leg straight back — small and controlled, not a swing.","Only the leg moves. Your hips and back stay still.","Return slowly until the leg is just past the standing one."],tempo:"1 second back · squeeze for a beat · 2–3 seconds forward",breathing:"Breathe out as you kick back. Breathe in as it returns.",mistakes:[{error:"Your lower back arches and your hips tilt as the leg goes back.",fix:"Shorten the kick. The rep ends where your hips start to move — use less weight and think about squeezing rather than reaching."},{error:"You swing the leg back with momentum.",fix:"Take a full second back and three forward. If the stack bounces, the weight is too heavy."},{error:"Your standing knee wobbles and you hang off the frame.",fix:"Use less weight and stand tall on a soft knee. The frame is for balance, not for holding you up."}],feelIt:"Your glute on the working leg. If you feel it mostly in your lower back, the kick is too big — make it smaller.",easier:"The same movement on your hands and knees with no cable, or a light band around your ankles.",harder:"Pause two seconds at the back of the kick, or add weight in small steps."},"thigh-abductor":{setup:["Sit tall, back against the pad, knees against the outside of the pads.","Pick a weight you can open fully under control — lighter than you think.","Hold the handles and keep your torso still."],cues:["Push your knees apart slowly and hold for a beat at the widest point.","Come back together under control — don't let the stack pull your knees in.","Torso stays tall and still. Only the legs move."],tempo:"2 seconds open · hold for a beat · 3 seconds back",breathing:"Breathe out as you open. Breathe in as you close.",mistakes:[{error:"You lean back and drive the pads with your whole body.",fix:"Sit tall with your back on the pad. If you have to lean to move it, the weight is too heavy."},{error:"The stack slams down as your knees come back in.",fix:"Three seconds back, every rep. The return is half the work."},{error:"You jerk the pads open and your range shrinks with every rep.",fix:"Use less weight and open slowly. Go as wide as you can control, not as wide as the machine allows."}],feelIt:"The sides of your hips and glutes. Not your lower back.",easier:"Less weight and a smaller range, or a band around your knees while you sit and push out against it.",harder:"Hold the open position for two seconds, or lean slightly forward from the hips with a flat back."},"thigh-adductor":{setup:["Sit tall, back against the pad, knees against the inside of the pads.","Set the start width somewhere comfortable — not the widest setting on your first day.","Hold the handles and keep your torso still."],cues:["Squeeze your knees together slowly and hold for a beat when they meet.","Open again under control — don't let the stack pull your legs apart.","Torso stays tall and still. Only the legs move."],tempo:"2 seconds together · hold for a beat · 3 seconds back out",breathing:"Breathe out as you squeeze. Breathe in as you open.",mistakes:[{error:"The stack yanks your legs apart on the way back.",fix:"Three seconds out, every rep. If it still yanks, use less weight — the inner thigh does not like surprises."},{error:"You start with the pads too wide and feel a sharp pull at the top.",fix:"Bring the start position in a notch or two. Range grows from week to week, not inside one set."},{error:"You lean forward or back to help.",fix:"Sit tall with your back against the pad. If you have to lean, the weight is too heavy."}],feelIt:"Your inner thighs. A gentle stretch when the pads are open is fine — a sharp pull means the start is set too wide.",easier:"Less weight and a narrower start, or squeeze a ball between your knees while seated.",harder:"Hold the squeeze for two seconds, or slow the return to 4 seconds."},"cross-body-crunch":{setup:["On your back, knees bent, feet flat on the floor.","Fingertips lightly beside your ears — not clasped behind your head.","Look at a point on the ceiling and keep looking there."],cues:["Curl one shoulder up and twist, elbow toward the opposite knee.","The knee can lift to meet the elbow — the shoulder comes up, not the whole back.","Lower slowly, then go to the other side."],tempo:"2 seconds up · squeeze for a beat · 2 seconds down · alternate sides",breathing:"Breathe out as you curl and twist. Breathe in as you lower.",mistakes:[{error:"You pull on your head to get the elbow across.",fix:"Fingertips only, elbows wide. The elbow reaches because your ribs twist, not because your hands pull."},{error:"You sit all the way up and swing across.",fix:"Only one shoulder blade leaves the floor. Sitting further up uses your hips, not your stomach."},{error:"You rush and the twist disappears.",fix:"Two seconds up, two down, with a beat at the top. Twelve slow reps beat forty fast ones."}],feelIt:"Your stomach, with the sides working as you twist. If you feel it mostly in your neck, your hands are pulling.",easier:"A plain crunch, hands crossed on your chest, until lifting your shoulder blades feels automatic.",harder:"Slow it down further, pause at the top, or lift both feet off the floor."},"decline-crunch":{setup:["Set the bench at a shallow decline to start. Steeper is a progression.","Hook your feet under the pads and lie back.","Hands crossed over your chest — easier than beside your ears, and kinder to your neck."],cues:["Curl your ribs toward your hips, one piece of your spine at a time.","Come up only until your shoulder blades are clear of the bench.","Lower slowly, all the way back, without dropping."],tempo:"2 seconds up · squeeze for a beat · 3 seconds down",breathing:"Breathe out as you curl up. Breathe in as you lower.",mistakes:[{error:"You sit all the way up with a flat back.",fix:"Curl instead of sitting. Once your shoulder blades are off the bench, the work is done — the rest is your hips."},{error:"You pull on your neck with your hands.",fix:"Cross your hands over your chest instead. If your neck aches, that is where the problem is."},{error:"You drop back and bounce off the bench.",fix:"Three seconds down, every rep. The lowering is where most of the work is."}],feelIt:"Your stomach, right through the middle. If you feel it mostly in the front of your hips, you are coming up too far or the bench is too steep.",easier:"A flat bench or the floor, or a shallower angle. Flat crunches are the same movement without the extra load.",harder:"A steeper decline, a slower lowering, or a light plate held on your chest."},"decline-oblique-crunch":{setup:["Set the bench at a shallow decline to start.","Hook your feet under the pads, lie back, fingertips beside your ears or hands crossed on your chest.","Look at a point on the ceiling and keep looking there."],cues:["Curl up and twist one shoulder toward the opposite knee.","Shoulder blades off the bench — that is the top. Don't sit all the way up.","Lower slowly, then twist to the other side on the next rep."],tempo:"2 seconds up · squeeze for a beat · 3 seconds down · alternate sides",breathing:"Breathe out as you curl and twist. Breathe in as you lower.",mistakes:[{error:"You sit all the way up, then twist at the top.",fix:"The twist happens on the way up, and only your shoulder blades leave the bench. Sitting up uses your hips, not your stomach."},{error:"You pull your head across with your hands.",fix:"Fingertips only, elbows wide — or cross your hands over your chest. The elbow reaches because your ribs twist, not because your hands pull."},{error:"One side is much easier than the other and you drift that way.",fix:"Slow both sides to the same speed. Start each set on the harder side while you are fresh."}],feelIt:"Your stomach and the sides of your waist. If you feel it mostly in your neck or the front of your hips, you are coming up too far.",easier:"Cross-body crunch on the floor — the same twist without the bench.",harder:"A steeper decline, a pause at the top of each twist, or a slower lowering."},"bent-knee-hip-raise":{setup:["On your back, arms out to your sides, palms down on the floor.","Knees bent, feet just off the floor. Press your lower back gently into the floor.","Chin tucked, looking straight up."],cues:["Curl your hips up off the floor, bringing your knees over your chest.","Small lift — your hips come up a few centimetres, not your whole back.","Lower slowly until your feet are just off the floor again — don't let them touch."],tempo:"2 seconds up · squeeze for a beat · 3 seconds down",breathing:"Breathe out as your hips lift. Breathe in as you lower.",mistakes:[{error:"You swing your legs to throw your hips up.",fix:"Slow down and make the lift smaller. If you need the swing, rest your feet on the floor between reps until it is stronger."},{error:"Your lower back arches off the floor as your legs lower.",fix:"Lower only as far as your back stays pressed down. If that means your feet stay high, that is your range for now."},{error:"You press hard into your arms and shoulders.",fix:"Arms are for balance, not for pushing. Move them closer to your sides — the harder they push, the less your stomach does."}],feelIt:"The lower part of your stomach. If you feel it mostly in your lower back or the front of your hips, the range is too big.",easier:"Keep your feet on the floor between reps, or bend your knees tighter — the closer the knees are to your chest, the easier it is.",harder:"Straighten your legs slightly, pause at the top, or do it on a decline bench."},"flutter-kicks":{setup:["Lie face down on a flat bench with your hips right at the end and your legs hanging off.","Hold the bench with both hands, or hug it underneath.","Squeeze your glutes before you start, so your legs are held, not hanging."],cues:["Lift one leg at a time with your glute, keeping your hips pressed to the bench.","Small, even kicks — up to level with your body, not above.","Legs stay straight, toes pointed."],tempo:"Steady rhythm · about one second per kick · never a swing",breathing:"Keep breathing steadily throughout — don't hold your breath.",mistakes:[{error:"Your hips lift off the bench and your lower back does the kicking.",fix:"Make the kicks smaller — level with the bench is high enough. If your hips still lift, move them a little further onto the bench."},{error:"You kick fast and the legs just swing.",fix:"Slow to one kick a second and squeeze your glute at the top of each. Rhythm is not the point — control is."},{error:"You hold your breath and go red in the face.",fix:"Breathe out on every kick. Cut the set short and breathe if you have to."}],feelIt:"Glutes and the back of your thighs. If you feel it in your lower back, the kicks are too high.",easier:"Lift one leg at a time from the floor, face down, with the other resting. Or hold each leg up for two seconds instead of kicking.",harder:"Longer sets, ankle weights, or lift both legs together and hold at the top."},"air-bike":{setup:["On your back, fingertips beside your ears, elbows wide.","Lift your legs so your knees are bent and your shins are level with the floor.","Press your lower back gently into the floor and keep it there."],cues:["Curl one shoulder up and across toward the opposite knee as that knee comes in.","The other leg stretches out long, hovering off the floor.","Slow — one side, then the other, without your feet ever touching down."],tempo:"Slow and even · about 2 seconds per side · never a scramble",breathing:"Breathe out each time an elbow meets a knee. Breathe in as you change sides.",mistakes:[{error:"You pull your head with your hands to reach the knee.",fix:"Fingertips only, elbows wide. The elbow reaches because your ribs twist, not because your hands pull."},{error:"Your lower back arches as the straight leg goes out.",fix:"Keep the straight leg higher off the floor. Lower it only as far as your back stays pressed down."},{error:"You pedal fast and the twist disappears.",fix:"Two full seconds per side, with a beat when elbow meets knee. Ten slow reps beat fifty fast ones."}],feelIt:"Your whole stomach, with the sides working as you twist. If you feel it mostly in your neck or your lower back, slow down and lift the straight leg higher.",easier:"Keep your feet on the floor and just do the upper-body twist, or do the cross-body crunch.",harder:"Slow it down further, pause with elbow at knee, or lower the straight leg closer to the floor."},"ab-rollout-with-barbell":{setup:["Bar loaded with round plates that roll, on the floor at your feet.","Bend forward and take the bar with both hands about shoulder width, palms down.","Brace your stomach before you move an inch. If you cannot do the kneeling version for ten steady reps, start there."],cues:["Roll out only as far as your lower back stays flat — your hips must not sag.","Arms straight the whole way. The bar rolls, you don't reach.","Pull back by lifting your hips up high, as if folding in half."],tempo:"3 seconds out · brief pause · pull back under control",breathing:"Breathe in as you roll out. Breathe out as you pull back.",mistakes:[{error:"Your lower back sags and arches at the far point.",fix:"Shorten the range — stop well before your hips drop. If it still sags, go back to the kneeling version until it is stronger."},{error:"You bend your arms to pull the bar back.",fix:"Keep your arms straight and pull with your hips and stomach. If you cannot, the range is too long."},{error:"The bar shoots away from you on the first rep.",fix:"Roll out slowly, three full seconds, and start from your knees. Heavier plates roll slower — a lighter bar is not an easier one here."}],feelIt:"Your whole stomach, and your shoulders and back working to hold you straight. Not your lower back — if it aches, shorten the range.",easier:"Ab rollout on your knees with the barbell. Nearly everyone starts there, and it stays hard for a long time.",harder:"Roll further, pause at the far point, or slow the roll out to 4 seconds."}},A={"wide-grip-bench-press":{setup:["Eyes under the bar, feet flat and planted, shoulder blades squeezed together and down.","Grip about one hand-width wider than your usual bench grip — not out at the collars.","Wrists stacked straight over your elbows. If they bend back, the grip is too wide for you."],cues:["Lower the bar to the lower half of your chest, elbows under the bar the whole way.","Keep your shoulder blades pinned to the bench — the wide grip pulls them apart.","Press up under control. The range is shorter than usual; do not chase a deeper touch."],tempo:"3 seconds down · touch lightly · press up under control",breathing:"Breathe in as the bar comes down. Breathe out as you press.",mistakes:[{error:"Your elbows flare straight out to the sides and your shoulders feel pinched at the front.",fix:"Bring the grip in by a hand-width and tuck your elbows a little. If the pinch stays, go back to a regular bench press."},{error:"The bar bounces off your chest.",fix:"Touch, pause for a beat, then press. If you need the bounce, the weight is too heavy."},{error:"Your wrists bend back and the bar sits in your fingers.",fix:"Bar low in the palm, over the forearm bone. Narrow the grip until you can keep the wrist straight."}],feelIt:"Across your chest, more than a normal bench press. Not at the front of your shoulders — if you feel it there, narrow the grip.",easier:"Bench press with a regular grip — the same movement with more room for your shoulders.",harder:"Pause two seconds on the chest, or add weight in small steps once every rep looks the same."},"close-grip-barbell-bench-press":{setup:["Set up as for a bench press: eyes under the bar, feet planted, shoulder blades squeezed together and down.","Hands about shoulder width apart — closer than that, and your wrists pay for it.","Wrists straight, bar low in the palm."],cues:["Elbows tucked along your ribs the whole way down and the whole way up.","Lower the bar to the lower half of your chest, not your throat.","Press up and finish with your arms straight."],tempo:"2–3 seconds down · touch lightly · press up under control",breathing:"Breathe in as the bar comes down. Breathe out as you press.",mistakes:[{error:"Your elbows flare out and it turns into a normal bench press.",fix:"Think about brushing your ribs with your elbows. Use less weight until they stay tucked for the whole set."},{error:"Your wrists bend back under the bar.",fix:"Widen the grip a little — shoulder width is close enough. Keep the bar stacked over your forearm."},{error:"The bar drifts toward your face on the way up.",fix:"Press up and slightly toward your feet, and lower to the same spot on your chest every rep."}],feelIt:"The back of your arms first, then your chest. Not your wrists.",easier:"Bench press with a regular grip, or push-ups with your hands close together.",harder:"Pause a second on the chest, or slow the lowering to four seconds."},"barbell-neck-press":{setup:["This is the bench press lowered to the top of your chest with the elbows out. Keep the weight light and the range short.","Set the safety bars at collarbone height so the bar can never reach your throat.","Shoulder blades squeezed together and down, feet planted. Grip a little wider than your shoulders."],cues:["Stop the bar a few centimetres above your collarbones — it never touches.","Elbows out to the sides, wrists straight over them.","Press straight up under control. Nothing here is fast."],tempo:"3 seconds down · stop above the collarbones · press up under control",breathing:"Breathe in as the bar comes down. Breathe out as you press.",mistakes:[{error:"You lower the bar all the way to your neck.",fix:"Stop higher — a few centimetres above the collarbones is the bottom. Set the safeties so you cannot go further."},{error:"Your shoulder blades come apart and your shoulders roll forward at the bottom.",fix:"Squeeze the shoulder blades harder and shorten the range. If they still slip, go back to a regular bench press."},{error:"You load it like your bench press.",fix:"Start with the empty bar and add weight only in the smallest steps. This is a light, feel-the-chest movement, not a strength lift."}],feelIt:"The upper part of your chest. Not the front of your shoulders — the moment you feel it there, stop the set.",easier:"The regular bench press — same muscles, more room for your shoulders, and it is the version to build strength on.",harder:"Pause for a beat above the collarbones. Add weight only when every rep of the set is identical."},"incline-bench-press":{setup:["Bench between 30 and 45 degrees. Lower is easier on the shoulders — start there.","Sit back so your hips and upper back are on the pad, feet flat and planted.","Shoulder blades squeezed together and down. Grip a little wider than your shoulders."],cues:["Lower the bar to the top of your chest, just below the collarbones.","Elbows under the bar, tucked to about 45 degrees.","Press up and very slightly back, toward your face."],tempo:"2–3 seconds down · touch lightly · press up under control",breathing:"Breathe in as the bar comes down. Breathe out as you press.",mistakes:[{error:"The bar comes down to your throat.",fix:"Aim for the top of the chest, not the neck. Set the bench one notch lower and the bar lands where it should."},{error:"Your hips slide down and your lower back arches off the pad.",fix:"Sit higher on the bench and drive your feet into the floor. If you still arch, the weight is too heavy."},{error:"The bar bounces off your chest.",fix:"Touch, pause for a beat, then press. If you need the bounce, the weight is too heavy."}],feelIt:"The upper part of your chest and the front of your shoulders, with the back of your arms helping. Not your lower back.",easier:"Incline dumbbell press — your shoulders find their own path and there is no bar to aim.",harder:"Pause two seconds on the chest, or add weight in small steps once every rep looks the same."},"decline-barbell-bench-press":{setup:["Hook your legs under the pads before you take the bar — they are what hold you on the bench.","Have someone hand you the bar or help with the lift-off; the rack sits behind your head.","Shoulder blades squeezed together and down. Grip a little wider than your shoulders."],cues:["Lower the bar to your lower chest, elbows tucked to about 45 degrees.","Press straight up. The range is short — do not force the bar higher than straight arms.","Keep your head and upper back on the bench the whole set."],tempo:"2–3 seconds down · touch lightly · press up under control",breathing:"Breathe in as the bar comes down. Breathe out as you press.",mistakes:[{error:"The bar lands high on your chest or at your throat.",fix:"Aim for the bottom of the breastbone. On a decline the bar sits lower than you expect — let it."},{error:"The bar bounces off your chest.",fix:"Touch, pause for a beat, then press. If you need the bounce, the weight is too heavy."},{error:"You feel light-headed by the end of the set.",fix:"Keep the sets short, breathe every rep, and sit up slowly between them. Fewer reps at a time is fine."}],feelIt:"The lower part of your chest and the back of your arms. Your legs will work to hold you in place — that is normal.",easier:"Flat bench press, or the decline dumbbell press — dumbbells are easier to get into position without help.",harder:"Pause a second on the chest, or add weight in small steps."},"wide-grip-decline-bench-press":{setup:["Legs hooked under the pads, someone to help with the lift-off.","Grip about one hand-width wider than your usual bench grip, wrists straight over your elbows.","Shoulder blades squeezed together and down before you take the bar."],cues:["Lower the bar to your lower chest, elbows under the bar.","Keep your shoulder blades pinned — the wide grip wants to pull them apart.","Press up under control. The range is short; a shallow, tidy rep is the goal."],tempo:"3 seconds down · touch lightly · press up under control",breathing:"Breathe in as the bar comes down. Breathe out as you press.",mistakes:[{error:"Your elbows flare straight out and your shoulders feel pinched at the front.",fix:"Bring the grip in by a hand-width. If the pinch stays, do the decline press with a regular grip."},{error:"The bar bounces off your chest.",fix:"Touch, pause for a beat, then press. If you need the bounce, the weight is too heavy."},{error:"Your wrists bend back and the bar sits in your fingers.",fix:"Bar low in the palm, over the forearm bone. Narrow the grip until you can keep the wrist straight."}],feelIt:"Across the lower part of your chest. Not the front of your shoulders — if you feel it there, narrow the grip.",easier:"Decline barbell bench press with a regular grip, or the flat bench press.",harder:"Pause two seconds on the chest, or add weight in small steps."},"reverse-triceps-bench-press-with-barbell":{setup:["Palms face toward your head — an underhand grip, hands about shoulder width apart.","Wrap your thumbs around the bar. This grip is the awkward part, so start with the empty bar.","Have someone hand you the bar, or press from safety pins set just above your chest. Shoulder blades squeezed together and down."],cues:["Elbows tucked to your ribs, wrists straight, the whole rep.","Lower the bar to the bottom of your chest, just above your stomach.","Press up and slightly toward your feet. Finish with your arms straight."],tempo:"3 seconds down · touch lightly · press up under control",breathing:"Breathe in as the bar comes down. Breathe out as you press.",mistakes:[{error:"Your wrists bend back and the bar wants to roll out of your hands.",fix:"Thumbs around the bar, bar low in the palm, and less weight. If you still cannot hold the wrist straight, do the close-grip bench press instead."},{error:"Your elbows drift out to the sides.",fix:"Think about brushing your ribs with your elbows. Use a lighter bar until they stay there for the whole set."},{error:"The bar drifts toward your face on the way up.",fix:"Lower to the same low spot every rep and press slightly toward your feet. Set the safeties in case it does."}],feelIt:"The back of your arms, with the lower chest helping. Not your wrists.",easier:"Close-grip barbell bench press — the same elbow path with a grip your wrists already know.",harder:"Pause a second on the chest, or slow the lowering to four seconds. Add weight in the smallest steps."},"bench-press-dumbbell":{setup:["Sit on the end of the bench with the dumbbells on your thighs, then lie back and use your knees to kick them up to your chest.","Feet flat and planted, shoulder blades squeezed together and down.","Start with the dumbbells above your chest, arms straight, palms facing forward."],cues:["Lower until the dumbbells are level with your chest and you feel a light stretch.","Elbows tucked to about 45 degrees, not straight out to the sides.","Press up and slightly in, so the dumbbells come together above your chest without clanking."],tempo:"2–3 seconds down · brief pause at the bottom · press up under control",breathing:"Breathe in as the dumbbells come down. Breathe out as you press.",mistakes:[{error:"Your elbows flare straight out and your shoulders feel pinched.",fix:"Tuck them toward your ribs. Turn the dumbbells slightly inward at the bottom — most people's shoulders prefer it."},{error:"You drop the dumbbells far below your chest for a bigger stretch.",fix:"Stop when the dumbbells are level with your chest. Deeper than that is your shoulder joint stretching, not your chest working."},{error:"The dumbbells wander outward on the way up.",fix:"Press to a point above your chest, not straight up from where they are. Less weight until the path is the same every rep."}],feelIt:"Your chest, with the back of your arms and front of your shoulders helping. Shoulders should feel set and stable.",easier:"Lighter dumbbells, or push-ups with your hands on a bench.",harder:"Pause at the bottom, slow the lowering to four seconds, or press one arm at a time."},"incline-dumbbell-press":{setup:["Bench between 30 and 45 degrees — lower is easier on the shoulders.","Kick the dumbbells up from your thighs as you lie back. Hips and upper back on the pad, feet flat.","Start with the dumbbells at shoulder height, elbows pointing down toward the floor."],cues:["Press up and slightly in, so the dumbbells meet above your upper chest.","Elbows tucked to about 45 degrees, wrists straight.","Lower under control until the dumbbells are level with your chest."],tempo:"2–3 seconds down · brief pause at the bottom · press up under control",breathing:"Breathe in as the dumbbells come down. Breathe out as you press.",mistakes:[{error:"Your elbows flare straight out to the sides.",fix:"Tuck them a little toward your ribs and turn the dumbbells slightly inward at the bottom."},{error:"The bench is so steep it feels like a shoulder press.",fix:"Drop it a notch. Between 30 and 45 degrees puts the work on the upper chest."},{error:"Your lower back arches off the pad and your hips slide down.",fix:"Sit higher, drive your feet into the floor, and use less weight until your back stays on the pad."}],feelIt:"The upper part of your chest and the front of your shoulders. Not your lower back.",easier:"Flat dumbbell bench press, or lighter dumbbells on a lower incline.",harder:"Pause at the bottom, slow the lowering to four seconds, or add weight in small steps."},"hammer-grip-incline-bench-press":{setup:["Bench between 30 and 45 degrees. Kick the dumbbells up from your thighs as you lie back.","Palms facing each other, dumbbells at the sides of your chest, elbows pointing down.","Feet flat, hips and upper back on the pad, shoulder blades squeezed together and down."],cues:["Press straight up, elbows close to your ribs — the grip keeps them there for you.","Wrists straight, dumbbells stacked over your elbows.","Lower under control to the sides of your chest."],tempo:"2–3 seconds down · brief pause at the bottom · press up under control",breathing:"Breathe in as the dumbbells come down. Breathe out as you press.",mistakes:[{error:"The dumbbells drift apart at the top.",fix:"Press to a point above your upper chest, dumbbells almost touching. Less weight until the path is the same every rep."},{error:"Your elbows swing out and the palms turn forward.",fix:"Keep the palms facing each other the whole rep. If they turn on their own, the weight is too heavy."},{error:"Your lower back arches off the pad.",fix:"Sit higher and drive your feet into the floor. Use less weight until your back stays on the pad."}],feelIt:"The upper part of your chest and the back of your arms. This grip is often the most comfortable incline press for the shoulders.",easier:"The same movement on a flat bench, or lighter dumbbells.",harder:"The regular incline dumbbell press with palms forward, or a pause at the bottom."},"decline-dumbbell-bench-press":{setup:["Hook your legs under the pads first. Then take the dumbbells — ideally handed to you once you are lying back.","Shoulder blades squeezed together and down, head on the bench.","Start with the dumbbells above your lower chest, arms straight."],cues:["Lower the dumbbells to the sides of your lower chest, elbows tucked to about 45 degrees.","Press up and slightly in. Stop at straight arms.","Keep your head and upper back on the bench the whole set."],tempo:"2–3 seconds down · brief pause at the bottom · press up under control",breathing:"Breathe in as the dumbbells come down. Breathe out as you press.",mistakes:[{error:"The dumbbells drift out wide at the bottom.",fix:"Keep them over your elbows and your elbows tucked. Wide at the bottom is where shoulders complain."},{error:"You drop far below your chest for a bigger stretch.",fix:"Stop when the dumbbells are level with your chest. The stretch you feel deeper is the joint, not the muscle."},{error:"You feel light-headed by the end of the set.",fix:"Keep the sets short, breathe every rep, and sit up slowly between them."}],feelIt:"The lower part of your chest and the back of your arms.",easier:"Flat dumbbell bench press — easier to get into and out of.",harder:"Pause at the bottom, or add weight in small steps."},"one-arm-bench-press":{setup:["Kick one dumbbell up as you lie back. The free hand holds the edge of the bench or rests on your stomach.","Feet wide and planted — they are what stop you rolling toward the dumbbell.","Both shoulder blades squeezed together and down, even though only one side is working."],cues:["Press without letting your body roll — hips and shoulders stay square to the ceiling.","Elbow tucked to about 45 degrees, dumbbell stacked over the elbow.","Lower to chest level and press up over the same spot every rep."],tempo:"2–3 seconds down · brief pause · press up under control",breathing:"Breathe in as the dumbbell comes down. Breathe out as you press.",mistakes:[{error:"Your body tips toward the working arm on the way down.",fix:"Brace your stomach and push the opposite foot into the floor. Use less weight until you stay square."},{error:"The free hand starts helping by shoving the bench.",fix:"Rest it on your stomach instead. If you need it, the weight is too heavy."},{error:"The dumbbell wanders outward at the top.",fix:"Press to a point above your chest, not straight up. Same path every rep."}],feelIt:"The chest on the working side, plus your stomach working hard to keep you level.",easier:"The two-dumbbell bench press — the second dumbbell balances the first.",harder:"Pause at the bottom, or slow the lowering to four seconds."},"one-arm-barbell-floor-press":{setup:["Lie on your back, knees bent, feet flat. Have someone hand you the bar, or start with it on low safety pins beside you.","Grip the bar dead centre — a hand off centre and it tips. Start with an empty bar.","Free arm out to the side on the floor for balance. Brace your stomach."],cues:["Keep the bar level. Balance is the exercise here — the weight is second.","Lower until the back of your upper arm rests lightly on the floor, then pause.","Press straight up, elbow tucked, wrist straight."],tempo:"2 seconds down · rest the arm on the floor for a beat · press up under control",breathing:"Breathe in as the bar comes down. Breathe out as you press.",mistakes:[{error:"The bar tips to one side.",fix:"Re-find the centre of the bar and use less weight. If it still tips, do this with a dumbbell instead."},{error:"You bounce your arm off the floor.",fix:"Let the arm settle for a beat, then press from a dead stop. The stop is the point of the floor press."},{error:"Your elbow flares out and the bar drifts over your face.",fix:"Tuck the elbow toward your ribs and press toward your feet slightly. Lighter until the path is straight."}],feelIt:"Your chest and the back of your arm, with your forearm working hard to keep the bar level.",easier:"The same movement with a dumbbell — nothing to balance — or the one-arm bench press.",harder:"Pause longer on the floor, or add weight in the smallest steps you have."},"machine-bench-press":{setup:["Set the seat so the handles line up with the middle of your chest.","Sit right back, shoulder blades pinned to the pad, feet on the rests.","Grip the handles with your wrists straight."],cues:["Press the handles away without letting your shoulders roll forward off the pad.","Stop just short of locking your elbows.","Bring the handles back slowly until your hands are level with your chest."],tempo:"1 second to press · brief pause · 3 seconds back",breathing:"Breathe out as you press. Breathe in as it returns.",mistakes:[{error:"The handles are up at your shoulders instead of your chest.",fix:"Raise the seat. Handles at mid-chest is the setting; it takes ten seconds and changes everything."},{error:"Your shoulders come off the pad to reach the end of the press.",fix:"Keep the shoulder blades pinned and finish a little short. The reach is your shoulder, not your chest."},{error:"The weight stack slams down between reps.",fix:"Take three full seconds on the way back. The slow half is where most of the work is."}],feelIt:"Your chest, with the back of your arms helping. Your back should feel flat and supported.",easier:"Less weight and a shorter range — a controlled rep beats a full one that yanks your shoulders forward.",harder:"Pause at the end of the press, or slow the return to four seconds."},"decline-chest-press":{setup:["Set the seat so the handles line up with the lower part of your chest.","Sit right back, shoulder blades pinned to the pad, feet flat on the rests.","Wrists straight over the handles."],cues:["Press the handles forward and slightly down, shoulders staying on the pad.","Stop just short of locking your elbows.","Bring the handles back slowly until your hands are level with your chest."],tempo:"1 second to press · brief pause · 3 seconds back",breathing:"Breathe out as you press. Breathe in as it returns.",mistakes:[{error:"Your shoulders roll forward off the pad at the end of the press.",fix:"Keep the shoulder blades pinned and finish a little short. Less weight if they keep coming off."},{error:"The handles are too high and it feels like a normal chest press.",fix:"Raise the seat so the handles sit at the bottom of your chest. That is the whole difference."},{error:"The weight stack slams down between reps.",fix:"Take three full seconds on the way back. Control the weight; do not let it control you."}],feelIt:"The lower part of your chest and the back of your arms.",easier:"The machine bench press, or push-ups.",harder:"Pause at the end of the press, or slow the return to four seconds."},"smith-machine-bench-press":{setup:["Set the bench so the bar comes down to the lower half of your chest — the bar path is fixed, so where you put the bench decides where it lands. Test with the empty bar.","Set the safety catches just below chest height.","Feet planted, shoulder blades squeezed together and down. Grip a little wider than your shoulders."],cues:["Lower the bar to the lower half of your chest, elbows tucked to about 45 degrees.","Press up under control. The machine guides the bar; you still do the pressing.","Keep your shoulder blades pinned to the bench the whole set."],tempo:"2–3 seconds down · touch lightly · press up under control",breathing:"Breathe in as the bar comes down. Breathe out as you press.",mistakes:[{error:"The bar lands at your throat or your stomach.",fix:"Move the bench, not your body. Slide it until the empty bar touches the lower half of your chest."},{error:"The bar bounces off your chest.",fix:"Touch, pause for a beat, then press. If you need the bounce, the weight is too heavy."},{error:"Your wrists bend back under the bar.",fix:"Bar low in the palm, over the forearm bone. Wrists straight over elbows."}],feelIt:"Your chest and the back of your arms. Shoulders should feel set, not pinched at the front.",easier:"The machine bench press, or less weight with the safeties set high.",harder:"Pause two seconds on the chest, or move to the free-bar bench press once the pattern is grooved."},"smith-machine-incline-bench-press":{setup:["Bench between 30 and 45 degrees, placed so the bar comes down to the top of your chest. Test with the empty bar and move the bench until it does.","Set the safety catches just below where the bar touches.","Hips and upper back on the pad, feet planted, shoulder blades squeezed together and down."],cues:["Lower the bar to the top of your chest, just below the collarbones.","Elbows tucked to about 45 degrees, wrists straight.","Press up under control, shoulder blades pinned."],tempo:"2–3 seconds down · touch lightly · press up under control",breathing:"Breathe in as the bar comes down. Breathe out as you press.",mistakes:[{error:"The bar comes down on your throat.",fix:"Slide the bench toward your feet until the empty bar lands on the top of your chest. Never adjust by lifting your head."},{error:"The bar bounces off your chest.",fix:"Touch, pause for a beat, then press. If you need the bounce, the weight is too heavy."},{error:"Your hips slide down and your back arches off the pad.",fix:"Sit higher and drive your feet into the floor. Use less weight until your back stays on the pad."}],feelIt:"The upper part of your chest and the front of your shoulders.",easier:"Incline dumbbell press — no bar path to line up.",harder:"Pause two seconds on the chest, or move to the free-bar incline bench press."},"smith-machine-close-grip-bench-press":{setup:["Flat bench placed so the bar comes down to the lower half of your chest. Test with the empty bar.","Hands about shoulder width apart — the very narrow grip some people use just bends the wrists.","Safety catches set just below chest height. Shoulder blades squeezed together and down."],cues:["Elbows tucked along your ribs, the whole way down and up.","Stop just above your chest, pause, then press.","Finish with your arms straight, wrists stacked over your elbows."],tempo:"2–3 seconds down · pause above the chest · press up under control",breathing:"Breathe in as the bar comes down. Breathe out as you press.",mistakes:[{error:"Your wrists bend back and ache.",fix:"Widen the grip to shoulder width and keep the bar low in your palm."},{error:"Your elbows flare out and it becomes a normal press.",fix:"Think about brushing your ribs with your elbows. Use less weight until they stay tucked for the whole set."},{error:"The bar bounces off your chest.",fix:"Stop just above the chest, pause for a beat, then press. The pause is part of the exercise."}],feelIt:"The back of your arms first, then your chest. Not your wrists.",easier:"The machine bench press, or push-ups with your hands close together.",harder:"Pause longer above the chest, or move to the free-bar close-grip bench press."},"push-up-feet-elevated":{setup:["Feet on a bench, hands on the floor under your shoulders or a touch wider.","Body in one straight line from head to heels — it is easy to pike at the hips here.","Squeeze your glutes and stomach before the first rep."],cues:["Lower your whole body as one piece until your chest is near the floor.","Elbows travelling back at about 45 degrees, not straight out to the sides.","Push the floor away and finish with your shoulder blades spread."],tempo:"2 seconds down · brief pause · push up under control",breathing:"Breathe in on the way down. Breathe out as you push.",mistakes:[{error:"Your hips rise into a peak and it turns into a shoulder exercise.",fix:"Squeeze your glutes and push your hips down into the line. A lower bench makes the line easier to hold."},{error:"Your head reaches the floor before your chest does.",fix:"Keep your chin tucked and lead with your chest. Your head should be the last thing to move."},{error:"You only go down a few centimetres.",fix:"Use a lower bench and do the full range there. Half a rep trains half the muscle."}],feelIt:"The upper part of your chest, the front of your shoulders, and your stomach holding the line. Not your lower back.",easier:"Regular push-ups with your feet on the floor, or a lower step.",harder:"A higher bench, a pause at the bottom, or slow the lowering to four seconds."},"bench-dips":{setup:["Hands on the edge of a bench behind you, fingers pointing forward, arms straight.","Feet out in front — on the floor with your knees bent to start, on a second bench once that is easy.","Slide forward so your backside just clears the bench. Stay close to it."],cues:["Lower until your upper arms are level with the floor — no deeper.","Elbows pointing straight back, not out to the sides.","Keep your back brushing the bench the whole way down and up."],tempo:"2 seconds down · brief pause · push up under control",breathing:"Breathe in as you lower. Breathe out as you push up.",mistakes:[{error:"You go deep and your shoulders feel pinched at the front.",fix:"Stop higher — upper arms level with the floor is the bottom. Depth here is not something to chase."},{error:"Your hips drift forward away from the bench.",fix:"Keep your back brushing the bench. Drifting forward moves the work to the front of your shoulders."},{error:"Your shoulders shrug up toward your ears at the bottom.",fix:"Push your shoulders down before you lower, and shorten the range until they stay there."}],feelIt:"The back of your arms. Not the front of your shoulders — if you feel it there, stop the rep higher.",easier:"Feet flat on the floor with your knees bent, and a shorter range.",harder:"Feet up on a second bench, then a weight plate on your lap."},"cable-crossover":{setup:["Pulleys at shoulder height or a little above. Take a handle in each hand.","Step forward with one foot until the cables pull your arms back — a light stretch across the chest, no more.","Lean forward slightly and set a small bend in your elbows. That bend does not change during the set."],cues:["Sweep your hands together in front of your lower chest, elbows fixed.","Squeeze your chest for a beat where your hands meet.","Let the arms open slowly until you feel the stretch again — then stop."],tempo:"1 second to bring together · squeeze for a beat · 3 seconds back out",breathing:"Breathe out as your hands come together. Breathe in as they open.",mistakes:[{error:"Your elbows bend and straighten, so it becomes a press.",fix:"Set the elbow bend at the start and freeze it. Use less weight — if you have to bend, it is too heavy."},{error:"Your shoulders roll forward as your hands meet.",fix:"Keep your chest up and your shoulders back. Bring the hands together a little lower so the chest does the squeezing."},{error:"Your body rocks back and forth to move the weight.",fix:"Stand still with one foot forward and drop the weight. Only your arms move."}],feelIt:"Across your chest, especially where your hands meet. Not the front of your shoulders.",easier:"Less weight, or push-ups. The stretch at the start is what people overdo — keep it light.",harder:"Cross your hands over each other at the front, or hold the squeeze for two seconds."},"jm-press":{setup:["A mix of a close-grip bench press and a lying triceps extension. It is an advanced movement — start with the empty bar and keep it light.","Lie on a flat bench, shoulder blades squeezed together and down, feet planted.","Grip about shoulder width apart, bar over your upper chest. Set the safeties."],cues:["Lower the bar toward the top of your chest by bending the elbows, which point forward.","Stop a few centimetres above your chest and pause.","Press back up in a straight line to where you started."],tempo:"2 seconds down · pause above the chest · press up under control",breathing:"Breathe in as the bar comes down. Breathe out as you press.",mistakes:[{error:"The bar drifts over your face.",fix:"Bring it down toward the top of the chest, not the chin. Set the safeties so a drifting bar stops before you do."},{error:"Your elbows flare out and it turns into a bench press.",fix:"Keep the elbows pointing forward, above the bar. Less weight until they stay there for every rep."},{error:"You load it like your close-grip bench.",fix:"It is far lighter than that. Add weight only in the smallest steps and only when every rep looks the same."}],feelIt:"The back of your arms, hard. Not your elbows — if you feel it in the joint, the weight is too heavy.",easier:"Close-grip barbell bench press — the same elbow path with the bar going to the chest.",harder:"Pause longer above the chest. Add weight slowly; this movement rewards patience."},"one-arm-dumbbell-shoulder-press":{setup:["Stand with your feet under your hips, one dumbbell at shoulder height, palm facing forward or slightly in.","Free hand on your hip, or holding something solid for balance.","Brace your stomach and squeeze your glutes before the first rep."],cues:["Press straight up until your arm is beside your ear, without leaning away.","Wrist straight over the elbow, elbow under the dumbbell.","Lower under control back to shoulder height."],tempo:"Press up under control · brief pause at the top · 2–3 seconds down",breathing:"Breathe out as you press. Breathe in as the dumbbell comes down.",mistakes:[{error:"You lean sideways away from the dumbbell to get it up.",fix:"Brace your stomach and keep your ribs down. If you still lean, the weight is too heavy."},{error:"Your lower back arches as you press.",fix:"Squeeze your glutes and think about keeping your ribs over your hips. Sit down on a bench if it keeps happening."},{error:"Your elbow drifts behind you at the bottom.",fix:"Keep the elbow slightly in front of your body, under the dumbbell, so the press goes straight up."}],feelIt:"The shoulder on the working side and the back of your arm, plus your stomach working to keep you upright.",easier:"The same press seated with your back against a bench, or lighter dumbbells with both arms at once.",harder:"Pause a second at the top, or slow the lowering to four seconds."},"t-bar-rows":{setup:["Stand over the bar with a foot either side, knees slightly bent and kept that way.","Push your hips back and bend forward until your chest is roughly parallel to the floor. Back flat.","Take the handles with a narrow grip and let your arms hang straight."],cues:["Start the pull with your shoulder blades, before your arms bend.","Drive your elbows past your ribs and bring the bar to your lower chest.","Torso stays still. Lower all the way until your arms are straight."],tempo:"1 second to pull · squeeze for a beat · 3 seconds down",breathing:"Breathe out as you pull. Breathe in as you lower.",mistakes:[{error:"Your lower back rounds as the set goes on.",fix:"Push your hips back and lift your chest to re-set. Stand a little more upright, and use less weight."},{error:"You stand up with each rep to heave the bar.",fix:"Fix the angle of your body at the start and keep it. If you have to stand up to move the weight, it is too heavy."},{error:"Your shoulders shrug up toward your ears.",fix:"Pull the shoulder blades down and together, not up. Elbows drive back, not shoulders up."}],feelIt:"Between and around your shoulder blades, and the sides of your back. Your lower back should feel braced, not strained.",easier:"Seated cable rows — the same pull with your back supported by the position.",harder:"Pause two seconds at the top, or add weight in small steps."},"reverse-grips-bent-over-barbell-rows":{setup:["Hold the bar with your palms facing forward, hands about shoulder width apart.","Push your hips back and lean forward to about 45 degrees, knees slightly bent. Back flat.","Let the bar hang with your arms straight, below your chest."],cues:["Pull the bar to your belly button, elbows sliding back along your ribs.","Start with the shoulder blades, finish with the arms.","Torso stays at the same angle. Lower all the way to straight arms."],tempo:"1 second to pull · squeeze for a beat · 3 seconds down",breathing:"Breathe out as you pull. Breathe in as you lower.",mistakes:[{error:"You stand up with each rep and the bar swings.",fix:"Keep the lean fixed. If you have to stand up to move the weight, it is too heavy."},{error:"Your arms do all the work and it feels like a curl.",fix:"Start the pull with your shoulder blades and drive the elbows back, not the hands up."},{error:"Your lower back rounds.",fix:"Push your hips back and lift your chest. Lean less, and use less weight, until the back stays flat."}],feelIt:"Between your shoulder blades and the sides of your back. Some bicep work is normal with this grip.",easier:"Seated cable rows, or a body row.",harder:"Pause two seconds at the top, or slow the lowering further."},"rear-deltoid-row-barbell":{setup:["Wide overhand grip on the bar — hands well outside your shoulders.","Push your hips back and lean forward until your chest is close to parallel with the floor. Knees slightly bent, back flat.","Let the bar hang with your arms straight, directly below your chest."],cues:["Pull your elbows out wide and up, toward the ceiling — not back toward your hips.","Bring the bar to the lower part of your chest.","Torso stays still. Lower under control until your arms are straight."],tempo:"1 second to pull · squeeze for a beat · 3 seconds down",breathing:"Breathe out as you pull. Breathe in as you lower.",mistakes:[{error:"Your elbows tuck in and the bar goes to your stomach.",fix:"Elbows out wide, bar to the chest. That is the whole difference from a normal row — keep the weight light enough to feel it."},{error:"You heave with your body to get the bar up.",fix:"Keep the lean fixed. Use less weight — this is a small-muscle movement and it does not need much."},{error:"Your shoulders shrug up toward your ears.",fix:"Keep your neck long and drive the elbows out, not up. Less weight if the shrug will not go away."}],feelIt:"The back of your shoulders and between your shoulder blades. Not your lower back.",easier:"The same movement with dumbbells, or a lying rear lateral raise face down on a bench.",harder:"Pause two seconds at the top, or slow the lowering to four seconds."},"upright-barbell-rows":{setup:["Keep the range short and the weight light. Stand with your feet under your hips, bar hanging in front of your thighs.","Hands a little wider than shoulder width. A narrow grip is what makes the shoulders complain.","Brace your stomach. Shoulders down, away from your ears."],cues:["Lead with your elbows, lifting them out to the sides no higher than your shoulders.","The bar travels close to your body and stops around the bottom of your chest.","Lower under control. Nothing is pulled to the chin."],tempo:"1 second up · brief pause · 3 seconds down",breathing:"Breathe out as the bar rises. Breathe in as it lowers.",mistakes:[{error:"You pull the bar to your chin with your elbows above your shoulders.",fix:"Stop when the elbows are level with the shoulders — the bar ends around the bottom of your chest. Shorter is the version to do."},{error:"You rock your body to get the bar moving.",fix:"Stand still and use less weight. A light bar lifted smoothly does more here than a heavy one heaved."},{error:"Your grip is narrow and your wrists bend at the top.",fix:"Widen the grip to just outside shoulder width. Wrists stay straight, elbows lead."}],feelIt:"The sides and tops of your shoulders, and the muscles between your neck and shoulders. Not the front of your shoulders — if you feel a pinch there, shorten the range or stop the set.",easier:"Lateral dumbbell raises — the same shoulder muscles with your arms free to find their own path.",harder:"Pause for a beat at the top. Add weight only in the smallest steps and only if the range stays short."},"upright-cable-row":{setup:["Keep the range short and the weight light. Straight bar on the low pulley, hands a little wider than shoulder width.","Stand back a step so the cable pulls slightly forward and down, not straight up your body.","Brace your stomach, shoulders down, bar hanging at your thighs."],cues:["Lead with your elbows out to the sides, stopping when they are level with your shoulders.","The bar stays close to your body and stops around the bottom of your chest.","Lower under control against the cable."],tempo:"1 second up · brief pause · 3 seconds down",breathing:"Breathe out as the bar rises. Breathe in as it lowers.",mistakes:[{error:"You pull the bar to your chin.",fix:"Stop when the elbows reach shoulder height. The cable makes going higher feel easy — that is not a reason to."},{error:"The cable pulls you forward and you lean back to fight it.",fix:"Stand a step further from the stack and brace. If you still lean, drop the weight."},{error:"Your shoulders shrug up before your elbows move.",fix:"Shoulders down first, then elbows out. Less weight until the order stays right."}],feelIt:"The sides and tops of your shoulders. Not the front of your shoulders — if you feel a pinch there, shorten the range or stop the set.",easier:"Lateral dumbbell raises, or front cable raises.",harder:"Pause for a beat at the top, or slow the lowering to four seconds. Keep the range short as you add."},"smith-machine-upright-row":{setup:["Keep the range short and the weight light. The bar path is fixed, so stand where the bar hangs against your thighs.","Hands a little wider than shoulder width. Set the safety catches at thigh height.","Brace your stomach, shoulders down, away from your ears."],cues:["Lead with your elbows out to the sides, no higher than your shoulders.","The bar stops around the bottom of your chest.","Lower under control to the catches."],tempo:"1 second up · brief pause · 3 seconds down",breathing:"Breathe out as the bar rises. Breathe in as it lowers.",mistakes:[{error:"You pull the bar up to your chin.",fix:"Stop when the elbows are level with the shoulders. Shorter is the version to do."},{error:"The fixed path forces your wrists to bend at the top.",fix:"Widen the grip a little and stop the bar lower. If the wrists still bend, do this with dumbbells instead."},{error:"You use your legs and hips to start the bar moving.",fix:"Stand still. Less weight — the bar should start moving from your elbows alone."}],feelIt:"The sides and tops of your shoulders. Not the front of your shoulders or your wrists — if either complains, stop the set.",easier:"Lateral dumbbell raises — nothing fixes your hands in place.",harder:"Pause for a beat at the top. Add weight only in the smallest steps and only if the range stays short."},"one-arm-upright-row":{setup:["Keep the range short and the weight light. One dumbbell hanging in front of your thigh, palm facing your body.","Free hand holding a post or rack for balance.","Brace your stomach, shoulder down, away from your ear."],cues:["Lead with your elbow out to the side, stopping when it is level with your shoulder.","The dumbbell stays close to your body and ends around the bottom of your chest.","Lower under control. Do not lean away from the dumbbell."],tempo:"1 second up · brief pause · 3 seconds down",breathing:"Breathe out as the dumbbell rises. Breathe in as it lowers.",mistakes:[{error:"You pull the dumbbell to your chin with your elbow high above your shoulder.",fix:"Stop at shoulder height. Shorter is the version to do; the last few centimetres add nothing."},{error:"You lean sideways to get the dumbbell up.",fix:"Stand tall and brace. Use less weight until you stay upright for the whole set."},{error:"Your shoulder shrugs up before your elbow moves.",fix:"Shoulder down first, then elbow out. The shrug means the weight is too heavy."}],feelIt:"The side and top of the working shoulder. Not the front of it — if you feel a pinch there, shorten the range or stop the set.",easier:"A lateral dumbbell raise on one side — the same muscles, arm free.",harder:"Pause for a beat at the top. Keep the range short as you add weight."},"underhand-pull-downs":{setup:["Set the thigh pad snug so you stay in the seat when the weight gets heavy.","Palms facing you, hands about shoulder width apart.","Sit tall with a slight lean back, and keep that lean for the whole set."],cues:["Pull your shoulders down away from your ears before your arms bend.","Bring the bar to the top of your chest, elbows close to your body and driving down.","Control the weight all the way back up until your arms are straight."],tempo:"1 second to pull · squeeze for a beat · 3 seconds back up",breathing:"Breathe out as you pull down. Breathe in as it goes up.",mistakes:[{error:"You lean further and further back until it becomes a row.",fix:"Fix the lean at the start and hold it. If you have to lean to move the weight, it is too heavy."},{error:"Your arms do all the work and it feels like a curl.",fix:"Shoulders down first, elbows drive down toward your pockets. The arms finish the rep; they should not start it."},{error:"Your shoulders shrug up at the top of each rep.",fix:"Let the arms straighten but keep the shoulders pulled down. Slow the return to three seconds."}],feelIt:"The sides of your back, under your armpits, with your biceps helping — more than on the wide grip. That is normal.",easier:"Less weight. This is the machine to learn the pull on before you attempt a chin-up.",harder:"Pause at your chest for two seconds, or move to chin-ups with the same grip."},"front-dumbbell-raise":{setup:["A dumbbell in each hand, resting against the front of your thighs, palms facing your legs.","Feet under your hips, knees soft, stomach braced.","Shoulders down, away from your ears."],cues:["Raise one arm straight in front of you to shoulder height, no higher.","Keep a small bend in the elbow and the arm still — no swing.","Lower slowly, then the other arm. The body does not move."],tempo:"1 second up · brief pause at shoulder height · 3 seconds down",breathing:"Breathe out as the arm rises. Breathe in as it lowers.",mistakes:[{error:"You rock backwards to swing the dumbbell up.",fix:"Stand still with your stomach braced. Use lighter dumbbells — this needs far less than most people pick."},{error:"The dumbbell goes above your shoulder.",fix:"Stop at shoulder height. Above that your shoulder is shrugging, not lifting."},{error:"Your shoulders shrug up toward your ears.",fix:"Keep your neck long and think about reaching the dumbbell forward, not up."}],feelIt:"The front of your shoulders. Not your neck, and not your lower back.",easier:"Lighter dumbbells, or sit on a bench so the body cannot help.",harder:"Both arms at once, a pause at the top, or slow the lowering to four seconds."},"lying-rear-lateral-raise":{setup:["Lie face down on a bench raised high enough that your arms can hang straight down without touching the floor.","Toes on the floor for balance. Forehead just past the end of the bench, or resting on it.","Dumbbells hanging below your shoulders, a slight bend in each elbow. Keep that bend."],cues:["Raise your arms out to the sides until they are level with your shoulders.","Lead with the elbows — think about pushing the dumbbells away, not lifting them up.","Lower slowly. The dumbbells never swing."],tempo:"1 second up · squeeze for a beat · 3 seconds down",breathing:"Breathe out as the arms rise. Breathe in as they lower.",mistakes:[{error:"Your elbows bend more and more and it becomes a row.",fix:"Set a slight bend at the start and keep it. Lighter dumbbells until it holds."},{error:"The dumbbells swing up and drop back down.",fix:"One second up, three seconds down. Swinging means the weight is too heavy — halve it."},{error:"Your shoulders shrug up toward your ears.",fix:"Keep your neck long and drive the elbows out to the sides, not up toward your head."}],feelIt:"The back of your shoulders and between your shoulder blades. Not your neck.",easier:"Lighter dumbbells — most people need less than five kilos to begin with.",harder:"Pause for two seconds at the top, or slow the lowering to four seconds."},"lying-one-arm-rear-lateral-raise":{setup:["Lie face down on a bench high enough that your working arm can hang straight without touching the floor.","The free hand rests on the floor to keep you steady.","Dumbbell hanging below your shoulder, a slight bend in the elbow. Keep that bend."],cues:["Raise the arm out to the side until it is level with your shoulder.","Lead with the elbow. Your body stays flat on the bench — do not twist to help.","Lower slowly. The dumbbell never swings."],tempo:"1 second up · squeeze for a beat · 3 seconds down",breathing:"Breathe out as the arm rises. Breathe in as it lowers.",mistakes:[{error:"You twist your body toward the working side to get the dumbbell up.",fix:"Press your chest into the bench and keep both hips down. Lighter dumbbell until you stay flat."},{error:"The elbow bends more and more and it becomes a row.",fix:"Set a slight bend at the start and keep it. Lighter dumbbell until it holds."},{error:"The dumbbell swings up and drops back down.",fix:"One second up, three seconds down. If it swings, the weight is too heavy."}],feelIt:"The back of the working shoulder and between your shoulder blades. Not your neck.",easier:"The two-arm lying rear lateral raise — the second arm balances the first.",harder:"Pause for two seconds at the top, or slow the lowering to four seconds."},"internal-cable-rotation":{setup:["Sit on the floor side-on to a low pulley, the working arm nearest the stack.","Elbow bent to a right angle and pinned to your side — a rolled towel between your elbow and your ribs keeps it there.","Take the handle with your forearm pointing out toward the stack. Light weight — this is a small movement."],cues:["Rotate your forearm across your stomach, elbow staying glued to your side.","Keep your body still — only the forearm moves.","Let it rotate back out slowly, to where it started."],tempo:"1 second to rotate in · brief pause · 3 seconds back out",breathing:"Breathe out as the forearm comes across. Breathe in as it returns.",mistakes:[{error:"Your elbow drifts away from your side.",fix:"Put a rolled towel between your elbow and ribs and squeeze it. If it still drifts, the weight is too heavy."},{error:"You twist your body to move the weight.",fix:"Sit tall and still. Only the forearm moves. Drop the weight until that is true."},{error:"The weight yanks your arm back out.",fix:"Take three full seconds on the way out. The slow half is where the work is."}],feelIt:"Deep in the front of your shoulder and a little in the chest. Very light — if you need to strain, the weight is wrong.",easier:"The same movement with a light band, or no weight at all while you learn the path.",harder:"Pause at the end of the rotation, or slow the return to four seconds. Add weight in the smallest steps."},"high-cable-curls":{setup:["Flat bench end-on to a cable stack, short bar on the high pulley.","Lie on your back with your head toward the stack and take the bar with palms facing you.","Arms straight, angled up over your head toward the pulley. Feet flat on the floor."],cues:["Curl the bar toward your forehead, keeping your upper arms completely still.","Squeeze at the top for a beat.","Let the bar back up slowly until your arms are straight — do not let the cable yank them."],tempo:"1 second to curl · squeeze for a beat · 3 seconds back",breathing:"Breathe out as you curl. Breathe in as it returns.",mistakes:[{error:"Your elbows drop toward the bench as you curl.",fix:"Keep the upper arms pointing at the pulley. Only the forearms move. Less weight if they keep dropping."},{error:"Your shoulders lift off the bench.",fix:"Keep your upper back pressed into the bench. If the cable pulls you up, the weight is too heavy."},{error:"The weight yanks your arms straight at the bottom.",fix:"Take three full seconds back. Control the weight; do not let it control you."}],feelIt:"The front of your upper arms, especially at the top of the curl. Not your shoulders.",easier:"Standing cable curls, or biceps curls with dumbbells.",harder:"Pause two seconds at the top, or slow the return to four seconds."},"drag-curl-with-barbell":{setup:["Stand with the bar against your thighs, palms facing forward, hands about shoulder width apart.","Feet under your hips, knees soft, stomach braced.","Shoulders down and back. Light weight — this is smaller than a normal curl."],cues:["Drag the bar straight up your body, elbows travelling backwards behind you.","The bar stays in contact with your body the whole way — it never swings out.","Stop when the bar reaches your lower chest. Lower it the same way."],tempo:"1 second up · squeeze for a beat · 3 seconds down",breathing:"Breathe out as the bar rises. Breathe in as it lowers.",mistakes:[{error:"Your elbows come forward and it turns into a normal curl.",fix:"Think about pushing your elbows back behind you as the bar rises. That is the whole movement."},{error:"The bar drifts away from your body.",fix:"Keep it brushing your shirt from thigh to chest. Use less weight — a light bar dragged beats a heavy one swung."},{error:"You lean back to finish the rep.",fix:"Stand still with your stomach braced and stop the bar lower. Leaning back means the weight is too heavy."}],feelIt:"The front of your upper arms, strongly at the top. A little in your forearms is normal.",easier:"Regular biceps curls with a barbell, or with dumbbells.",harder:"Pause two seconds at the top, or slow the lowering to four seconds."},"reverse-grip-triceps-pushdown":{setup:["Straight bar on a high pulley, palms facing up, hands about shoulder width apart.","Stand close to the stack, one foot slightly ahead of the other, stomach braced.","Elbows pinned to your sides, forearms up. Lighter than your normal pushdown."],cues:["Push the bar down until your arms are straight, elbows never leaving your sides.","Wrists stay straight — the bar rests in your fingers and palm, not bent back.","Let it back up slowly until your forearms are level with the floor, or a little higher."],tempo:"1 second down · squeeze for a beat · 3 seconds back up",breathing:"Breathe out as you push down. Breathe in as it returns.",mistakes:[{error:"Your elbows drift forward and up as you push.",fix:"Pin them to your sides and think about only the forearm moving. Less weight until they stay there."},{error:"Your wrists bend back and your fingers open.",fix:"Wrap your thumbs around the bar and use less weight. This grip does not hold much."},{error:"You lean over the bar and push with your body.",fix:"Stand tall and drop the weight. If you have to lean, it is too heavy."}],feelIt:"The back of your arms, especially at the bottom of the push. Not your wrists or fingers.",easier:"The regular triceps pushdown with palms down — your grip is stronger that way.",harder:"Pause two seconds at the bottom, or slow the return to four seconds."},"decline-close-grip-bench-to-skull-crusher":{setup:["Two movements in one rep: a close-grip bench press, then a lying triceps extension at the top. Start with the empty bar.","Lie back on the bench — decline if you have one, flat works the same way. Legs hooked or feet planted.","Hands about shoulder width apart, shoulder blades squeezed together and down. Have someone spot, or set the safeties."],cues:["Press: elbows tucked, bar to the lower chest, press up to straight arms.","Extend: upper arms stay still, bend the elbows to lower the bar toward your forehead, then straighten.","That is one rep. Both halves are slow."],tempo:"Press: 2 seconds down, press up · Extend: 2 seconds down, straighten under control",breathing:"Breathe in as the bar lowers, out as it rises — on both halves of the rep.",mistakes:[{error:"Your elbows flare out during the extension half.",fix:"Point the elbows at the ceiling and keep them there. Use less weight — the extension half is far weaker than the press."},{error:"You load it like a close-grip bench press.",fix:"Load it like a skull crusher — the weaker half sets the weight. Start with the empty bar."},{error:"The bar drifts over your face on the press half.",fix:"Lower to the same spot on your chest every rep and press up and slightly toward your feet. Set the safeties."}],feelIt:"The back of your arms, hard. Not your elbows — if you feel it in the joint, the weight is too heavy.",easier:"The close-grip barbell bench press on its own, then a separate set of lying triceps extensions.",harder:"Pause at the bottom of each half. Add weight only in the smallest steps."},"standing-overhead-triceps-extension-with-barbell":{setup:["Stand with your feet under your hips, stomach braced, knees soft.","Bar or EZ bar overhead, hands close together — a hand-width apart, palms facing forward.","Elbows pointing forward and staying close to your head."],cues:["Bend your elbows to lower the bar behind your head, upper arms staying still.","Stop when you feel a stretch in the back of your arms, then straighten.","Keep your ribs down — do not arch your back to help."],tempo:"2–3 seconds down · brief pause at the bottom · straighten under control",breathing:"Breathe in as the bar lowers. Breathe out as you straighten.",mistakes:[{error:"Your elbows flare out to the sides.",fix:"Think about squeezing your ears with your upper arms. Less weight until they stay close for the whole set."},{error:"Your lower back arches as the bar goes behind your head.",fix:"Brace your stomach, squeeze your glutes, and sit on a bench if it keeps happening."},{error:"The elbows themselves ache rather than the muscle.",fix:"Shorten the range, slow it down, and use less weight. If it stays, do this one arm at a time with a light dumbbell instead."}],feelIt:"The back of your arms, with a stretch at the bottom. Not your lower back, not the elbow joints.",easier:"The same movement seated with your back supported, or the one-arm dumbbell version.",harder:"Pause two seconds at the bottom, or slow the lowering to four seconds."},"one-arm-triceps-extension-with-dumbbell":{setup:["Sit tall on a bench, feet flat, stomach braced.","One dumbbell straight overhead, elbow pointing at the ceiling and close to your head.","Free hand across your chest, or supporting the working elbow from the front."],cues:["Lower the dumbbell behind your head by bending the elbow only — the upper arm stays still.","Stop when you feel a stretch in the back of your arm.","Straighten fully without the elbow drifting out."],tempo:"2–3 seconds down · brief pause at the bottom · straighten under control",breathing:"Breathe in as the dumbbell lowers. Breathe out as you straighten.",mistakes:[{error:"Your elbow drifts out to the side.",fix:"Hold it in place with the free hand. Less weight until it stays on its own."},{error:"You lean sideways away from the dumbbell.",fix:"Sit tall with your stomach braced. If you still lean, the weight is too heavy."},{error:"Your wrist bends back under the dumbbell.",fix:"Keep the wrist straight and the dumbbell stacked over the forearm. Lighter if it keeps bending."}],feelIt:"The back of the working arm, with a stretch at the bottom. Not your neck, not your lower back.",easier:"Hold one dumbbell overhead with both hands — twice the support, half the balancing.",harder:"Pause two seconds at the bottom, or slow the lowering to four seconds."},"bent-over-one-arm-triceps-extension-with-dumbbell":{setup:["Push your hips back and lean forward until your chest is close to parallel with the floor. Free hand on a bench or your thigh.","Dumbbell in the working hand, upper arm lifted so it is level with your body and pinned there.","Elbow bent, forearm hanging straight down. Light weight."],cues:["Straighten your arm behind you — the upper arm does not move at all.","Squeeze for a beat at the top with the arm fully straight.","Lower slowly. The dumbbell never swings."],tempo:"1 second to straighten · squeeze for a beat · 3 seconds down",breathing:"Breathe out as you straighten. Breathe in as it lowers.",mistakes:[{error:"Your upper arm drops toward the floor as the set goes on.",fix:"Lift it back level with your body and keep it there. If it will not stay, the weight is too heavy."},{error:"You swing the dumbbell up with momentum.",fix:"Three seconds down, one second up. This needs far less weight than most people pick."},{error:"Your back rounds as you lean over.",fix:"Push your hips back, lift your chest, and rest the free hand on a bench so your back is supported."}],feelIt:"The back of the working arm, especially at the top. Not your lower back, not your shoulder.",easier:"Lighter dumbbell, or the triceps pushdown on a cable.",harder:"Pause two seconds at the top, or slow the lowering to four seconds."},"bent-over-two-arm-triceps-extension-with-dumbbell":{setup:["Push your hips back and lean forward until your upper body is close to parallel with the floor. Knees soft, back flat.","A dumbbell in each hand, upper arms lifted level with your body and pinned there.","Elbows bent, forearms hanging straight down. Light weights — you have no free hand for support."],cues:["Straighten both arms behind you at once — the upper arms do not move.","Squeeze for a beat at the top.","Lower slowly. Your back stays flat and still."],tempo:"1 second to straighten · squeeze for a beat · 3 seconds down",breathing:"Breathe out as you straighten. Breathe in as they lower.",mistakes:[{error:"Your upper arms drop and the dumbbells swing.",fix:"Lift the upper arms back level with your body and use lighter dumbbells. Both arms at once needs less than one."},{error:"Your back rounds as you tire.",fix:"Push your hips back and lift your chest between reps. If it keeps rounding, do it one arm at a time with a hand on a bench."},{error:"You stand up a little with each rep to help.",fix:"Fix the lean and keep it. Standing up means the weight is too heavy."}],feelIt:"The back of both arms, especially at the top. Your lower back should feel braced, not strained.",easier:"The one-arm version with your free hand on a bench — a supported back and half the balancing.",harder:"Pause two seconds at the top, or slow the lowering to four seconds."},"one-arm-low-pulley-triceps-extension-with-cable":{setup:["Handle on a low pulley. Stand with your back to the stack, feet under your hips.","Reach behind you and take the handle, then bring it overhead so the cable runs up your back.","Working elbow pointing at the ceiling, close to your head. Free hand holds that elbow in place."],cues:["Straighten your arm toward the ceiling — the upper arm does not move.","Lower slowly until you feel a stretch in the back of your arm.","Stand tall the whole set; do not lean away from the cable."],tempo:"1 second to straighten · brief pause · 3 seconds down",breathing:"Breathe out as you straighten. Breathe in as it lowers.",mistakes:[{error:"Your elbow drifts forward and out.",fix:"Hold it with the free hand and use less weight. Only the forearm should move."},{error:"You lean forward to fight the cable.",fix:"Step half a pace back toward the stack and brace your stomach. Lighter if you still lean."},{error:"The weight yanks your arm back down.",fix:"Take three full seconds on the way down. Control the weight; do not let it control you."}],feelIt:"The back of the working arm, with a stretch at the bottom. Not your shoulder, not your lower back.",easier:"The one-arm triceps extension with a dumbbell, seated.",harder:"Pause two seconds at the bottom, or slow the lowering to four seconds."},"standing-triceps-extension-with-towel":{setup:["Stand with your feet under your hips, stomach braced. A partner stands behind you holding the ends of a towel.","Hold the middle of the towel behind your head with both hands, elbows pointing at the ceiling and close to your head.","Agree the resistance out loud before you start — steady, and the same on every rep."],cues:["Straighten your arms overhead against the towel, upper arms staying still.","Lower slowly as the partner keeps the towel taut, until your hands are near your neck.","Keep your ribs down — do not arch to help."],tempo:"2 seconds up · brief pause at the top · 3 seconds down",breathing:"Breathe out as you straighten. Breathe in as you lower.",mistakes:[{error:"The resistance jerks — easy one moment, heavy the next.",fix:"The partner keeps a steady pull and follows your pace. Tell them lighter if you cannot move smoothly."},{error:"Your elbows flare out to the sides.",fix:"Squeeze your ears with your upper arms. Ask for less resistance until they stay close."},{error:"Your lower back arches as you push.",fix:"Brace your stomach and squeeze your glutes. Ask the partner to ease off if you still arch."}],feelIt:"The back of your arms. Not your lower back, not your neck.",easier:"The overhead triceps extension with a light dumbbell — the weight does not change on you.",harder:"The partner adds resistance on the way down only, or you slow the lowering to four seconds."},"bent-arm-pullover":{setup:["Lie on a bench with your head near the end and your feet flat on the floor.","Barbell held with a close grip — about shoulder width — arms straight above your chest, then bend the elbows a little. Keep that bend.","Ribs down, lower back gently on the bench. Light weight to start."],cues:["Lower the bar in an arc over and behind your head, elbows staying bent and pointing up.","Stop when you feel a stretch across your chest and under your armpits — no further.","Pull it back over your chest in the same arc."],tempo:"3 seconds down · brief pause at the stretch · pull back up under control",breathing:"Breathe in as the bar goes behind your head. Breathe out as you pull it back.",mistakes:[{error:"Your arms straighten as the bar goes back.",fix:"Set the elbow bend at the start and keep it. Less weight until it holds — straight arms put the load on the elbows."},{error:"Your lower back arches high off the bench at the bottom.",fix:"Keep your ribs down and stop the bar higher. The arch is your back finding range your shoulders do not have yet."},{error:"You go as deep as you can for a bigger stretch.",fix:"Stop at a comfortable stretch. Range grows over weeks; forcing it is how this movement goes wrong."}],feelIt:"Across your chest and under your armpits, with the back of your arms helping. Not your lower back, not your shoulders' front.",easier:"The dumbbell bent-arm pullover — one dumbbell held in both hands is easier to control — with a shorter range.",harder:"Pause two seconds at the stretch, or add weight in small steps."},"dumbbell-bent-arm-pullover":{setup:["Lie on a bench with your head near the end and your feet flat on the floor.","Hold one dumbbell by the inside of the top plate with both hands, arms above your chest, elbows bent a little. Keep that bend.","Ribs down, lower back gently on the bench."],cues:["Lower the dumbbell in an arc over and behind your head, elbows staying bent.","Stop when you feel a stretch across your chest and under your armpits.","Pull it back over your chest in the same arc."],tempo:"3 seconds down · brief pause at the stretch · pull back up under control",breathing:"Breathe in as the dumbbell goes behind your head. Breathe out as you pull it back.",mistakes:[{error:"Your arms straighten as the dumbbell goes back.",fix:"Set the elbow bend at the start and keep it. Lighter until it holds."},{error:"Your lower back arches high off the bench at the bottom.",fix:"Keep your ribs down and stop the dumbbell higher. Put your feet up on the bench if the arch will not go away."},{error:"The dumbbell drops quickly behind your head.",fix:"Three seconds down, every rep. Fast at the bottom is where the shoulders complain."}],feelIt:"Across your chest and under your armpits. Not your lower back.",easier:"Less weight and a shorter range — stop well before the full stretch while you learn the arc.",harder:"Pause two seconds at the stretch, or the straight-arm version."},"straight-arm-dumbbell-pullover":{setup:["Lie on a bench with your head near the end and your feet flat on the floor.","One dumbbell held by the inside of the top plate with both hands, arms above your chest, nearly straight — a tiny bend at the elbow.","Ribs down, lower back gently on the bench. Lighter than the bent-arm version."],cues:["Lower the dumbbell in an arc behind your head, arms staying nearly straight.","Stop at a comfortable stretch under your armpits — well before the floor.","Pull it back over your chest, arms still nearly straight."],tempo:"3 seconds down · brief pause at the stretch · pull back up under control",breathing:"Breathe in as the dumbbell goes behind your head. Breathe out as you pull it back.",mistakes:[{error:"Your elbows bend more and more as the set goes on.",fix:"That is the weight telling you it is too heavy. Drop it, and keep the tiny bend the same on every rep."},{error:"Your lower back arches high off the bench.",fix:"Keep your ribs down and stop the dumbbell higher. Feet up on the bench helps."},{error:"You chase the floor with the dumbbell.",fix:"Stop where the stretch is comfortable. The last part of the arc is your shoulders, not your chest."}],feelIt:"Under your armpits and across your chest, with the back of your arms holding the position. Not the front of your shoulders, not your lower back.",easier:"The dumbbell bent-arm pullover — bent elbows take the load off the shoulders and elbows.",harder:"Pause two seconds at the stretch, or slow the lowering to four seconds."},"wide-grip-decline-barbell-pullover":{setup:["Legs hooked under the pads of a decline bench, head at the low end.","Bar resting on your upper thighs, hands out near the plates — a very wide grip. Start with the empty bar.","Arms straight with a slight bend at the elbows. Ribs down."],cues:["Raise the bar in an arc over your face and behind your head, arms staying nearly straight.","Stop at a comfortable stretch across your chest — well before the floor.","Bring it back over in the same arc to your thighs."],tempo:"2 seconds over · brief pause at the stretch · 2 seconds back",breathing:"Breathe in as the bar goes behind your head. Breathe out as it comes back.",mistakes:[{error:"Your elbows bend to get the bar past your face.",fix:"Keep the slight bend fixed. If you have to bend more, the bar is too heavy — the empty bar is plenty to begin with."},{error:"You take the bar as far toward the floor as it will go.",fix:"Stop where the stretch is comfortable. The wide grip shortens the range your shoulders have — respect it."},{error:"Your hips lift off the bench as the bar goes back.",fix:"Keep your ribs down and the range shorter. Legs pressing into the pads is what holds you down."}],feelIt:"Across your chest, and under your armpits at the stretch. Not the front of your shoulders, not your lower back.",easier:"The straight-arm dumbbell pullover on a flat bench — one dumbbell, a normal grip, a shorter arc.",harder:"Pause two seconds at the stretch. Add weight only in the smallest steps."},"barbell-front-raise-pullover":{setup:["Lie on a flat bench, feet flat on the floor, bar resting on your upper thighs.","Hands about shoulder width apart, arms straight with a slight bend at the elbows.","Ribs down, lower back gently on the bench. Light weight — the bar passes over your face."],cues:["Raise the bar in an arc over your face and behind your head, arms nearly straight.","Stop at a comfortable stretch across your chest.","Bring it back in the same arc to your thighs, under control the whole way."],tempo:"2 seconds over · brief pause at the stretch · 2 seconds back",breathing:"Breathe in as the bar goes behind your head. Breathe out as it comes back.",mistakes:[{error:"Your elbows bend as the bar passes over your face.",fix:"Keep the slight bend fixed. Use a lighter bar — this is a long lever and needs very little."},{error:"Your lower back arches high off the bench at the stretch.",fix:"Keep your ribs down and stop the bar higher. Feet up on the bench if the arch will not go away."},{error:"The bar speeds up as it goes behind your head.",fix:"Same pace the whole arc. If you cannot control it over your face, the weight is too heavy."}],feelIt:"The front of your shoulders on the way over, then across your chest and under your armpits at the stretch. Not your lower back.",easier:"The straight-arm dumbbell pullover — same arc behind the head, without the part over your face.",harder:"Pause two seconds at the stretch, or slow both halves to three seconds."}},j={"barbell-squat":{setup:["Set the bar just below shoulder height, so you lift it out rather than tiptoe under it.","Bar rests on the muscle across the top of your back, not on the bone at the base of your neck.","Step back two steps. Feet a little wider than your shoulders, toes turned slightly out."],cues:["Take a breath and brace like someone is about to poke your stomach.","Sit down and back at the same time, letting your knees travel forward over your toes.","Push the floor away to stand up. Hips and chest rise together."],tempo:"3 seconds down · pause at the bottom · stand up under control",breathing:"Breathe in at the top and hold it down and up. Breathe out once you're standing.",mistakes:[{error:"Your knees drift toward each other as you stand up.",fix:"Push your knees out toward your little toes on the way up. If they still cave, the weight is too heavy."},{error:"Your lower back rounds at the bottom.",fix:"Stop the rep higher — go only as deep as you can keep your back flat. Depth comes back as your hips loosen."},{error:"Your heels lift and you tip onto your toes.",fix:"Keep your whole foot planted and think about pushing through the middle of it. Widening your stance slightly often fixes it."}],feelIt:"Thighs and glutes doing the work. Your lower back should feel braced and steady, never strained.",easier:"Goblet squat — hold one dumbbell at your chest. The front load makes staying upright much easier.",harder:"Front squat, or add weight in small steps once you can hold the bottom position calmly."},"romanian-dead-lift":{setup:["Stand holding the bar against the front of your thighs, feet about hip width.","Soften your knees slightly and keep them there — this is a hip movement, not a squat.","Pull your shoulders back so the bar stays close to your body."],cues:["Push your hips backwards, as if closing a car door behind you.","Let the bar slide down your thighs, staying in contact the whole way.","Stop when your hamstrings feel tight — that's your depth, wherever it is.","Drive your hips forward to stand up."],tempo:"3 seconds down · no bounce at the bottom · hips forward to stand",breathing:"Breathe in as you lower. Breathe out at the top.",mistakes:[{error:"The bar drifts away from your legs.",fix:"Keep it brushing your thighs the whole way down. A bar out in front is what makes backs sore."},{error:"You bend your knees more and more, so it turns into a squat.",fix:"Fix the knee angle at the start and don't change it. Only the hips move."},{error:"You go for the floor because that's what a deadlift looks like.",fix:"Depth is decided by your hamstrings, not the floor. Most people stop around mid-shin."}],feelIt:"A strong stretch down the back of your thighs. If you feel it mostly in your lower back, you're rounding — reduce the range and the weight.",easier:"Do it with two dumbbells, or with no weight at all, until the hip hinge feels automatic.",harder:"Slow the lowering to 4 seconds, or move to one leg at a time."},"bench-press":{setup:["Eyes roughly under the bar. Feet flat on the floor, planted.","Squeeze your shoulder blades together and down, as if tucking them into your back pockets.","Grip a little wider than your shoulders, wrists stacked straight over your elbows."],cues:["Lower the bar to the lower half of your chest, not to your throat.","Elbows tucked to roughly 45° from your body, not flared straight out.","Press up and very slightly back, toward your face."],tempo:"2–3 seconds down · touch the chest lightly · press up under control",breathing:"Breathe in as the bar comes down. Breathe out as you press.",mistakes:[{error:"The bar bounces off your chest.",fix:"Touch, pause for a beat, then press. If you need the bounce, the weight is too heavy."},{error:"Your elbows flare straight out to the sides.",fix:"Think about bending the bar in half. That tucks the elbows without you having to aim."},{error:"Your backside lifts off the bench.",fix:"Keep it down and drive through your feet instead. Lifting the hips is a sign the load is too much."}],feelIt:"Chest and the back of your arms. Shoulders should feel stable and set, not pinched at the front.",easier:"Dumbbell bench press or push-ups — both let your shoulders find a natural path.",harder:"Pause two seconds on the chest, or add weight once every rep looks the same as the first."},"push-ups":{setup:["Hands under your shoulders, or a touch wider.","Body in one straight line from your head to your heels.","Squeeze your glutes and stomach before the first rep — that's what keeps the line."],cues:["Lower your whole body as one piece.","Elbows travelling back at roughly 45°, not straight out to the sides.","Push the floor away and finish with your shoulder blades spread."],tempo:"2 seconds down · brief pause · push up under control",breathing:"Breathe in on the way down. Breathe out as you push.",mistakes:[{error:"Your hips sag toward the floor.",fix:"Squeeze your glutes harder. If they still sag, move to an incline until you can hold the line."},{error:"Your head reaches the floor before your chest does.",fix:"Keep your chin tucked and lead with your chest. Your head should be the last thing to move."},{error:"You only go down a few centimetres.",fix:"Raise your hands onto a bench or a step and do the full range there. Half a rep trains half the muscle."}],feelIt:"Chest, the back of your arms, and your stomach working to hold the line. Not your lower back.",easier:"Hands on a bench, a table or a wall. The higher your hands, the easier it gets — and it is a real push-up.",harder:"Feet raised, a pause at the bottom, or slow the lowering to 4 seconds."},"body-row":{setup:["Set a bar at about hip height. Hang underneath it with your hands a little wider than your shoulders.","Body in one straight line, heels on the floor.","The more upright you are, the easier this is — start higher than you think you need to."],cues:["Start by pulling your shoulder blades together, before your arms bend.","Pull your chest to the bar, not your chin.","Lower all the way until your arms are straight."],tempo:"1 second up · squeeze for a beat · 2–3 seconds down",breathing:"Breathe out as you pull. Breathe in as you lower.",mistakes:[{error:"Your hips drop and you pull in a banana shape.",fix:"Squeeze your glutes and keep the line. Raising the bar makes this much easier to hold."},{error:"You pull with your arms and your shoulders roll forward.",fix:"Lead with the shoulder blades. Arms are what finish the rep, not what starts it."},{error:"You stop short at the bottom.",fix:"Straighten your arms fully every rep. The stretch at the bottom is where the back work happens."}],feelIt:"Between and around your shoulder blades, and in your upper back. Some forearm work is normal.",easier:"Raise the bar higher, or bend your knees and put your feet flat.",harder:"Lower the bar toward the floor, or put your feet up on a bench."},"leg-press":{setup:["Set the seat so your knees bend to about a right angle at the bottom, no deeper to start.","Feet flat on the middle of the platform, about shoulder width.","Sit right back — your lower back and hips stay against the pad the whole set."],cues:["Lower until your knees are bent about 90°, under control.","Push through your whole foot, not just the toes.","Stop just short of locking your knees at the top."],tempo:"3 seconds down · brief pause · press back up under control",breathing:"Breathe in as the platform comes down. Breathe out as you press.",mistakes:[{error:"Your hips curl up off the seat at the bottom.",fix:"You are going too deep for now. Stop the rep higher — the moment your hips start to lift is past your range."},{error:"You snap your knees straight at the top.",fix:"Stop just short of locked. The muscles should hold the weight at the top, not the joint."},{error:"You put your hands on your knees to help.",fix:"Hold the handles at the side instead. If you need to push your knees, the weight is too heavy."}],feelIt:"Thighs and glutes. Your lower back should feel supported by the pad and do nothing at all.",easier:"Less weight and a smaller range — a shorter, controlled rep beats a deep, wobbly one.",harder:"Slow the lowering to 4 seconds, or add weight in small steps."},"seated-leg-curl":{setup:["Line your knees up with the machine's pivot — the point the lever rotates around.","Pad sits just above your heels, not on your calves.","Back flat against the seat, thigh pad snug so your legs stay put."],cues:["Curl your heels down and under, toward the back of the seat.","Squeeze for a beat at the bottom of the curl.","Let the weight back up slowly until your legs are almost straight."],tempo:"1 second to curl · squeeze for a beat · 3 seconds back",breathing:"Breathe out as you curl. Breathe in as it returns.",mistakes:[{error:"Your hips lift off the seat as you curl.",fix:"Tighten the thigh pad and use less weight. If your hips move, your legs are getting help."},{error:"The weight stack slams down between reps.",fix:"Take three full seconds on the way back. The slow half is where most of the work is."},{error:"Your range gets shorter as the set goes on.",fix:"Drop the weight. Half a curl trains half the muscle, and the last reps are the ones that count."}],feelIt:"The back of your thighs, above the knee. Cramping there is common at first and eases as you get used to it.",easier:"Less weight and a shorter range while you learn where the squeeze is.",harder:"Slow the return to 4 seconds, or work one leg at a time."},"seated-military-press":{setup:["Bench upright, feet flat on the floor, back against the pad.","Bar starts at collarbone height, hands just outside your shoulders.","Wrists stacked straight above your elbows, not bent back."],cues:["Brace your stomach before the first rep — that's what stops you arching.","Press straight up, moving your head back slightly out of the way.","Finish with your arms straight and your upper arms beside your ears."],tempo:"2 seconds down · brief pause at the collarbone · press up under control",breathing:"Breathe in at the bottom. Breathe out as you press up.",mistakes:[{error:"You lean back until it turns into an incline bench press.",fix:"Squeeze your glutes and brace your stomach. If you still lean back, the weight is too heavy."},{error:"You press around your face in a curve to avoid hitting it.",fix:"Tuck your chin as the bar passes, then press straight. The bar travels in a line, your head moves."},{error:"Your wrists bend back under the bar.",fix:"Keep the bar low in your palm, stacked over the forearm bone. A bent wrist is where the ache comes from."}],feelIt:"Shoulders and the back of your arms. Your stomach should feel braced and working.",easier:"Dumbbells instead of a bar — your shoulders find their own path and your head is never in the way.",harder:"Pause a second at the collarbone, or add weight once every rep travels the same line."},"seated-cable-rows":{setup:["Feet flat on the platform, knees slightly bent and kept that way.","Sit tall — sit on your sit bones, not slumped back behind them.","Start with your arms straight and let your shoulders reach forward."],cues:["Start the pull with your shoulder blades, before your arms bend.","Pull the handle to your belly button, elbows sliding past your ribs.","Let your arms straighten and your shoulders reach forward again at the end."],tempo:"1 second to pull · squeeze for a beat · 3 seconds back out",breathing:"Breathe out as you pull. Breathe in as it returns.",mistakes:[{error:"Your body rocks backwards and forwards with every rep.",fix:"Keep your torso still and let only your arms and shoulder blades move. Rocking means the weight is too heavy."},{error:"Your shoulders shrug up toward your ears.",fix:"Think about pulling your shoulder blades down and together, not up."},{error:"You stop before your arms are straight.",fix:"Let it stretch all the way out every rep. The reach at the end is part of the movement, not the rest between reps."}],feelIt:"Between and around your shoulder blades. Some forearm and bicep work is normal.",easier:"Less weight, and focus on keeping your torso completely still.",harder:"Hold the squeeze for two seconds, or slow the return to four."},"v-bar-pull-down":{setup:["Set the thigh pad snug so you stay in the seat when the weight gets heavy.","Take the V handle, sit tall, and lean back just slightly.","Pick a lean and keep it — the lean should not change during the set."],cues:["Start by pulling your shoulders down, away from your ears.","Bring the handle to the top of your chest.","Drive your elbows down toward your pockets, not backwards.","Control the weight all the way back up until your arms are straight."],tempo:"1 second to pull · squeeze for a beat · 3 seconds back up",breathing:"Breathe out as you pull down. Breathe in as it goes up.",mistakes:[{error:"You lean further and further back until it becomes a row.",fix:"Fix the lean at the start and hold it. If you have to lean to move the weight, it is too heavy."},{error:"You pull the bar behind your neck.",fix:"Always to the front, to the top of the chest. There is nothing to gain behind the neck and a lot of shoulder to lose."},{error:"The weight yanks your arms straight at the top.",fix:"Take three seconds up. If it pulls you out of the seat, drop the weight."}],feelIt:"The sides of your back, under your armpits. Your arms will work too — that is fine, they should not do all of it.",easier:"Less weight. This is also the machine to learn the pulling motion on before you attempt a pull-up.",harder:"Pause at your chest for two seconds, or slow the return further."},"pull-ups":{setup:["Grip the bar a little wider than your shoulders, palms facing away.","Hang with your arms completely straight.","Squeeze your glutes and stomach so you hang still instead of swinging."],cues:["Pull your shoulders down away from your ears before your arms bend.","Lead with your chest toward the bar.","Lower all the way back to a straight-arm hang."],tempo:"Pull under control · brief pause at the top · 3 seconds down",breathing:"Breathe out as you pull up. Breathe in on the way down.",mistakes:[{error:"You swing and kick your legs to get up.",fix:"Start from a still hang. If you cannot get up without swinging, use the easier version below — that is what it is for."},{error:"You get your chin over the bar with your shoulders rolled forward.",fix:"Lead with the chest and keep your shoulders down. A slightly lower rep done properly is worth more."},{error:"You stop halfway down and go again.",fix:"Straighten your arms fully every rep. The bottom of the movement is where most of the strength is built."}],feelIt:"The sides of your back and your arms. Your stomach works to keep you from swinging.",easier:"Use the assisted machine or a band, or jump to the top and lower yourself as slowly as you can. Lowering slowly is how nearly everyone earns their first pull-up — it is the normal route, not a lesser one.",harder:"Pause at the top, slow the lowering further, or add weight with a belt."},"dumbbell-lunges":{setup:["A dumbbell in each hand, arms relaxed at your sides.","Stand tall with your feet under your hips.","Step about one long stride — too short is what makes the knee ache."],cues:["Step forward and drop your back knee straight down toward the floor.","Front shin close to vertical, chest up.","Push through your front heel to stand back up."],tempo:"2 seconds down · light touch at the bottom · drive up under control",breathing:"Breathe in as you step down. Breathe out as you come back up.",mistakes:[{error:"Your front knee drifts inward as you stand up.",fix:"Push the knee out so it tracks over your middle toes. Slow down and use lighter dumbbells until it stays there."},{error:"You lean forward over your front leg.",fix:"Chest up, eyes ahead. Leaning forward moves the work into your lower back."},{error:"You wobble and cannot find your balance.",fix:"Do them stationary first — stay in one split stance and just go up and down, holding a rack with one hand if you need to."}],feelIt:"The front leg's thigh and glute. The back leg is mostly there for balance.",easier:"No weight at all, and stationary rather than stepping. Hold something for balance — that is a legitimate way to train this.",harder:"Heavier dumbbells, walking lunges, or a pause at the bottom."},"step-ups-with-dumbbells":{setup:["A box or bench around knee height. Lower is fine — start lower than you think.","A dumbbell in each hand, arms at your sides.","Place your whole foot on the box, not just the front half."],cues:["Drive up through the foot that is on the box.","Stand all the way up before you come back down.","Lower yourself under control — do not just drop."],tempo:"Drive up · stand tall for a beat · 3 seconds down",breathing:"Breathe out as you step up. Breathe in as you lower.",mistakes:[{error:"You bounce off your back foot to get up.",fix:"The leg on the box does the work. Try touching your back toe down lightly between reps instead of pushing off it."},{error:"Your hips shoot up and you lurch onto the box.",fix:"The box is too high. Drop to a lower one — a step you can control beats a tall one you cannot."},{error:"You drop back down and land hard.",fix:"Take three seconds to lower. Landing hard is where knees get sore."}],feelIt:"The leg on the box — thigh and glute. Both should be working by the end of the set.",easier:"A lower box and no dumbbells at all.",harder:"A higher box, heavier dumbbells, or a pause at the top of each rep."},crunches:{setup:["On your back, knees bent, feet flat on the floor.","Hands crossed over your chest — easier than behind your head, and safer for your neck.","Look at a point on the ceiling and keep looking there."],cues:["Curl your ribs toward your hips.","Lift only your shoulder blades off the floor.","Lower back down slowly instead of dropping."],tempo:"2 seconds up · squeeze for a beat · 2 seconds down",breathing:"Breathe out as you curl up. Breathe in as you lower.",mistakes:[{error:"You pull on your neck with your hands.",fix:"Cross your hands over your chest instead. If your neck aches, that is where the problem is."},{error:"You sit all the way up.",fix:"Only the shoulder blades come off the floor. Sitting further uses your hips, not your stomach."},{error:"You go fast and bounce off the floor.",fix:"Two seconds up, two seconds down. Twelve slow reps beat forty fast ones."}],feelIt:"Your stomach, right through the middle. If you feel it mostly in the front of your hips, you are coming up too far.",easier:"A smaller range — even lifting just your shoulders an inch counts while you find the movement.",harder:"Slow it down further, pause at the top, or hold a light weight on your chest."}},D={...j,...C,...A},x=t=>t?D[t]:void 0,y=({children:t})=>e.jsx("p",{className:"text-[11px] font-bold text-muted-foreground mb-2",children:t}),S=({c:t,compact:o})=>e.jsxs("div",{className:"divide-y divide-border/35 border-t border-border/35",children:[e.jsx(p,{k:"Tempo",v:t.tempo}),!o&&e.jsx(p,{k:"Breathing",v:t.breathing})]}),q=({m:t})=>e.jsxs("li",{className:"py-2.5",children:[e.jsxs("p",{className:"flex gap-2 text-[13px] font-semibold leading-snug",children:[e.jsx(L,{size:13,className:"shrink-0 mt-px text-ember-light","aria-hidden":!0}),t.error]}),e.jsx("p",{className:"mt-1 pl-[21px] text-[13px] text-muted-foreground leading-snug",children:t.fix})]}),O=({slug:t,className:o})=>{const r=x(t);return r?e.jsxs("div",{className:u("space-y-5",o),children:[e.jsx(S,{c:r}),e.jsxs("section",{children:[e.jsx(y,{children:"Set up"}),e.jsx("ul",{className:"space-y-1.5",children:r.setup.map((n,s)=>e.jsxs("li",{className:"flex gap-2.5 text-[13px] text-foreground/85 leading-snug",children:[e.jsx("span",{className:"shrink-0 h-1.5 w-1.5 rounded-full bg-muted-foreground/50 mt-[7px]","aria-hidden":!0}),e.jsx("span",{children:n})]},s))})]}),e.jsxs("section",{children:[e.jsx(y,{children:"Key cues"}),e.jsx("ol",{className:"space-y-1.5",children:r.cues.map((n,s)=>e.jsxs("li",{className:"flex gap-2.5 text-[13px] text-foreground/85 leading-snug",children:[e.jsx("span",{className:"shrink-0 h-5 w-5 rounded-full bg-gold/15 text-gold text-[11px] font-black flex items-center justify-center mt-px",children:s+1}),e.jsx("span",{className:u(s===0&&"text-foreground font-semibold"),children:n})]},s))})]}),e.jsxs("section",{children:[e.jsx(y,{children:"Common mistakes"}),e.jsx("ul",{className:"divide-y divide-border/35",children:r.mistakes.map((n,s)=>e.jsx(q,{m:n},s))})]}),e.jsxs("div",{className:"divide-y divide-border/35 border-t border-border/35",children:[e.jsx(p,{k:"Feel it",v:r.feelIt}),e.jsx(p,{k:"Easier",v:r.easier}),e.jsx(p,{k:"Harder",v:r.harder})]})]}):null},U=({slug:t})=>{const o=x(t);return o?e.jsxs("div",{className:"space-y-2",children:[e.jsx(S,{c:o,compact:!0}),o.cues[0]&&e.jsxs("p",{className:"flex gap-2 text-[12.5px] text-foreground/90 leading-snug",children:[e.jsx("span",{className:"shrink-0 h-4 w-4 rounded-full bg-gold/15 text-gold text-[10px] font-black flex items-center justify-center mt-px","aria-hidden":!0,children:"!"}),e.jsx("span",{className:"font-semibold",children:o.cues[0]})]}),o.mistakes[0]&&e.jsx("ul",{className:"list-none",children:e.jsx(q,{m:o.mistakes[0]})})]}):null};export{U as E,F as I,I as a,W as b,Y as c,x as d,O as e,z as f};
